export default [{"id":29,"question":"ذهبنا مع بعض الأصدقاء إلى رحلة خارج الرياض، وبالضبط في الثمامة، فخرجنا يوم الأربعاء في الليل، فحينما جاء وقت النوم نمنا، فلما أصبحنا على يوم الخميس، وجدتُ نفسي قد احتلمتُ، وأصبحت علي جنابة، ونحن عددنا أربعة، ولا يوجد معنا غير جالون ماء للشرب والأكل، فأخبرتُ أحد الأصدقاء بما حدث لي، فقال لي: تعفَّر، وصلِّ معنا الفجر، يجوز لك ذلك، فعملتُ ما أمرني به، ولما جاء، وقت صلاة الظهر شككتُ في الأمر، ولم أصلِّ معهم جميع الأوقات من فجر يوم الخميس إلى عشاء ليلة السبت في نهار الجمعة، فلما ذهبنا إلى الرياض صليتها بعد أن اغتسلتُ، وبدون أن أقْصُر في جميع الأوقات فيما فاتني، فماذا عليَّ في ذلك؟","title":"حكم من احتلم في صحراء ولم يجد ماءً للغسل","answer":"الجواب: الواجب عليك إذا وقع مثل هذا أن تنظر، إن وجدتَ ماءً قريبًا منك تستطيع الغسل به فعلتَ، ووجب عليك ذلك، فإن لم تجد تيممت كما قال لك صاحبك، تعفَّرت بالتراب وكفى؛ لأن الله  يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43]، ويقول النبي ﷺ: وجُعِلَت لي الأرض مسجدًا وطهورًا فأيما رجل من أمتي أدركته الصلاة فعنده مسجده وطهوره، ويقول ﷺ: وجُعِلَ التراب لي طهورًا إذا لم نجد الماء، فمن لم يجد الماء فالصعيد، وضوءه.\nفعليك إذا فقدتَ الماء في أي مكان أن تتيمم، وتضرب التراب بيديك، وتمسح به وجهك، وكفيك كما أمر الله  وتصلي، وليس عليك إعادة، تجزئ، وإذا كنتَ في محل فيه ماء وجب عليك الغسل، وإذا كان الوقت باردًا سخَّنته بالنار، وإذا لم تجد نارًا وخشيت على نفسك بسبب شدة البرد؛ تيممتَ وصليت، وأجزأك، والحمد لله.\nوأما تركك لصلاة معهم المدة الطويلة يوم الخميس والجمعة، فهذا غلط وخطأ منك، فعليك التوبة إلى الله من ذلك، والندم على ما مضى منك، وعدم العودة إلى ذلك، وقد أحسنتَ في قضاء الصلاة لَمَّا تمكنت من الماء؛ ولكنك أخطأت في تركها، وفي التأخير.\nفالواجب التوبة من ذلك، وألا تؤخرها عن وقتها، إن وجدتَ ماءً فاغتسل، وإلا فتيمم وصلِّ، ولا تؤخرها عن وقتها أبدًا.","link":"https://binbaz.org.sa/fatwas/2809/حكم-من-احتلم-في-صحراء-ولم-يجد-ماء-للغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0002.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":44,"question":"أنا أعمل موظفًا في الهاتف السعودي، والمراقب المسئول يمنعني من تأدية الصلاة في وقت العمل، مع العلم أن المسجد مقابل مبنى الهاتف، فما هو رأي سماحتكم في ذلك؟","title":"حكم تأخير الصلاة للموكّل بأمانة أو حراسة","answer":"الجواب: الواجب عليك أن تصلي في محلك؛ لأنك تشبه الحارس، الحارس إذا كان حارسًا على مال، أو على مزرعة، أو غيرها، يصلي في محله، ولا يلزمه جماعة، إذا كان ذهابه إلى الجماعة يفوِّت الحراسة، وربما جاء في الهاتف ما يدعو إلى الحذر، والحاصل أن من وُكل إليه الهاتف المهم للمسلمين يكون بمثابة الحارس الذي يصلي عند محل الحراسة.\nأما أن يضيع الوقت، لا، يجب أن يصلي في الوقت، ولو قدِّر أن الهاتف تكلم؛ فإن مدة الصلاة مدة قليلة، خمس دقائق أو أقل من ذلك.\nفالواجب أن تصلي الصلاة في الوقت، ولا يجوز أن تُهمل من أجل الحراسة، ولا من أجل الهاتف.\nفإذا كان هناك ضرورة وجب التناوب، فيُجعل هذا الحارس ينوب بعض الوقت، ثم يذهب ويصلي، ويأتي الحارس الآخر وقد صلى، فينوب عنه.\nأما أن يوكَل إليه حراسة تمنعه من الصلاة؛ فهذا ظلم، ولا يجوز.","link":"https://binbaz.org.sa/fatwas/2824/حكم-تاخير-الصلاة-للموكل-بامانة-او-حراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0017.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":70,"question":"تقول في سؤالها الأخير: هل تتلاقى الأرواح بعد الموت؟","title":"هل تتلاقى الأرواح بعد الموت في القبور؟","answer":"الجواب: الله أعلم، جاء فيها مراءٍ كثيرة في التلاقي، والله أعلم ، جاء أشياء تدل على أنها قد تتلاقى روح المؤمن مع روح المؤمن الحي في النوم، وقد وجد في هذا أمثلة كثيرة تدل على وجود ذلك، ولكن ليس في هذا أحاديث صحيحة عن النبي ﷺ تدل على ذلك فيما نعلم، ولكن وُجد منامات تدل على هذا وعلى وقوعه.","link":"https://binbaz.org.sa/fatwas/2988/هل-تتلاقى-الارواح-بعد-الموت-في-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0047.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":76,"question":"الادِّعاء أن ستة مليارات من الناس المنتشرين على سطح البسيطة سيكون مصيرهم النار، هكذا بموجب فتوى لا تستند إلى الحقِّ والعدل، ويقول: إن أتباع جميع الدِّيانات السَّماوية باستثناء المُحَرِّفين لكتاب الله سيذهبون إلى الجنة فيما إذا عملوا صالحًا؛ تحقيقًا لقوله تعالى: إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَادُوا وَالنَّصَارَى وَالصَّابِئِينَ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَالِحًا فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ [البقرة:62] إلى آخر ما قال.فما توجيهكم؟","title":"ما مصير أتباع الرسل قبل الإسلام؟","answer":"الجواب: مَن آمن بالله واليوم الآخر من جميع الأمم واتَّبع الرسلَ لا شكَّ أنه إلى الجنة: إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَادُوا وَالنَّصَارَى وَالصَّابِئِينَ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَالِحًا فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ، فمَن آمن بالله ورسله من هذه الأمة، ومن بني إسرائيل، ومن اليهود، والنَّصارى، ومن غيرهم من الأمم؛ كلهم إلى الجنة، وكل مَن تابع الرسلَ من أولهم إلى آخرهم فهو إلى الجنة، ومَن عصاهم وخالفهم فهو إلى النار.\nولا شكَّ أنَّ أكثر الخلق إلى النار، وأقلَّهم إلى الجنة، كما قال جلَّ وعلا: وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ [يوسف:103]، وقال جلَّ وعلا: وَإِنْ تُطِعْ أَكْثَرَ مَنْ فِي الْأَرْضِ يُضِلُّوكَ عَنْ سَبِيلِ اللَّهِ [الأنعام:116]، وقال سبحانه: وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ فَاتَّبَعُوهُ إِلَّا فَرِيقًا مِنَ الْمُؤْمِنِينَ [سبأ:20].\nلكن في آخر الزمان: إذا رفع اللهُ القرآنَ، وأرسل الريحَ التي تقبض أرواح المؤمنين والمؤمنات لا يبقى إلَّا الأشرار، فعليهم تقوم الساعة، وهم من أهل النار؛ لأنهم بقوا على الشرك بالله وعبادة غيره، فعليهم تقوم الساعة -نسأل الله العافية: لا تقوم الساعةُ حتى لا يُقال في الأرض: الله، الله، وفي روايةٍ: حتى لا يُقال في الأرض: لا إله إلَّا الله -نسأل الله السلامة.\nوأما القول بأنَّ جميع أهل الأرض في النار، فهذا كلامٌ باطلٌ، بل مَن آمن بالله واليوم الآخر فهو من أهل الجنَّة، وإنما يكون من أهل النار مَن كفر بالله وخالف أمره، لكن في آخر الزمان بعد رفع الكتاب العزيز، وبعد موت المؤمنين والمؤمنات؛ يبقى الأشرار، وعليهم تقوم الساعة، وهم من أهل النار -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3042/ما-مصير-اتباع-الرسل-قبل-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0053.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":124,"question":"سائل يقول: ما الأمور التي يستطيع العبدُ بها الخلاص من المعاصي؟","title":"ما أسباب تجنب المعاصي؟","answer":"الجواب: مثلما تقدم: لزوم التقوى، أن يلزم طاعة الله، ويتذكر الوقوف بين يدي الله، ويعلم أنه خُلق ليعبد الله ويُطيعه، فيُحاسِب نفسه، فبهذا يُعينه الله، ويقيه شرَّ المعاصي، بالتَّذكر، ومُراقبة الله، وكونه يعلم أنه مسؤولٌ وأنه موقوفٌ بين يدي الله، وأنَّ هذه الدار دار العمل، وليست دار اللَّهو والغفلة، فإذا تذكَّر هذه الأمور وراقب الله؛ أعانه الله على ترك المعاصي، وعلى الاستقامة على طاعة الله.","link":"https://binbaz.org.sa/fatwas/3622/ما-اسباب-تجنب-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0109.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":132,"question":"إذا تاب العبدُ من معصيةٍ ارتكبها، وبعد فترةٍ عاد إليها، ثم تاب، لكن أيضًا بعد التوبة بفترةٍ يعود إلى المعصية، فما حكم ذلك؟ وبماذا تنصحونه؟","title":"حكم من يتوب من المعصية ثم يعود إليها","answer":"الجواب: إذا تاب من المعصية محا الله عنه المعصية، إذا تاب صادقًا مُحيت المعصية بالتوبة، فالتوبة تَجُبُّ ما قبلها، وإذا عاد إليها من جديدٍ صار الإثمُ من جديدٍ على المعصية الجديدة، وأما الأولى التي تاب منها توبةً صادقةً فقد مُحيت عنه، فكل توبةٍ تمحو ما قبلها، ويبقى عليه الجديد.\nفعليه أن يُلاحظ التوبة، ويلزمها، ويجتهد في سلامته من الذنوب، وأما التوبة فتجُبُّ ما قبلها، فلا يؤخذ بالذنب الأول إذا تاب منه توبةً صادقةً.","link":"https://binbaz.org.sa/fatwas/3659/حكم-من-يتوب-من-المعصية-ثم-يعود-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0121.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":161,"question":"رجلٌ أسرف على نفسه، ولكنه تاب إلى ربِّه، ومع هذا فهو خائفٌ من الذنوب السَّابقة، مما سبب له الخوف الذي يُؤدي به إلى الوساوس، أرجو إرشاد هذا ليتخلص من الوساوس؟","title":"بم يُنصح من تاب ويخاف الذنوب السابقة؟","answer":"الجواب: إذا أسرف الإنسانُ على نفسه، ثم هداه الله ومَنَّ عليه بالتوبة فليحمد الله، وليعلم أنَّ الله جلَّ وعلا إنما مَنَّ عليه بالتوبة رحمةً منه سبحانه وفضلًا منه؛ ليُطهره وليغسله من المعايب، فليحمد الله، وليُبْشِر بالخير، وليحذر الشيطان ونزغاته، فإن الشيطان قد يُوقعه في وساوس وفي ظنونٍ سيئةٍ فليحذر ذلك، ولا يُطع عدوَّ الله، فالله جلَّ وعلا أخبر أنَّ العبد إذا تاب وآمن وعمل صالحًا تاب الله عليه، وبدَّل سيئاته حسنات، قال سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، وفي الحديث الصحيح: التَّائِب من الذنب كمَن لا ذنبَ له، فالتائب يغفر الله له سيئاته، ويمحو عنه أخطاءه.\nفعليك يا أخي بالتوبة ولزومها، واحذر الوساوس والظنون السَّيئة التي حرَّمها الله عليك.","link":"https://binbaz.org.sa/fatwas/3699/بم-ينصح-من-تاب-ويخاف-الذنوب-السابقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0155.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":198,"question":"سائلٌ يقول: احتلم وجاءت صلاةُ الفجر، ولعدم وجود الملابس وشدَّة البرد ما استطاع أن يغتسل، فترك حتى جاء الظهرُ، حيث تمكَّن من وجود الملبس والطّهور، فما الحكم؟","title":"حكم من أخّر الغُسْل والصلاة لشدة البرد","answer":"الجواب: الواجب عليه إذا لم يتيسر له الماء الدَّافئ ولا اللباس أن يتيمم بالتراب: يضرب الترابَ بيديه بنية الجنابة ونية الحدث الأصغر –الوضوء- ويمسح وجهه وكفَّيه ناويًا الجنابة والوضوء جميعًا، ويُصلي على حسب حاله، ولا يُؤخِّر الصلاة أبدًا، وإذا أخَّرها أثم، وعليه الغسل، ويقضي الصلاة التي عليه، لكن يلزمه أن يُصلي في الوقت ولو بالتيمم، وإذا أمكنه أن يُسخن الماء وأن يجد الملبس الذي يُعينه على الدفء وجب عليه ذلك، وإلا صلَّى بالتيمم ولا يُؤخِّر الصلاة عن وقتها.","link":"https://binbaz.org.sa/fatwas/3796/حكم-من-اخر-الغسل-والصلاة-لشدة-البرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0205.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":232,"question":"لي نفسٌ تُحبّ الخير، ولكنها ضعيفةٌ لا تثبت أمام المعصية، فكلما رأيتُ معصيةً ضعفت أمامها، فهل هناك دواء أو شفاء لذلك تدلونا عليه؟","title":"ما دواء الضعف أمام المعاصي؟","answer":"الجواب: نعم، قال الله تعالى: وَخُلِقَ الْإِنْسَانُ ضَعِيفًا [النساء:28]، لكن الله أعطاك أسلحةً حتى تقوى، أعطاك الأسلحة التي بها يقوى قلبُك، وهي طاعة الله، والإكثار من ذكره، والتفكر في عظمته وما له من الحقِّ عليك، وأنك صائرٌ إليه، وأنك مسؤولٌ: فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ ۝ عَمَّا كَانُوا يَعْمَلُونَ [الحجر:92- 93]، وأنك مستحقٌّ للعقاب على سيئاتك، وللثواب على طاعتك، ففكِّر ولا تتبع الهوى فيُضلك عن سبيل الله.\nومعلوم أنَّ النفس أمارةٌ بالسوء إلا ما رحم الله، فلا تُجبها إلى هواها، قال تعالى: وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى ۝ فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى [النازعات:40- 41]، فمتى دعتك إلى المعصية فذكّرها بأنَّ الخطر عظيم، وأنها منهية عن معصية الله، وأنها متوعدة بغضب الله وعقابه، إلا أن يعفو الله، وأنت لا تدري هل تموت على ذلك؟ هل يُعفى عنك أو تُعذب؟\nفجاهدها وذكّرها، واحذر مغبة التَّساهل، فإذا وُفِّقْتَ لهذا؛ أعانك الله عليها، وسلمتَ من شرِّ هذه النفس.","link":"https://binbaz.org.sa/fatwas/4090/ما-دواء-الضعف-امام-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0242.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":235,"question":"يقول أنه شابٌّ، وتمر عليه فترات في اليوم يحسّ فيها بزيادةٍ في الإيمان، وفترات أخرى يحسّ فيها بأنَّ الإيمان ينقص، فيسأل ويقول: ما الأسباب التي تُؤدي إلى زيادة الإيمان وإلى نقصانه؟","title":"ما الأسباب التي تؤدي لزيادة الإيمان ونقصه؟","answer":"الجواب: هذه الدنيا هي دار الابتلاء والامتحان، فهي مختبرٌ، يُبتلى فيها الإنسانُ بما يزيد إيمانه، وبما ينقص إيمانه، فتارةً يتلو القرآن، ويتدبر القرآن، ويُكثر من ذكر الله؛ فيزيد إيمانه، وتارةً يصحب الأخيار، ويستفيد من علمهم وصحبتهم الطيبة؛ فيزداد إيمانه، ويُجاهد في سبيل الله، ويأمر بالمعروف، وينهى عن المنكر، ويدعو الناس إلى الخير؛ فيزداد إيمانه، وتارةً يُبتلى بجُلساء سوءٍ، بالغفلة عن الله، بالإقبال على زهرة العاجلة؛ فيضعف الإيمان، وينقص إيمانه.\nفالإنسان في هذه الدار بين مدٍّ وجزرٍ، فكلما شُغل بآخرته وبالأعمال الصَّالحة زاد إيمانه، وكلما شُغل بضدِّ ذلك نقص إيمانه.\nوالإيمان عند أهل السنة والجماعة يزيد وينقص، خلاف ما تقوله الخوارج والمعتزلة، فأهل السنة والجماعة عندهم الإيمان قولٌ وعملٌ وعقيدةٌ، يزداد بالطاعات، وينقص بالمعاصي، فكلما اجتهد في الطاعات، وذكر الله، وصُحبة الأخيار، وأنواع الخير؛ زاد إيمانه وقوي، وكلما شُغل بأمورٍ أخرى: من الغفلة، والإعراض عن المذاكرة، وعن صحبة الأخيار، والإقبال على شهوات الدنيا وزينتها؛ ضعف إيمانُه، ورقَّ إيمانه، وهو بين مدٍّ وجزرٍ، وعلى خطرٍ إذا مال إلى ما يُضعف الإيمان، وعلى خيرٍ عظيمٍ إذا التزم بما يُقوي إيمانه.\nفعلى المؤمن أن يحذر أسبابَ النقص، وليجتهد في أسباب الزيادة، وذلك بالإقبال على القرآن الكريم والسنة المُطهرة، والاستكثار من الطاعات، وأنواع الذكر، والاستغفار، والتوبة، وصحبة الأخيار، والحذر من قرب الأشرار وصحبة الأشرار، والحذر من الغفلة، وطاعة النفس الأمَّارة بالسوء، والإقبال على الملذَّات والشهوات، مُتناسيًا أمر الآخرة، وأمر الجنة والنار، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/4093/ما-الاسباب-التي-تودي-لزيادة-الايمان-ونقصه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0245.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":236,"question":"كيف نُرشد الشباب إلى أن يستغلوا كلَّ الوقت فيما يُرضي الله من قولٍ وعملٍ، علمًا بأنَّ هناك مَن يُعارض هذا؛ حيث يقول: ليس كل شيء دينًا، أو: ليست الحياة كلها يجب فيها أن نلتزم فيها بهذا الشيء، فهو يفصل بين الدِّين والدنيا؟ فما رأي فضيلتكم؟","title":"ما النصيحة للشَّباب في قضاء الأوقات؟","answer":"الجواب: النَّصيحة للشباب وغير الشباب مطلوبة؛ لأنَّ النصيحة متى أُهملت غلب على النفوس الهوى وحبُّ العاجلة وحبُّ الراحة وحبُّ الشهوات، فالنَّصائح كالسياط التي يُجاهد بها الإنسان، ويُقاد بها إلى الخير؛ تُرقق قلبه، وتُذكره بالآخرة، فلا بدّ من النَّصيحة والتَّوجيه والدَّعوة، وإلا ضاعت الحياةُ بالغفلات والشَّهوات.\nولهذا شرع الله التَّذكير ودعا إليه فقال سبحانه: وَذَكِّرْ فَإِنَّ الذِّكْرَى تَنْفَعُ الْمُؤْمِنِينَ [الذاريات:55]، وقال: فَذَكِّرْ إِنَّمَا أَنْتَ مُذَكِّرٌ [الغاشية:21]، فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَى [الأعلى:9]، وَلَوْ أَنَّهُمْ فَعَلُوا مَا يُوعَظُونَ بِهِ لَكَانَ خَيْرًا لَهُمْ وَأَشَدَّ تَثْبِيتًا ۝ وَإِذًا لَآتَيْنَاهُمْ مِنْ لَدُنَّا أَجْرًا عَظِيمًا  ۝  وَلَهَدَيْنَاهُمْ صِرَاطًا مُسْتَقِيمًا [النساء:66- 68].\nفالعبرة والتذكير فيها الخير العظيم، والمصلحة العظيمة، والنبي عليه السلام يقول: الدِّين النَّصيحة، هكذا يقول النبيُّ ﷺ: الدين النصيحة، الدين النصيحة يُكررها ثلاثًا، قيل: لمَن يا رسول الله؟ قال: لله، ولكتابه، ولرسوله، ولأئمة المسلمين، وعامَّتهم رواه مسلمٌ بدون تكرار، ولكن جاء مُكرَّرًا في روايةٍ أخرى عند أبي دواد وغيره؛ لتدل على الأهمية.\nفالنصيحة مطلوبة لا بدّ منها، ولكن مع النَّصيحة لا بدّ من الغفلة بعض الشيء، في حديث حنظلة لما دخل على النبيِّ ﷺ قال: يا رسول الله، نافق حنظلة، قال: لم ذاك؟! قال: نكون عندك فتُذكرنا الجنة -أو قال: الآخرة- كأنا نراها رأي العين؛ فترقّ قلوبُنا، فإذا خرجنا عافسنا النساء والأولاد والضّيعات ونسينا كثيرًا، فقال عليه الصلاة والسلام: لو أنَّكم تدومون على ما تكونون عندي لصافحتكم الملائكةُ في طرقاتكم، وعلى فُرشكم، ولكن يا حنظلة ساعة وساعة، فلا بدّ من وجود شيءٍ من مشاغل الدنيا: من طلب الرزق، من التحدث مع الأهل والأولاد، من البيع والشراء، إلى غير ذلك.\nفالساعات التي فيها طلب الرزق والجلوس مع الأهل تُعتبر خوضًا لا تضرُّ العبد، ما لم يأثم فيها، ما لم يخلطها بالحرام: من الغيبة، والنميمة، والكذب، وشهادة الزور، وغير هذا مما حرَّم الله.\nأما الدَّعوة إلى الله، والتذكير، والنصيحة، والحرص على حفظ الوقت، فهذا أمرٌ مطلوبٌ، ومع هذا كله لا بدّ من شيءٍ، لا بدّ من ساعاتٍ لحاجات الإنسان، لا تضرُّه، وقد تُعينه على الخير.\nولهذا قال ﷺ: ولكن ساعة وساعة يعني: ساعة للدين والعمل والجد، وساعة للدنيا وأعمالها: من تجارةٍ، وزراعةٍ، وغير هذا مما يكون مع الأهل والأولاد، والله المُستعان.","link":"https://binbaz.org.sa/fatwas/4106/ما-النصيحة-للشباب-في-قضاء-الاوقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0246.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":281,"question":"يوجد كثيرٌ من الشباب يُصلِّي، ولكنه لا يحضر قلبه في الصلاة، فهو يسهو عن صلاته، فما نصيحتكم إلى هؤلاء الشباب حتى تتم صلاتهم؟","title":"ما النصيحة لتحقيق الخشوع في الصلاة؟","answer":"الجواب: الواجب على المؤمن الإقبال على صلاته، وأن يتذكر أنه بين يدي الله، وأنه يُناجي الله، كما قال النبيُّ ﷺ: إذا قام أحدُكم في الصلاة فإنه يُناجي الله، فأنت يا عبدالله تُناجي ربَّك في الصلاة، وقائم بين يديه، فجديرٌ بك أن تُقبل على صلاتك، وأن تطرح بصرك إلى مواضع سجودك، وأن تستشعر في قلبك أنك بين يدي الله العظيم الجليل، حتى تخشع له، وتطمئن إليه، وتُعظّم كتابه وعبادته. وتحذر عدوك الشيطان، وإذا غلبك هذا العدو فانفُثْ عن يسارك ثلاث مرات وقل: \"أعوذ بالله من الشيطان الرجيم\"، ثلاث مرات، فقد اشتكى عثمان بن أبي العاص الثَّقفي إلى النبي ﷺ وقال: إنَّ الشيطان لبَّس عليَّ صلاتي، فقال له: انفث عن يسارك ثلاث مرات وقل: أعوذ بالله من الشيطان الرجيم، ففعل ذلك فعافاه الله.\nفإذا غلب هذا العدو عليك وأنت في الصلاة فانفث عن يسارك ثلاث مرات وقل: \"أعوذ بالله من الشيطان الرجيم\"، ولا يضرُّك، وهذا من العلاج العظيم النبوي، وهو حديثٌ ثابتٌ عن النبيِّ ﷺ، رواه الإمام أحمد وغيره.\nس: هل هذا النَّفث عند كل صلاةٍ؟\nالشيخ: إذا غلب عليه الوسواس، إذا أحس بالوساوس وكثرت عليه؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/4279/ما-النصيحة-لتحقيق-الخشوع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0328.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":282,"question":"أنا شابٌّ أحاول إذا كنتُ أقرأ القرآن أو أُصلي أو أتذكر حال المسلمين أن أبكي، ولكن لا أستطيع، فما أسباب ذلك؟ وما العلاج؟","title":"ما أسباب عدم الخشوع والبكاء؟ وما العلاج؟","answer":"الجواب: لهذا أسبابٌ كثيرةٌ، عدم البكاء له أسبابٌ، منها: قسوة القلوب بسبب المعاصي والذنوب، فإنَّ القلوب إذا قست قلَّت دمعةُ العين، وإذا حاسب نفسَه واتَّقى الله وترك معصيته واستقام على أمره خشع قلبه، ودمعت عينه.\nومن ذلك: الغفلة بالوساوس التي تعرض على قلبه هاهنا وهاهنا حتى تشغله عن الخشوع ودمع العين، فقد يكون في نفسه تقيًّا، ولكن تغلب عليه الوساوس حتى تشغله عن ذكر الله، وعن تعظيمه، وعن الخشوع بين يديه، وقد يُبتلى بأفكارٍ ترد عليه تشغله أيضًا.\nفينبغي أن يجمع قلبَه على صلاته، وعلى قراءته، وعلى ذكره لله؛ وعند هذا يخشع القلب، وتدمع العين.","link":"https://binbaz.org.sa/fatwas/4280/ما-اسباب-عدم-الخشوع-والبكاء-وما-العلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0329.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":283,"question":"هناك سؤالٌ من طالبين:أحدهما يقول: يُقام في المعاهد أذانُ صلاة الظهر، فأُصليها أحيانًا وأنا على جنابةٍ؛ لأنه من الصَّعب أمام مئات الطلاب والمُدرسين أن أقول لهم هذا، وليس هذا بتكاسُلٍ مني، فمن بعد الفجر أنام، فأستيقظ متأخِّرًا وأضطر أذهب إلى المعهد، فإذا رجعتُ إلى البيت تطهرتُ وصليتُ.والآخر يقول: في أول الصباح من هذا المُخيم عندما استيقظتُ من النوم وجدتُ نفسي على جنابةٍ، وقد كانت تلك الجنابة السادسة لمدة ستة أيام، فهل هذا مرضٌ أو ماذا؟ وهل عليَّ اغتسالٌ؟ مع العلم أنَّه لا توجد أماكن اغتسال في هذا المكان. وجزاكم الله خيرًا.","title":"حكم من صلى على جنابة حياءً من الناس","answer":"الجواب: أما أن يُصلي وهو جنب فهذا من كبائر الذنوب، ومن المُنكرات العظيمة، وإذا فعله لقلَّة اهتمامٍ وعدم مُبالاةٍ، أو استهزاء بالشرع؛ فشأنه خطيرٌ، قد يكون ردَّةً عن الإسلام -نعوذ بالله تعالى- واستهزاء واحتقارًا للشرع، فالمقصد عظيم جدًّا.\nفالواجب الحذر من هذا، وأن يُصلي وعليه حدثٌ! فكيف إذا كان على جنابةٍ؟!\nفالواجب البدار، وإذا لم يكن هناك محلُّ اغتسالٍ في المكان الذي يذهب إليه فالواجب البدار قبل أن يخرج ولو تأخَّر، قبل أن يخرج من محلِّه يغتسل ولو تأخَّر عن عمله أو درسه أو غير ذلك، هذا مُقدَّمٌ على الدرس، ومقدَّمٌ على العمل، ومقدَّمٌ على كل شيءٍ، ولو خُصم عليه مالٌ فالأمر سهلٌ، فلا يجوز له أبدًا أن يخرج من محلِّه وهو على جنابته، إلا إذا كان في المحل الذي يذهب إليه محلٌّ يغتسل فيه.\nوأدهى من هذا وأكبر وأخطر أن يُصلي في جنابةٍ، هذا منكرٌ عظيمٌ، وفسادٌ كبيرٌ، وتساهلٌ بأمر الله، أما إذا وقع عن سخريةٍ وعن احتقارٍ فهذا شأنه الكفر -نعوذ بالله- قال تعالى: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ ۝ لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65- 66] -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/4281/حكم-من-صلى-على-جنابة-حياء-من-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0330.mp3","categories":["الغسل","الطهارة لصحة الصلاة"]},{"id":295,"question":"إذا تاب العبدُ من معصيةٍ ارتكبها، وبعد فترةٍ عاد إليها، ثم تاب، لكن أيضًا بعد التوبة بفترةٍ يعود إلى المعصية، فما حكم ذلك؟ وبماذا تنصحونه؟","title":"حكم من يتوب من المعصية ثم يعود إليها","answer":"الجواب: إذا تاب من المعصية محا الله عنه المعصية، إذا تاب صادقًا مُحيت المعصية بالتوبة، فالتوبة تَجُبُّ ما قبلها، وإذا عاد إليها من جديدٍ صار الإثمُ من جديدٍ على المعصية الجديدة، وأما الأولى التي تاب منها توبةً صادقةً فقد مُحيت عنه، فكل توبةٍ تمحو ما قبلها، ويبقى عليه الجديد.\nفعليه أن يُلاحظ التوبة، ويلزمها، ويجتهد في سلامته من الذنوب، وأما التوبة فتجُبُّ ما قبلها، فلا يؤخذ بالذنب الأول إذا تاب منه توبةً صادقةً.","link":"https://binbaz.org.sa/fatwas/4297/حكم-من-يتوب-من-المعصية-ثم-يعود-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0344.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":411,"question":"عرَّفت أن المعصية هي من مرض القلب، فأرجو أن تدلني على كتابٍ يُبين علاج المعصية، وجزاكم الله خيرًا.","title":"ما علاج القلب للتغلب على المعاصي؟","answer":"الجواب: لا ريب أنَّ أصل المعاصي من مرض القلوب: إما بالانحراف والهوى، وإما بالتَّكبر، وإما بالجهل والغفلة، وأعظم دواء وأحسن كتابٍ لعلاج أمراض القلوب كتاب الله سبحانه وتعالى القرآن الكريم، هو أحسن كتابٍ، وأصدق كتابٍ، وأنفع كتابٍ، وأوضح كتابٍ، فليس بعده كتابٌ، بل هو أعظم الكتب وأشرفها وأحسنها دواءً وبيانًا للدواء.\nفعليك يا أخي، وعلينا جميعًا رجالًا ونساءً، علينا جميعًا أن نُعالج أمراضنا بتدبر القرآن، والإكثار من تلاوته، والمذاكرة فيه بين الزميل وزميله، والمرأة وزميلتها؛ للتفاهم بمعاني كلام الله، ومراجعة التفاسير الطيبة: كتفسير ابن كثير، وابن جرير، وهكذا المختصرات؛ لأن التفاسير تُعين على فهم كتاب الله، هذا أحسن كتابٍ، وأعظم كتابٍ، وأشرف كتابٍ، يقول الله سبحانه في كتابه العظيم: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، ويقول سبحانه: يَا أَيُّهَا النَّاسُ قَدْ جَاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفَاءٌ لِمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِلْمُؤْمِنِينَ [يونس:57].\nفعليك يا أخي بكتاب الله، وعلينا جميعًا بكتاب الله: تلاوةً، وتدبُّرًا، وتعقُّلًا؛ وبذلك تحصل الفائدة العظيمة، ويحصل الدواء، ويحصل الشفاء بتوفيق الله.\nثم سنة الرسول ﷺ وأحاديثه فيها أيضًا من الدواء ما فيها، فهي الوحي الثاني، والأصل الثاني، ومن أحسن الكتب في ذلك الصحيحان: \"صحيح البخاري\" و\"مسلم\"، ثم بعدهما بقية الكتب الستة، ولكن بالنسبة إلى عامَّة الناس المختصر من هذه الكتب: كـ\"رياض الصالحين\" و\"بلوغ المرام\" و\"عمدة الحديث\"، هذه كتب مفيدة، \"منتقى الأخبار\" لابن تيمية، هذه كتب في الحديث مفيدة ومختصرة، ومن أخصرها وأبينها \"رياض الصالحين\"، فصاحبه قد اختار الأحاديث الجيدة في الغالب، واعتنى بذلك، وهو كتابٌ جيدٌ مفيدٌ، وهكذا \"بلوغ المرام\" كتابٌ محررٌ مفيدٌ، و\"عمدة الحديث\" للشيخ عبدالغني المقدسي كتابٌ عظيمٌ، وهكذا \"الترغيب والترهيب\" إذا قرأه طالبُ العلم واختار منه الأحاديث الأولى منه، وهي الأحاديث الصَّحيحة التي يبدأ بها، وهو كتابٌ عظيمٌ، ثم بعد ذلك بعض كتب أهل العلم المؤلفة في هذا، مثل: \"الجواب الكافي\" لابن القيم، ذكر فيه الذنوب: شرَّها ودواءها، سماها \"الدَّاء والدواء\"، وهو كتابٌ جيدٌ لابن القيم رحمه الله، وكتاب \"الفوائد\" لابن القيم أيضًا كتابٌ مفيدٌ ونافع، فهذان الكتابان من خير الكتب فيما أعلم.\nونسأل الله للجميع التوفيق.","link":"https://binbaz.org.sa/fatwas/4828/ما-علاج-القلب-للتغلب-على-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0469.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":422,"question":"أنا شابٌّ تبتُ إلى الله ، ثم استمررتُ في التوبة، وأحسستُ بحلاوة الإيمان، ثم عصيتُ الله، ثم رجعتُ إلى التوبة، فهل أستمر في ذلك؟","title":"ما حكم من تاب من المعصية ثم عاد إليها؟","answer":"الجواب: عليك أن تحمد الله وتشكره على ما مَنَّ عليك من التوبة، وما جرى من المعصية التي عقبتها التوبة؛ يمحوها الله ، وقد سمعت في البحث: إِلَّا مَنْ تَابَ وَآمَنَ [الفرقان:70] من كلام الله ، والله يقول: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، ويقول النبي ﷺ: التائب من الذنب كمَن لا ذنبَ له، فالزم التوبةَ واستقم عليها، واحذر أن يستزلك الشيطانُ مرةً أخرى.\nفعليك بلزوم التوبة، ومُجالسة الأخيار، والحذر من الأشرار، فإنه قد يجرّك الشيطان إلى المعصية، ثم تموت عليها قبل توبتك، احذر أن يجرّك الشيطان إلى المعاصي فتنزل بك المنية وأنت على المعصية: من صدم، أو انقلاب سيارة، أو سكتة، أو غير ذلك. الزم التوبةَ، الزمها قبل أن يهجم عليك الأجلُ، واحذر غرور الشيطان وطاعته، الشيطان يقول: افعل، افعل، وتب، مَن يقول لك أنَّك تتوب؟! قد يُطبع على قلبك، ويقسو قلبك؛ فلا تتوب، قد يهجم الأجلُ عليك وأنت على المعصية ما تبتَ، فتلقى الله بالمعصية.\nفعليك بلزوم التوبة والحذر، وسَلْ ربَّك التوفيق والهداية، فالأمور بيده ، والقلوب بيده جلَّ وعلا، فاضرع إليه دائمًا أن يهديك، وأن يُثبتك، وأن يُعيذك من الشيطان ونزغاته، ومن جُلساء السوء.","link":"https://binbaz.org.sa/fatwas/4846/ما-حكم-من-تاب-من-المعصية-ثم-عاد-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0480.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":423,"question":"ما أكبر الذنوب؟ وما أصغرها؟","title":"ما أكبر الذنوب؟ وما أصغرها؟","answer":"الجواب: أكبر الذنوب: الشرك بالله، هو أعظم ذنبٍ، ثم يلي ذلك: قتل النفس بغير حقٍّ، ثم يلي ذلك: الزنا بزوجة الجار، ثم عقوق الوالدين -نسأل الله العافية- ثم شهادة الزور التي هي من أقبح المحرمات -نعوذ بالله- ثم الأيمان الغموس، الأيمان الفاجرة التي يُقتطع بها حقّ المسلم. ثم بقية كبائر الذنوب: كالربا، وأكل مال اليتيم، والتولي يوم الزحف، وقذف المحصنات الغافلات، وشرب المسكرات، وغير هذا من كبائر الذنوب، وهي كثيرة.\nأما صغائر الذنوب: فهي الذنب الذي نهى الله عنه، لكن لم يرد فيه وعيدٌ بلعنٍ ولا بنارٍ ولا بغضبٍ ولا بحدٍّ في الدنيا، هذه يُقال لها: الصغائر، التي نهي عنها ولكن لم يرد فيها وعيدٌ بنارٍ ولا بغضبٍ ولا بحدٍّ يُقام على صاحبها، فهذه يُقال لها: من الذنوب الصغيرة، وهي معصية ومحرَّمة.","link":"https://binbaz.org.sa/fatwas/4847/ما-اكبر-الذنوب-وما-اصغرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0481.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":424,"question":"رجل يرتكب الذنوبَ من سرقةٍ وزنا وغيره، وقد يسرق ولا يُعيد ما سرقه، وقد يستلف مالًا ولا يُعيده، وقد تراكمت عليه الذنوب، فماذا يجب عليه أن يفعل من ناحية التوبة؟","title":"ماذا يفعل من أراد أن يتوب من ذنوبه؟","answer":"الجواب: عفو الله أوسع، وباب التوبة مفتوح حتى تطلع الشمسُ من مغربها، أو حتى يموت، فعليه البدار بالتوبة والندم والإقلاع الصَّادق من هذه الذنوب، وعليه بذل الوسع في ردِّ الحق إلى أهله، رد الأموال إلى أهلها بكل طريقٍ، فإن جهله ولم يستطع الوصول إليهم تصدَّق بها عنهم للفقراء والمحاويج بالنية عنهم، والله يؤدي عنه سبحانه وتعالى.\nفدواء الذنوب التوبة إلى الله، هذا دواؤها: التوبة الصَّادقة النَّصوح، الصادقة بالندم على الماضي، والإقلاع عن الذنوب، والحذر منها، واتباع التوبة بالعمل الصالح، هكذا يكون الصَّادقون، كما قال : إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُولَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ [الفرقان:70]، وقال سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، وقال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8]، فالتوبة الصاَّدقة يمحو الله بها الذنوب.\nوعلى العبد إذا صدق أن يرد الحقَّ إلى أهله: من سرقةٍ، وخيانةٍ، وغير هذا من الأموال التي أخذها، أو قتلٍ؛ يُسلّم نفسه حتى يُقتل قصاصًا، أو يرضى بالدية منه، حتى يؤدي الحقوقَ التي عليه صادقًا، وإذا جهل أهلَ الحقوق تصدَّق عنهم بالمال الذي سرقه، أو أخذه منهم، أو استلفه منهم وضيَّعه عليهم، إذا لم يعرفهم ونسي محلهم، أو نسي بلادهم، يتصدَّق به عنهم، وإذا علم يرد إليهم حقَّهم بالطريق التي تُوصلها إليهم، ولو ما سمَّى نفسه، يرد إليهم أموالهم بالطريقة التي تمكنه، من غير أن يُسمِّي نفسه، لا حاجة إلى تسمية نفسه.","link":"https://binbaz.org.sa/fatwas/4848/ماذا-يفعل-من-اراد-ان-يتوب-من-ذنوبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0482.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":426,"question":"ما علاج قسوة القلوب الذي كثر في هذا الزمان، فالقرآن يُقرأ والقليل يبكي؟","title":"ما كيفية علاج قسوة القلوب؟","answer":"الجواب: علاجها: التوبة إلى الله، علاج قسوة القلوب التوبة إلى الله، والإكثار من قراءة القرآن، والإكثار من ذكر الله ، والحذر من الذنوب والمعاصي، والتوبة إلى الله منها، ومجالسة الأخيار، والحذر من الأشرار، كل هذا علاج: الإقبال على كتاب الله بتدبُّرٍ، والإكثار من ذكر الله. والإكثار من الصلاة والعبادة. والتوبة إلى الله من الذنوب. والحرص على الكسب الحلال، والبعد عن الحرام. ومجالسة الطيبين الأخيار، فإن لم تجدهم فالزم بيتك، إلا في وقت الصلاة، وإذا ما وجدتَ الأخيار فمن بيتك إلى المسجد، ومن المسجد إلى بيتك، إلا للحاجة الضَّرورية التي تأخذها من السوق. وإذا وجدت الأخيار فالزمهم وجالسهم، وهم الذين يذكرون الله، ويُعينون على طاعته، ويُذكِّرون بحقِّه، ويبتعدون عن المعاصي والشُّرور.","link":"https://binbaz.org.sa/fatwas/4850/ما-كيفية-علاج-قسوة-القلوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0484.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":434,"question":"أُشهد الله  أنني أُحبُّك فيه، وأريد منك أن تُجيب لي على هذا السؤال، وهو أنني شابٌّ ولله الحمد من الشباب الصَّالحين، ولكنني أتحول إلى أن أكون من أتباع الشياطين، حيث إنني أُصاحب بعض الأشرار، فأكون معهم في جميع أعمالهم أو أغلبها، ولكنني عندما أحضر مجالس الصَّالحين أتحول إلى شابٍّ صالحٍ، فما نصيحتكم لي ولأمثالي من الشباب؟ جزاكم الله خيرًا.","title":"بِمَ يُنصح من يتأثر بالصحبة صالحةً أو فاسدة؟","answer":"الجواب:\n\nأما المحبَّة فقد سبق الجواب عن ذلك، نقول: أحبَّك الله الذي أحببتنا له.\nوهنا ملاحظة: قول الإنسان: أنا من الصَّالحين، أو من المؤمنين، ينبغي أن يقول: \"إن شاء الله\"، فأهل السنة والجماعة يستثنون؛ لأن كونه صالحًا أو كونه مؤمنًا والشهادة من نفسه له بذلك محل نظرٍ، قد يكون قصَّر في ذلك وهو لا يدري، ولا يدري ماذا يُختم له به؟ فليقل: أنا من الصالحين إن شاء الله، أو من المؤمنين إن شاء الله؛ تحرزًا مما قد يقع من التقصير: بترك واجبٍ، أو فعل محظورٍ، والصلاح إنما يكمل بأداء حقِّ الله وحقِّ عباده، ومَن الذي يستطيع أن يقول: إني أديتُ حقَّ الله وحقَّ عباده، وهكذا الإيمان مما يتم بأداء حقِّ الله وحقِّ عباده.\nأما ما ذكرتَ: فالواجب عليك يا أخي أن تحذر صحبة الشياطين، وأن تبتعد عنهم، وعليك بصحبة الأخيار حتى تسلم من شرِّ الأشرار، وقد جاء في الحديث عنه عليه الصلاة والسلام -وهو الحديث الصحيح- أنَّ مثل الجليس الصالح ومثل الجليس السُّوء كصاحب المسك ونافخ الكير، فاختر لنفسك أن تكون مع أهل المسك الذي إمَّا أن يُعطيك، وإما أن تبتاع منه، وإما أن تجد منه ريحًا طيبةً، واحذر أن تكون مع أهل الكير: إما أن يحرق ثيابك، وإما أن تجد منه ريحًا خبيثةً.\nوفي الحديث الآخر يقول ﷺ: المرء على دين خليله، فلينظر أحدُكم مَن يُخالل. والشاعر يقول:\n\n\n\t\n\t\t\n\t\t\tعن المرء لا تسأل وسَلْ عن قرينه\n\t\t\tفكل قرينٍ بالمقارن يقتدي\n\t\t\n\t\n\nوجُلساء السُّوء كانوا سبب ضلال أبي طالب عم النبي ﷺ، جلسوا عنده عند موته ولقَّنوه التَّعصب لدين قومه حتى قال للنبي ﷺ: \"أنا على ملة عبدالمطلب\"، وأبى أن يقول: لا إله إلا الله، بأسباب جلساء السوء.\nفالواجب على المؤمن وعلى طالب العلم وعلى كل مسلمٍ أن يحذر جُلساء السوء، وأن يبتعد عنهم، وألا يُصاحبهم، وأن يختار لنفسه أصحاب الخير، فإن لم يجد فليلزم بيته، ولا يخرج إلا لحاجةٍ أو للصلاة أو لما شرع الله من الأمور الأخرى، ولا يتَّخذ أصحابًا يُضلونه ويصدُّونه عن الحقِّ.","link":"https://binbaz.org.sa/fatwas/4858/بم-ينصح-من-يتاثر-بالصحبة-صالحة-او-فاسدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0492.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":439,"question":"يعيش الشابُّ فترات من عمره محافظًا على الطاعات، وبعيدًا عن المعاصي، ولكنه لا يلبث أن يتكاسل ويضعف، فما الأسباب المُساعدة على الثبات على الخير، على شكل نقاطٍ حتى لا أنساها؟","title":"ما الأسباب المعينة في الثبات على الخير؟","answer":"الجواب: هذا يقع من كثيرٍ من الناس، وله أسباب، منها: فتوره عن التعلم والتفقه في الدين والمزيد من العلم، فبسبب ذلك يضعف عن الصبر والثبات؛ لقلة علمه، وقلة اجتهاده في التحصيل.\nومنها: أن يُبتلى بصاحبٍ أو أكثر من الأشرار، فيقوده إلى الشر، ويُثبطه عن الخير، فإنَّ الجليس السَّيئ ضرره عظيم، وخطره كبير، كما قال النبيُّ ﷺ: مثل الجليس الصالح والجليس السُّوء كحامل المسك ونافخ الكير، فحامل المسك إمَّا أن يُحذيك –يعني: يُعطيك شيئًا منه- وإما أن تبتاع منه، وإما أن تجد منه ريحًا طيبةً، ونافخ الكير إمَّا أن يحرق ثيابك، وإما أن تجد منه ريحًا خبيثةً، وهكذا الحديث الآخر: المرء على دين خليله، فلينظر أحدُكم مَن يُخالل، فمن المُهِمَّات: صحبة الأخيار، والزملاء الطيبين.\nومنها: أن يُبتلى بالأسفار إلى البلاد الخبيثة -إلى الخارج- يكون مستقيمًا ثم يُبتلى بالسفر إلى بلاد الكفر: إنجلترا أو فرنسا أو أمريكا أو غير ذلك، فيقع في حبائل الشيطان ودعاة الباطل، فيترك ما كان عليه سابقًا، ويقع في الفواحش والخمور والزنا؛ فيهلك، ولا حول ولا قوة إلا بالله!\nأما مَن صبر على حاله الأولى، واستقام عليها، واجتهد في صحبة الأخيار، واستمر في طلب العلم والتفقه في الدين؛ فإنه في الغالب يبقى على حاله، ويسلم من مكائد الشيطان، ومكائد الأعداء.\nفنصيحتي لطالب العلم ولنفسي ولكل مسلم: أن يلزم الحقَّ، وأن يستقيم عليه، وأن يستمر في طلب العلم والتفقه في الدين وصحبة الأخيار، والحذر من السفر إلى بلاد الكفرة. فهذه النقاط الثلاث من أهم المهمات:\nالاستمرار في العلم، والحرص على المزيد من العلم، والصبر على ما هو عليه من الدين.\nمع الحرص على صحبة الأخيار، والاستقامة على ما هم عليه.\nمع الحذر من السفر إلى البلاد الخارجية التي فيها الشر المنتشر، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/4864/ما-الاسباب-المعينة-في-الثبات-على-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0497.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":474,"question":"الآية: فَامْسَحُواْ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ [المائدة:6] أي من الغبار؟","title":"ما معنى {فَامْسَحُواْ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ}؟","answer":"الجواب: من التراب الصعيد يعني فَتَيَمَّمُواْ صَعِيداً طَيِّباً[المائدة:6]، إذا تيسر فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]","link":"https://binbaz.org.sa/fatwas/6199/ما-معنى-فامسحوا-بوجوهكم-وايديكم-منه","audio":"https://files.zadapps.info/binbaz.org.sa/AYA034.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":475,"question":"الغسل ورد عن رسول الله ﷺ صفتين في صفة الغُسْل، أحسن الله إليك؟","title":"ما صفة الغُسْل الوادرة عن النبي ﷺ؟","answer":"الجواب: المعروف عن عائشة وعن ميمونة هو الوضوء ثم إفاضة الماء، وجاء عن  ميمونة: أنه يغسل قدميه في مكان آخر.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6200/ما-صفة-الغسل-الوادرة-عن-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/3osl035.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":478,"question":"عفا الله عنك يا شيخ، أليس الصحيح ألا يتوضأ ولا يغتسل من غَسَّل ميتًا إذا لم يباشر تغسيله بيده؟","title":"هل يجب الغسل على من غَسَّل ميتًا؟","answer":"الجواب: كيف غَسَّله؟ س: بالقفازين من وراء حائل.  الشيخ: المعروف أن الوضوء من غُسل الميت مستحب، ثبت من حديث عائشة أنه كان يغتسل من غَسْل الميت عليه الصلاة والسلام، وثبت عن زوجة الصدِّيق أن الصحابة  أفتوها بعدم الغُسل لما اشتدّ عليها البرد، دل على أنه معروف عندهم الغسل لولا العذر.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6236/هل-يجب-الغسل-على-من-غسل-ميتا","audio":"https://files.zadapps.info/binbaz.org.sa/3'osl38.mp3","categories":["الغسل","غسل الميت وتجهيزه"]},{"id":480,"question":"الحكمة في الاغتسال لمن غَسَّل ميتًا؟","title":"ما الحكمة في الاغتسال لمن غَسَّل ميتًا؟","answer":"الجواب: لأنه في غسل الميت يوهن القوة، يتفكر الموت وما بعد الموت وتوهن قواه وتضعف قواه، ويصيبه شيء من الضعف؛ فالغسل يجبره وينشّطه ويقوِّيه.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6239/ما-الحكمة-في-الاغتسال-لمن-غسل-ميتا","audio":"https://files.zadapps.info/binbaz.org.sa/3'asl041.mp3","categories":["الغسل","غسل الميت وتجهيزه"]},{"id":825,"question":"شخصٌ رأى في ثوبه أثرَ احتلامٍ، وتذكر أنه رأى في منامه ما سبب هذا منذ أربعة أو خمسة أيام، لا يدري أنه احتلم، ولم يدرِ عن ذلك، وصلَّى صلوات، فلما رأى هذا الأثر اغتسل، فماذا عليه؟ هل يُعيد صلاته التي صلَّاها هذه الفترة وهو لا يدري؟","title":"حكم مَن رأى أثر احتلام مضت عليه أيام","answer":"الجواب: إذا علم أنها مني فعليه أن يُعيد بعد آخر نومةٍ نامها؛ لأن هذا هو المتيقن، فإذا كان مثلًا رآها العصر، وآخر نومةٍ الضُّحى –الصبح- فهو يُعيد الظهر والعصر، وإذا كانت آخر نومةٍ الظهر، وما رآها إلا بعد العصر، يُعيد العصر، وهكذا، يعني: من آخر نومةٍ نامها ثم رأى المني يُعيد الصلاة التي بعد النومة؛ لأن الظاهر أنها من النومة الأخيرة، ولا يعمّم على النومات السَّابقات.","link":"https://binbaz.org.sa/fatwas/20866/حكم-من-راى-اثر-احتلام-مضت-عليه-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0661شخص رأي في ثوبه أثر احتلام وتذكر أنه رأى في منامه ماسبب هذا فما الحكم؟ابن باز.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":835,"question":"ما حكم الرجل يموت على التوحيد وقد خلط عملًا صالحًا وآخر سيئًا؟ هل يُعذَّب في قبره إلى يوم قيام الساعة أم إلى وقتٍ معلومٍ ويُرفع عنه العذاب؟","title":"حكم من مات مُوَحِّدا قد خلط صالحًا وسيئًا","answer":"الجواب: هذا أمره إلى الله، يقول الله سبحانه: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، فأمره إلى الله، تحت مشيئته: إن شاء غفر له وعفا عنه، وإن شاء عذَّبه بعض العذاب في القبر، وبعض العذاب في النار، وإن شاء عذَّبه شيئًا دون شيءٍ ، فأمره إلى الله، هو الذي يعلم أحوال عباده ، لكنه على خطرٍ، مَن مات على السيئات غير تائبٍ هو على خطرٍ في القبر ويوم القيامة -نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/20876/حكم-من-مات-موحدا-قد-خلط-صالحا-وسيىا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0671ما حكم الرجل يموت على التوحيد وقد خلط عملاً صالحاً وآخر سيئاً يعذب في قبره إلى قيام الساعة؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":851,"question":"في حديث الإسراء والمعراج الذي رُوي عنه ﷺ ورد أنه ﷺ رأى أناسًا يُعذَّبون.و هل هناك عذاب قبل يوم القيامة غير عذاب القبر؟ أفيدونا جزاكم الله خيرًا.","title":"هل هناك عذاب قبل القيامة غير عذاب القبر؟","answer":"الجواب: هذا يُفسَّر بأنَّ هؤلاء صُوّروا له يُعذَّبون بسبب أعمالهم الخبيثة المنكرة، ويحتمل أن هذا العذاب لهم في الدنيا، ويحتمل أنه مثال لعذابهم الذي يكون يوم القيامة، فإنه ﷺ رأى في نومه ملكين أخذا بيده وأرياه جماعةً من المعذَّبين: من آكل الربا، ومن الزُّناة والزَّواني، ومن الذي ينام عن الصلاة حتى تطلع الشمس ولا يُصلي، ويحفظ القرآنَ ولا يعمل به، فهو يحتمل أمرين: أحدهما: أن هذا العذاب يحصل لهم في القبر في أرواحهم في البرزخ، وأنه عذابٌ عُجِّل لهم. ويحتمل أن المراد بذلك أنَّ هذا هو جنس العذاب الذي يحصل لهم يوم القيامة، وأن هذا مما يُعذَّبون به يوم القيامة في النار -نسأل الله العافية والسلامة.\nوبكل حالٍ فهو وعيدٌ عظيمٌ يُفيد الحذر من هذه الأعمال الخبيثة، سواء كان ذلك في البرزخ، أو في الآخرة، والأظهر والأقرب -والله أعلم- أنه في البرزخ -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/20878/هل-هناك-عذاب-قبل-القيامة-غير-عذاب-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0673هل هناك عذاب قبل يوم القيامة غير عذاب القبر؟ ابن باز فتاوى المحاضرات.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":888,"question":"ما السلوك السَّليم الذي يجب أن يسلكه المرءُ ليكون مسلمًا مؤمنًا حقًّا؟","title":"ما الذي يجب على المرءُ ليلزم طريق الحق؟","answer":"الجواب: كما تقدَّم: السلوك السليم هو أن تستقيم على شريعة الله كما دلَّ عليه كتابُ الله، وكما جاءت سنةُ رسول الله ﷺ؛ أن تبحث وتعرف طريق الصَّحابة، وما سلكوا مع نبيهم ﷺ، فتتبع منهجه ﷺ: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، وقال تعالى: وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ [التوبة:100]، عليك بهذا الطريق، طريق النبي ﷺ، وطريق أصحابه، ومَن سلك سبيلَهم، وهم أهل السنة والجماعة: في أقوالك وأعمالك، في كل شيءٍ، واحذر البدع كلها.","link":"https://binbaz.org.sa/fatwas/20911/ما-الذي-يجب-على-المرء-ليلزم-طريق-الحق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0706ما هو السلوك السليم الذي يجب أن يسلكه المرء ليكون مسلماً مؤمناً حقاً؟ابن باز فتاوى المحاضرات.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1015,"question":"ما علامات المؤمن عند الموت، وكذلك الكافر؟","title":"ما علامات المؤمن والكافر عند الموت؟","answer":"الجواب: علامات المؤمن عند الموت: الإكثار من ذكر الله، والخوف والخشية منه ، والبدار بالتوبة، ويُروى عنه عليه الصلاة والسلام أنه قال: المؤمن يموت بعرق الجبين، قال بعضُهم: معناه: يعرق جبينه عند الموت، وقال بعضُهم: معناه: أنه يموت وهو كافلٌ كادحٌ، يكسب ويطلب الرزقَ الحلال، يعمل حتى يموت.\nفالعلامات الواضحة: توبته إلى الله، وإقلاعه من الذنوب، وإكثاره من ذكر الله وطاعته، وإظهار الخير، والندم على ما مضى منه من الشر، هذه علامات الخير، وعلامات الإيمان. والضدُّ بالضدِّ: الغفلة عن الله، وعن ذكره، هذه من علامات الشرِّ، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21061/ما-علامات-المومن-والكافر-عند-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0857ما هي علامات المؤمن عند الموت وكذلك الكافر؟ ابن باز فتاوى المحاضرات.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1064,"question":"هذا يقول بأنه أحسَّ أنه ارتكب ذنبًا عظيمًا، يقول: حتى أحسّ أنني منافقٌ، وأني لم أسلم من عذاب الله، فصرتُ أخاف الله، وأخاف ذنوبي، وأخاف من سُوء الخاتمة، وأن أموت على النفاق، فبِمَ تنصحني فضيلة الشيخ؟","title":"بم يُنصح مَن أحس بالنفاق بعد ذنب عظيم؟","answer":"الجواب:\nأنصحك بالحذر من الوساوس هذه، وحُسن الظن بالله، يقول الربُّ جل وعلا: أنا عند ظن عبدي بي، وأنا معه إذا دعاني، فعليك بحُسن الظن بالله، وإياك وسُوء الظن بالله، ويقول ﷺ: لا يموتَنَّ أحدٌ منكم إلا وهو يُحْسِن ظنَّه بالله، فالمؤمن يُحسن ظنَّه بربه، ويجتهد في طاعة ربِّه، والتوبة إليه، فإذا أحسستَ بذنبٍ فبادر بالتوبة والرجوع إلى الله والنَّدم، وعليك بحُسن الظن بالله، وأنه جوادٌ كريمٌ، يغفر الذنوبَ، ويتوب على التَّائبين، ولكن لا تأمن، لا تتساهل، كن بين الرجاء والخوف كما تقدَّم، تُبادر بطاعة الله، وتحذر معاصي الله، وتكون حَسَنَ الظنِّ بالله، راجيًا له، خائفًا منه سبحانه وتعالى، وإياك وسُوء الظن بالله، فإنَّ هذا يُفضي إلى القنوط واليأس، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/21119/بم-ينصح-من-احس-بالنفاق-بعد-ذنب-عظيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0915يقول السائل بأنه أحس أنه أرتكب ذنباً عظيماً حتى أحسب أني منافق وأموت على النفاق فما نصيحتكم؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1070,"question":"هل يُجزئ الغُسل عن الوضوء لأداء الصَّلاة؟","title":"هل يُجزئ الغُسل عن الوضوء لأداء الصَّلاة؟","answer":"الجواب:\nإذا كان الغسلُ للجنابة ونويتَ الحدثين؛ أجزأ. ولكن كونك تتوضأ كما توضأ النبيُّ ﷺ، ثم تغتسل، هذا هو الأكمل والأفضل. أما الغسل المستحبّ: كالجمعة، أو للتَّبرد، أو لإزالة الوسخ؛ فلا، لا بدّ من الوضوء، توضأ قبله أو بعده.","link":"https://binbaz.org.sa/fatwas/21112/هل-يجزى-الغسل-عن-الوضوء-لاداء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0908هل يجزء الغسل عن الوضوء لأداء الصلاة ؟ ابن باز فتاوى المحاضرات.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":1071,"question":"بماذا تنصحونني؟ فقد ابتُليتُ بالنظر إلى بعض المُحرَّمات، مثل: مُسارقة النظر إلى المرأة، سواء على الطبيعة، أو على طريق مجلة، أو تلفاز. أفيدونا جزاكم الله خيرًا وأبقاكم.","title":"ما النصيحة لمن ابتُلي بالنظر إلى النساء؟","answer":"الجواب:\nقد بيَّن الله  حكمه في ذلك فقال سبحانه: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30]، فأنت احتسب نفسك من هؤلاء، جاهدها، إذا كنتَ ترجو أن تكون من المؤمنين فجاهدها ولا تنظر إلى النساء والمردان، لا في التلفاز، ولا في المجلات، ولا في الأسواق، ولا في أي شيءٍ نظرة شهوةٍ. أما النظر العابر الذي لا تقصد به الشَّهوة، أو صدفة، مثلما قال النبيُّ ﷺ لما سُئل عن نظر الفجأة قال: اصرف بصرك، وقال: إنَّ لك الأولى، وليست لك الأخرى، فالشيء الذي كان صدفةً ما قصدتَه لا حرج عليك. أما أن تقصد وتُتابع النظر فلا، وهكذا مع المردان الذين قد تتحرك الشهوةُ بالنظر إليهم، تحذر ذلك.","link":"https://binbaz.org.sa/fatwas/21111/ما-النصيحة-لمن-ابتلي-بالنظر-الى-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0907ما نصيحتكم بمن ابتلي بالنظر إلى النساء؟ فتاوى المحاضرات ابن باز.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1091,"question":"لقد علمنا أهمية طلب العلم، فحرصنا على ذلك، غير أننا صُدمنا بالواقع؛ إذ تعجّ الحياة بالمُتناقضات، فما يُبنى في سنةٍ تهدمه الوسائلُ الأخرى في ليلةٍ، فتنشأ النَّاشئة في المُجتمعات الإسلامية نشأةً مُتناقضةً، يقرؤون آيةَ الحجاب في الصباح فيرون ما يُناقضها في المساء، فما الواجب تجاه ذلك؟","title":"كيف يواجه المسلم غُربة الدين آخر الزمان؟","answer":"الجواب:\nهذا هو الابتلاء والامتحان، ولا سيما في آخر الزمان، مثل زماننا هذا، نحن في آخر الزمان، وفي غُرْبَةٍ من الدين، فلا بدّ من الصبر، كما أخبر النبيُّ ﷺ: يأتي على الناس زمانٌ الصابر على دينه كالقابض على الجمر، ويقول ﷺ: بدأ الإسلامُ غريبًا، وسيعود غريبًا كما بدأ، فطُوبى للغُرباء خرجه مسلمٌ في \"الصحيح\"، زاد غيره في لفظٍ: مَن الغرباء؟ قال: الذين يصلحون إذا فسد الناسُ، وفي لفظٍ آخر: يُصلحون ما أفسد الناسُ من سنتي، وفي حديث أبي ثعلبة: للعامل منهم أجر خمسين، قيل: يا رسول الله، منا أو منهم؟ قال: بل منكم.\nوأسباب ذلك قلَّة الأنصار والأعوان، وكثرة المهالك والشُّبَه، وكثرة طرق الضَّلالة والدُّعاة إليها، فلهذا الصابر في آخر الزمان على العلم والعمل له أجر خمسين من الصحابة، مثل أجر خمسين؛ لأنهم يجدون أعوانًا، وفي أول مجيء الإسلام، وفي نشاط الإسلام، ونشاط المسلمين، وقوة الإسلام، وقوة المسلمين، وكثرة الأعوان، واندحار الأعداء.\nأما في آخر الزمان فالعكس؛ كثرة الأعداء، وكثرة دُعاة الضَّلالة، وقلَّة الأنصار، وقلة المعين على الحقِّ، مع كثرة الشُّبَه، فهذا صراعٌ بين الحقِّ والباطل في آخر الزمان شديد، فلا بد من صبرٍ على ما تعلمه، فإذا عرف مما تعلم الحقّ ثم رأى ما يُضاده؛ حمد الله على بصيرةٍ، وحمد الله أن جعله ممن عرف هذا الحقَّ، ثم يعمل بما يستطيع من إنكار المنكر، والدعوة إلى الخير، حتى يُحقق ما علم.\nوهذا يشمل ما يتعلق بالعقائد، وما يتعلق بفروعه، وهذا مما يُسبب عظيم الأجور، وكثرة الحسنات، لمن صبر واحتسب، ويُبصره أيضًا بالعلم، يزيده علمًا، فإنَّ وجود المتناقضات مما يُعين على التوسع في العلم، والتَّبصر، ومعرفة الشُّبَه لإزالتها والقضاء عليها، ومعرفة السُّبل التي تُعين على الحقِّ وتهدي إليه، حتى ينشرها بين الناس، ويدعو إليها.","link":"https://binbaz.org.sa/fatwas/21125/كيف-يواجه-المسلم-غربة-الدين-اخر-الزمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0921تعج الحياة بالمتناقضات فما يبنى في سنة تهدمه الوسائل الأخرى في ليلة فما هو الواجب تجاه ذلك؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1107,"question":"إذا مات الرجلُ الصالحُ: هل يُنَعَّم في القبر أم يدخل الجنة؟ وكذلك الفاسق الكافر: هل يُعذَّب في القبر أم يدخل النار؟ أرجو التوضيح جزاكم الله خيرًا.","title":"ما كيفية عذاب القبر ونعيمه للميّت؟","answer":"الجواب:\nالقبر إمَّا روضة من رياض الجنة، أو حفرة من حفر النار، وهو أول منازل الآخرة، وأخبر النبي ﷺ أنَّ المؤمن إذا وُضع في قبره يُفتح له بابٌ إلى الجنة، ويرى مقعده من الجنة، ويأتيه من روحها ونعيمها، فضلًا من الله جلَّ وعلا، ويُفتح له بابٌ إلى النار، ويُقال: هذا مقعدك لو كفرتَ، فالآن هذا مقعدك من الجنة، فيراهما جميعًا حتى يتم سروره ويغتبط بفضل الله عليه: أن أجاره من النار، وأدخله الجنة، وفتح له بابًا إليها.\nوبعد البعث والنُّشور والموقف يوم القيامة بعد ذلك ينتقل المؤمنون إلى دورهم في الجنة، أما في الدنيا في القبور فيأتيه من نعيمها وروحها وطيبها وهو في قبره، وينال جسده نصيبه من ذلك، والروح تُنعَّم في الجنة، أرواح المؤمنين تنقل إلى الجنة كما في الحديث الصحيح: أنها طائر يعلق بشجر الجنة، حتى يردَّها الله إلى جسدها، وترد إلى الجسد متى شاء الله ذلك جلَّ وعلا.\nأما أرواح الشُّهداء -أرواح المقتولين في سبيل الله- فهؤلاء أرواحهم في أجواف طيرٍ خُضْرٍ تسرح في الجنة حيث شاءت، ثم تأوي إلى قناديل مُعلَّقة تحت العرش، كما جاء به الخبر عن رسول الله عليه الصلاة والسلام.\nوالكافر بضدِّ ذلك: إذا وُضع في قبره يُعذَّب في قبره، ويناله من العذاب ما شاء الله من ذلك، وروحه تُعذَّب في النار، ومع الجسد، لكن نعيم الروح وعذاب الروح أكمل، ويوم القيامة يُدخل الكافرُ النار، روحه وجسده يدخلان النار، والمؤمن بروحه وجسده إلى الجنة، أما في الدنيا فينال الجسد نصيبه من النعيم -جسد المؤمن- وينال جسد الكافر نصيبه من العذاب، وروحه نعيمها أكمل، وعذابها أكمل في الدنيا، روح المؤمن تُنَعَّم في الجنة، وروح الكافر تُعذَّب في النار، قال تعالى في آل فرعون: النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ [غافر:46]، فدلَّ على أنَّ أرواحهم في الدنيا يُصيبها نصيبها من العذاب في القبر، وفي خارج القبر، وهكذا المؤمن يحصل لروحه من النعيم في القبر، وفي خارج القبر، وتنقل إلى الجنة كما تقدم، وتكون طائرًا يسرح في الجنة حيث شاء، ويردّها الله إلى جسدها متى شاء .","link":"https://binbaz.org.sa/fatwas/21172/ما-كيفية-عذاب-القبر-ونعيمه-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0968إذا مات الرجل الصالح هل ينعم في القبر أم يدخل الجنة؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1112,"question":"أنا إنسانٌ أكثرتُ في المعاصي، ومن المعاصي والذنوب، ولكن الحمد لله ربّ العالمين الذي مَنَّ عليَّ بالهداية، فلقد تغيرت حياتي، ولكن أحسّ في قلبي أنَّ الله  لن يغفر لي ذنوبي التي ارتكبتُ من قبل، فبماذا تنصحني؟وبهذه المناسبة المباركة أسألك بالله الذي لا إله غيره أن تدعو لي ولكلِّ واحدٍ مثلي في هذا المكان المُبارك الطيب دعوةً بالمغفرة والقبول، لعلَّ الله سبحانه وتعالى أن يتجاوز عنَّا، ويجزيكم عنا.","title":"ما حكم من تاب ويخشى أنه لا يُغفر له؟","answer":"الجواب:\nأسأل الله  أن يقبل توبتك، وأن يُصلح قلبك وعملك وسائر المسلمين، أسأل الله أن يُصلح قلوبنا وأعمالنا جميعًا، وأن يمُنَّ علينا بالتوبة النَّصوح، وأن يهدينا صراطه المستقيم، وأن يُعيذنا من شرور أنفسنا، ومن سيئات أعمالنا.\nوننصحك بحُسن الظن بالله، عليك بحُسن الظنِّ بالله، وإياك والوساوس وسُوء الظنِّ بالله، ما دمت تبتَ من سيئاتك فاحمد الله، واسأله أن يتقبَّل منك، واحذر العودة إلى الشرِّ والمعاصي، واحذر العودة إلى صُحبة الأشرار، لا تصحب الأشرار، وعليك بصُحبة الأخيار، وأحسن ظنّك بربك، يقول النبيُّ ﷺ: يقول الله : أنا عند ظنّ عبدي بي، وأنا معه إذا دعاني، فمَن أحسن ظنَّه بالله ربح غاية الربح.\nفعليك أن تُحسن ظنك بالله، وأن تدعوه أن يُثبتك على الحقِّ، وأن يهديك صراطه المستقيم، وأن يُحسن لك الختام، واحذر وساوس الشيطان، وسوء الظن بالله ، ويقول عليه الصلاة والسلام: لا يموتنَّ أحدٌ منكم إلا وهو يُحسن ظنّه بالله، فالشيطان حريصٌ على إضلال بني آدم، وإفساد أعمالهم، وإذا تابوا وسوس لهم بأنَّ توبتكم غير مقبولةٍ، وأن معاصيكم الماضية عظيمة، وأنَّكم لا تسلمون من شرِّها، وهذا كله من خداعه، وكله من ظلمه وعدوانه، فعليك بالحذر من وساوس الشيطان، واذكر قوله تعالى: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا عَسَى رَبُّكُمْ أَنْ يُكَفِّرَ عَنْكُمْ سَيِّئَاتِكُمْ وَيُدْخِلَكُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ [التحريم:8]، وعسى من الله واجبة.\nويقول النبيُّ ﷺ: التَّائب من الذنب كمَن لا ذنبَ له، ويقول عليه الصلاة والسلام: التوبة تهدم ما كان قبلها، والإسلام يهدم ما كان قبله، فمَن تاب توبةً صادقةً بالندم على الماضي، والإقلاع منه، والعزم الصادق ألا يعود فيه؛ تاب الله عليه، وعفا عنه ، وإن كانت التوبةُ من حقِّ المخلوق فلا بد من أمرٍ رابعٍ، وهو: ردّ الحقِّ إلى أهله، كالسرقة والغصب ونحو ذلك، لا بد من ردِّ الحقِّ إلى صاحبه، أو استسماحه واستحلاله حتى تتم التوبةُ.\nفالشروط ثلاثة، التوبة لها شروط ثلاثة: النَّدم على الماضي. والإقلاع من المعصية وتركها خوفًا من الله، وتعظيمًا له. والأمر الثالث: العزم الصادق ألا تعود في ذلك. وهناك أمرٌ رابعٌ إذا كانت المعصيةُ تتعلق بالمخلوق: أنه لا بد من استسماحه، أو ردّ حقّه إليه، كالقاتل والسارق والغاصب، لا بد من ردِّ الحقِّ إلى أهله، أو يستسمحهم، وإلا فالتوبة تكون غير تامَّةٍ.","link":"https://binbaz.org.sa/fatwas/21167/ما-حكم-من-تاب-ويخشى-انه-لا-يغفر-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0963أنا تبت ولله الحمد من المعاصي ولكن أحسًّ في قلبي أن الله لم يغفر لي فما تنصحوني؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1116,"question":"إنني شابٌّ اهتديتُ إن شاء الله إلى طريق الصواب، وفي البداية وجدتُ حلاوة الإيمان، وشدَّني إنكار المُنكر، ولكنني الآن تقهقرتُ حتى إني أخاف أن أنتكس، أرجو من فضيلتكم النُّصح لي ولإخواني في مثل هذا الموضوع؟","title":"بِمَ يُنصح من استقام على الخير ثم تأخر؟","answer":"الجواب:\nالواجب على المؤمن والمؤمنة إذا مَنَّ الله عليه بالاستقامة أن يُحافظ عليها، وألا يُشدد على نفسه، وأن يصحب الأخيار، ويبتعد عن الأشرار، فالمؤمن مأمورٌ بالثبات على الحقِّ، والحذر من الغلو والجفاء، فلا يغلُ ويبتدع ويُشدد، ولا يجفُ ويقصر ويرتكب المعاصي، ولكن بين ذلك، لا غلو، ولا جفاء، يتحدث مع إخوانه، ويُجالس إخوانه في الله، ويتعاون معهم على البر والتَّقوى، وينصح لهم، ويقبل النَّصيحة، ولا يبتدع في الدين ما لم يأذن به الله، ولا يرضى بالفاحشة، ولا يميل إليها.\nهكذا المؤمن: يتوسط في أموره، فلا غلو، ولا جفاء، لا عنف وشدَّة، ولا تساهل في أمر الله، ولكن وسط، يرفق بإخوانه، ويُحب لهم الخير، ويُخاطبهم بالتي هي أحسن، ولا يبتدع في دين الله ما لم يأذن به الله، ولا يقصر ويرتكب ما حرَّم الله.","link":"https://binbaz.org.sa/fatwas/21163/بم-ينصح-من-استقام-على-الخير-ثم-تاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0959نصيحة في المحافظة على الاستقامة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1161,"question":"يعيش الشبابُ في مرحلة المُراهقة مرحلةً حرجةً من الصراع مع شهواته، ويرى أنه إن أطلق العنانَ لهذه الشَّهوات أهلكته في الدنيا والآخرة، ما السلاح الذي يعتصم به الشبابُ في مُواجهة هذه الشَّهوات؟","title":"ما العوامل التي تعين الشباب أمام الشهوات؟","answer":"الجواب:\nلا شكَّ أن التيار عظيم وخطير مع الشباب وغير الشباب، حتى الشيوخ على خطرٍ، حتى الكبار على خطر، فالأمر عظيم، وأسباب الفتنة كبيرة ومتنوعة: في الأسواق، وفي البيوت، وفي كل مكانٍ، حتى على الشيوخ، حتى على الكبار، فكيف بالشباب؟!\nوطريق النَّجاة هو الحذر من أسباب الفتنة: غضّ البصر، عدم الخلوة بالنساء -بالمرأة الأجنبية-، عدم صحبة الأشرار، الحرص على صحبة الأخيار، هذه من أسباب السلامة؛ كون المؤمن يحرص على صُحبة الأخيار، ويكون معهم، أو يلزم بيته، إلا لخروجه للصلاة وما لا بد منه، فيحذر التَّجول في الأسواق؛ فإنها سبب فتنةٍ، لا يخرج إلا لحاجةٍ، مع غضِّ البصر، ومع الحذر، أو يخرج للصلاة.\nفبيتُه إذا لزمه هو أسلم له، إلا من حاجةٍ، مع غضِّ البصر، ومع تدبُّر القرآن، والإكثار من تلاوة القرآن؛ لأنه يُربي الإيمانَ في القلوب، والخوف من الله، والحذر منه، وهو كتاب الله، فيه الهدى والنور، فيه الهداية لكل خيرٍ: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، شفاء لأمراض القلوب أعظم، وشفاء لبعض أمراض البدن أيضًا، ولكنه شفاء لما في الصدور، شفاؤه للقلوب أعظم وأكبر، كما قال تعالى: يَا أَيُّهَا النَّاسُ قَدْ جَاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفَاءٌ لِمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِلْمُؤْمِنِينَ [يونس:57]، فبالإكثار من تلاوته وتدبُّر معانيه يقوى الإيمان، ويقوى الخوف من الله، والرجاء له، والحذر من معاصيه، ومن أسباب غضبه.\nوصُحبة الأخيار تُعين على ذلك، والحذر من اتباع الهوى، الهوى يهوي بصاحبه إلى الشر، فاحذر هواك ونفسك الأمَّارة بالسُّوء، الله يقول: وَلَا تَتَّبِعِ الْهَوَى فَيُضِلَّكَ عَنْ سَبِيلِ اللَّهِ [ص:26]، ويقول سبحانه: وَمَنْ أَضَلُّ مِمَّنِ اتَّبَعَ هَوَاهُ بِغَيْرِ هُدًى مِنَ اللَّهِ [القصص:50]، ويقول سبحانه: وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى  ۝  فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى [النازعات:40- 41]، وقال في الكفار: إِنْ يَتَّبِعُونَ إِلَّا الظَّنَّ وَمَا تَهْوَى الْأَنْفُسُ [النجم:23]، فاحذر مُشابهتهم، فما تميل إليه نفسُك وهواك احذره حتى تعلم أنه صوابٌ، وأنه خيرٌ، وإلا فالهوى يقودك إلى البلاء.\nومن أعظم أسباب النَّجاة: صحبة الأخيار، والحرص عليهم، واتخاذهم أصحابًا، ولزوم البيت عند فقدهم، إلا من حاجةٍ: كالخروج للصلاة، ودرس العلم، والحاجات التي لا بد منها، وإذا بُليتَ بالأسواق فغضّ بصرك، واحذر مُتابعة الهوى، وصُحبة الأشرار، لا في الأسواق، ولا في غيرها.","link":"https://binbaz.org.sa/fatwas/21222/ما-العوامل-التي-تعين-الشباب-امام-الشهوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1018ما هو السلاح الذي يعصم به الشباب أمام الشهوات؟ابن باز.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1176,"question":"أجد في نفسي إذا خلوتُ هوًى وشهوةً، فما تنصحني حفظك الله؟","title":"ما النصيحة لمن يجد في نفسه ميلًا للشهوات؟","answer":"الجواب:\nأنصحك بأن تتذكر المقام بين يدي الله، وأنت مسؤولٌ عن جوارحك كلها: هل صُنتها وحفظتها؟ ومنها عينك وأذنك ولسانك ويدك ورجلك، وأعظمها قلبك، فعليك أن تصونه عن الهوى المحرم.  إذا شغلت قلبك بذكر الله والتَّفكير فيما أوجب الله عليك وبتدبُّر القرآن وفيما يلزمك من طاعة الله ورسوله؛ فهذا شغلٌ شاغلٌ عن الميل إلى ما حرَّم الله.","link":"https://binbaz.org.sa/fatwas/21256/ما-النصيحة-لمن-يجد-في-نفسه-ميلا-للشهوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1138ما نصيحتكم من يجد في نفسه ميل للشهوات؟ ابن باز فتاوى.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1181,"question":"إني أجد وقتًا كبيرًا، ولا أدري ماذا أفعل؟ وأجلس مع إخوةٍ لي في الله ونمزح ونحو ذلك.","title":"كيف يستفيد المسلم من وقته وفراغه؟","answer":"الجواب:\nتذكر أنَّ الوقت من ذهبٍ، بل أعز من الذهب، الوقت أعزّ من الذهب، فاحرص على حفظه، ولا تشغله بالسَّوالف الباطلة، والأحاديث التي لا فائدةَ فيها، لا مع زملائك، ولا مع غيرهم، احفظه، ولا تصرف الوقتَ إلا فيما ينفعك.  فالوقت له شأنٌ عظيمٌ، فاحفظه في قراءة القرآن، والاستكثار من تلاوته، وقراءة الأحاديث، قراءة متونك وتكرارها، المتون التي عندك: كتاب \"التوحيد\" و\"بلوغ المرام\" و\"عمدة الحديث\" الألفية، المتون الفقهية التي عندك، المتون التي عندك احرص عليها، كررها واحفظها، طالع ما أشكل عليك من المسائل، راجع كلام أهل العلم، راجع الأحاديث التي تحتاج إلى حفظها، أو تنسى بعضها حتى تحفظها، راجع الشروح فيما أشكل عليك.  ذاكر مع الزملاء الطيبين الحريصين، واحرص على صحبتهم؛ حتى تكون أوقاتك محفوظةً، أما إذا تساهلت ضاعت الأوقاتُ! ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/21251/كيف-يستفيد-المسلم-من-وقته-وفراغه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1143كيف أستفد من وقتي؟ ابن باز فتاوى.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1321,"question":"إذا إنسان نَوَى نيةً سيئة ثم رجع إلى الله عز وجل وغَيَّر نيته إلى طَيِّبَة؛ في هذه الحال هل تلزم التوبة؟","title":"كيف تكون توبةُ مَن نَوَى سيئة ولم يفعل؟","answer":"الجواب:\nإذا غَيَّر النية قبل أن يعمل؛ ما في شيء، أو إذا غَيَّرها قبل أن يعمل؛ قبل أن يَصَدَّق، قبل أن يجاهد، قبل أن يصلي، وأصلح نيته؛ فعلى نيته الأخيرة الطيِّبة.","link":"https://binbaz.org.sa/fatwas/21412/كيف-تكون-توبة-من-نوى-سيىة-ولم-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تلزم التوبة على من نوى نية سيئة ولم يفعل.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1323,"question":"إذا إنسان هَمَّ بفعلٍ ولم يستطع أن يفعله؛ فهل يُكتب عليه إذا كان قد جَزَم بالإرادة جَزْمًا على فِعْله؟","title":"ما أنواع الهَمُّ بالسيئة؟ وماذا يترتب عليها؟","answer":"الجواب:\nالهَمُّ بالفعل له أحوال ثلاث:\nإذا هَمَّ وعمل فله ما عمل، هم بالحسنة وعملها؛ له أجرها إلى سبعمائة ضعف إلى أضعاف كثيرة.\nالثاني: هَمَّ ولكن تساهل وترك تهاونًا وكسلاً، وهَمَّ بالسيئة؛ فهذا ليس عليه شيء.\nالثالث: هَمَّ بالسيئة وتركها من أجل الله؛ فهذا له أجر، له حسنة؛ لأنه تركها من أجل الله، تركها مثل ما جاء في الحديث: تركها من جَرَّائي فإذا هم بها ثم تركها من أجل الله؛ صار له أجر، فإنْ عملها صار عليه وزرها.\nوهكذا الحسنة: إنْ هَمَّ بها فله حسنة، وإن لم يفعلها، فإذا فعلها صارت له عشر حسنات إلى سبعمائة ضعف إلى أضعاف كثيرة.","link":"https://binbaz.org.sa/fatwas/21414/ما-انواع-الهم-بالسيىة-وماذا-يترتب-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أنواع الهم بالسيئة وما يترتب على كل نوع.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1324,"question":"بالنسبة الآن في الوقت الحاضر أغلب البلدان  المنتمية للإسلام تكون هناك باسم الجهاد ناس يتقاتلون فيما بينهم، وفي الغالب القاتل والمقتول عقيدتهم غير سليمة، ماذا يكون في مثل هذا؟","title":"حكم قتلى الحرب بين بلاد تنتمي للإسلام","answer":"الجواب:\nعلى حسب أحوالهم هذا إلى الله جل وعلا، الكافر على حاله، والعاصي على حاله، وأمرهم إلى الله، الله يعلم أحوالهم.","link":"https://binbaz.org.sa/fatwas/21415/حكم-قتلى-الحرب-بين-بلاد-تنتمي-للاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم القاتل والمقتول باسم الجهاد.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1333,"question":"إذا تاب عن معصية ولم يتب عن معصية أخرى هل تُقبل توبته؟","title":"حكم التوبة من بعض الذنوب دون بعض","answer":"الجواب:\nتقبل، مُبَعّض، الذنوب.....، لو تاب من الزنا ولم يتب من الخمر قُبلت توبته إذا كانت توبته استوفت الشروط، وهكذا إذا تاب من العقوق للوالدين تُقبل توبته وإن كان عنده ذنوب أخرى.  لكن الواجب عليه أن يتوب منها كلها، الواجب عليه أن يتوب من جميع الذنوب، قال الله جل وعلا: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ.. [النور:31].","link":"https://binbaz.org.sa/fatwas/21424/حكم-التوبة-من-بعض-الذنوب-دون-بعض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من تاب من ذنب ولم يتب من آخر.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1336,"question":"بالنسبة الذي يربط التوبة أنه إذا تزوج، أو إذا حج، أو إذا كَبُر َبالسن؛ يعني يقول أنا في سن الشباب؟","title":"حكم تعليق التوبة بحدث مُعَيَّن","answer":"الجواب:\nلا ما يجوز هذا، من قال له؟! سوف يهجم عليه الأجل، الأجل مُغَطَّى، قد يهجم عليه الأجل وهو في أول الشباب، الواجب البِدَار بالتوبة، وعدم التعليق.","link":"https://binbaz.org.sa/fatwas/21427/حكم-تعليق-التوبة-بحدث-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعليق التوبة بحدث معين.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1355,"question":"الملائكة الحَفَظَة هل يطلعون على النيَّات، أم يكتبون الأعمال والأفعال فقط؟","title":"هل تَطَّلِع الملائكة على أعمال القلوب؟","answer":"الجواب:\nيكتبون أعمال القلوب وأعمال الجوارح كلها، الله يطلعهم على أعمال القلوب من خوف ورجاء ومحبة، كل شيء.","link":"https://binbaz.org.sa/fatwas/21448/هل-تطلع-الملاىكة-على-اعمال-القلوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تطلع الملائكة على أعمال القلوب.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1367,"question":"في بعض الناس إذا التزم انتكس، ثم إذا انتكس يصعب أنه يرجع إلى الله ، يعني ييأسون منه يقولون أنه يطلع أشد من أول، أول قبل ما يهتدي؟","title":"حكم اليأس مِن عودة من ارتدَّ عن الإسلام","answer":"الجواب:\nلا، يُنصح حتى يتوب ويرجع؛ فكثير من الناس ارتد ورجع  وحَسُن إسلامه، مثل عبدالله بن سعد بن أبي سرح وغيره. الإنسان إذا وُجد منه شيء يُنصح حتى يرجع إلى الصواب، لا ييأسوا ولا ينبغي وَلا تَيْئَسُوا مِنْ رَوْحِ اللَّهِ [يوسف:87].  بعد موت النبي ﷺ ارتد كثير من الناس ثم هداهم الله وأسلموا ورجعوا إلى الحق.","link":"https://binbaz.org.sa/fatwas/21460/حكم-الياس-من-عودة-من-ارتد-عن-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يرتد ويرجع هل يثاب على أعماله قبل أن يرتد.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1380,"question":"ذكر قصص سُوء الخاتمة للعبرة؟","title":"حكم ذِكْر قصص سُوء الخاتمة للعبرة","answer":"الجواب:\nعلى كل حال الواجب الحذر من سُوء الخاتمة، نسأل الله العافية والمعاصي والتساهل من أسباب سُوء الخاتمة، والحسنات والاستكثار من الخير من أسباب حُسن الخاتمة، والغفلة واتباع الهوى من أسباب سوء الخاتمة، نعوذ بالله، والاستقامة على طاعة الله ورسوله  ﷺ والمسارعة إلى الخيرات من أسباب حسن الخاتمة.","link":"https://binbaz.org.sa/fatwas/21473/حكم-ذكر-قصص-سوء-الخاتمة-للعبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ذكر قصص سوء الخاتمة للعبرة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1388,"question":"هل تشترط الموالاة في الغسل أم يجوز تفريقه؟","title":"هل تُشترط الموالاة في الغُسْل؟","answer":"الجواب:\nالسنة الموالاة كما كان النبي ﷺ يوالي، لكن لو أخل بشيء وغسله بعد ذلك لا بأس، لو أخل بشيء من جسمه من رأسه أو من صدره أو كذا وغسله فالحمد لله.\nس: لو فرق تفريقًا طويلاً يعني غسل بعض أجزائه؟\nج: السنة الموالاة، المشروع الموالاة، لا يتعمد الترك، لكن لو وجد شيء أخل به ثم تَنَبَّه غسله، مثلًا نسي المضمضة، نسي الاستنشاق، ثم تنبه؛ يتمضمض ويستنشق بنية الغسل، والحمد لله.","link":"https://binbaz.org.sa/fatwas/21481/هل-تشترط-الموالاة-في-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الموالاة في الغسل.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":1393,"question":"الكثير من العلماء المعروفين خاصة علماء السلف والزهاد كانوا لا يأكلون إلا الخبز مع الماء؟","title":"ما الهَدْيُ النبوي الصحيح في الزهد؟","answer":"الجواب:\nكل عالم يخطئ ويصيب، من خالف السنة ولو أنه من الصحابة ما يُقتدى به، السنة هي القدوة لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] ومن تبعه بإحسان كذلك.\nس: ماذا لو قالوا: أَذْهَبْتُمْ طَيِّبَاتِكُمْ [الأحقاف:20]؟\nج: هذا في الإسراف والزيادات والاشتغال بملاذ الدنيا عن طاعة الله، لا هذا ولا هذا، لا إسراف وركون إلى الدعة والنعمة، ولا تكلف وغلو، ولكن بين ذلك.","link":"https://binbaz.org.sa/fatwas/21486/ما-الهدي-النبوي-الصحيح-في-الزهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الزهد.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1399,"question":"كيف يجمع بين الأمر بمجاهدة النفس والأمر بالاقتصاد بالعبادة والطاعة؟","title":"كيف يكون جهاد النفس مع القصد في العبادة؟","answer":"الجواب:\nلا منافاة، يجاهدها في أداء فرائض الله، ويجاهدها في ترك محارم الله، ويجاهدها فيما تيسر من العبادة، ولا يشقّ عليها.","link":"https://binbaz.org.sa/fatwas/21492/كيف-يكون-جهاد-النفس-مع-القصد-في-العبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الأمر بمجاهدة النفس والأمر بالاقتصاد بالعبادة والطاعة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1436,"question":"مَن سَنَّ سنةً سيئةً وتَبِعَه ناسٌ، ثم تاب وأتباعه لا زالوا يتبعونه، فهل عليه وزر؟","title":"حكم مَن سَنَّ سنة سيئة وتَبِعَه أناسٌ ثم تاب","answer":"الجواب:\nالظاهر أنه إذا تاب توبةً صادقةً ما عليه شيء، إلا إذا كانوا هم قريبين ويستطيع أن يُبلِّغهم؛ فعليه أن يُبَلِّغهم حتى لا يقتدوا به. أما إذا ما استطاع أن يُبَلِّغهم فنرجو أن توبته تكفيه، والشرك أعظم من ذلك. لكن إذا كان يمكنه الحصول على عناوينهم، أو كانوا قريبين منه فعليه أن يُبَلِّغهم: \"أني أخطأتُ في هذا الشيء وقد رجعتُ عن خطئي\"؛ حتى لا يتأسّوا به.","link":"https://binbaz.org.sa/fatwas/21531/حكم-من-سن-سنة-سيىة-وتبعه-اناس-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من سن سنة سيئة وتعبه أناس ثم تاب هل عليه وزر.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1462,"question":"لو أنَّ الشخص سرق وتاب فهل تكفي التوبة؟","title":"ما حكم التوبة لمن عليه حقوق للناس؟","answer":"الجواب:\nالتوبة تجُبُّ ما قبلها، لكن يرضي أصحاب الحقوق، فإذا تاب توبة صادقة يرضي الله  أصحاب الحقوق، ولا تضيع حقوقهم، فحقوقهم تبقى ويُرضيهم الله عنها إذا صحَّت التوبة.","link":"https://binbaz.org.sa/fatwas/21559/ما-حكم-التوبة-لمن-عليه-حقوق-للناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أذنب ثم تاب فهل تكفي التوبة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1509,"question":"الفقر هل يدخل في أنواع الابتلاء من الله؟","title":"هل يدخل الفقر في أنواع الابتلاء من الله؟","answer":"الجواب:\nكلها ابتلاء، الغنى والفقر، هذا يُبتلى بالسراء، وهذا يُبتلى بالضراء، هذا يُبتلى بالصحة، وهذا يُبتلى بالمرض، هذا يبتلى بالغنى، وهذا يبتلى بالفقر، هذا يبتلى بالوظيفة، وهذا يبتلى بحرمانها، كلها ابتلاء وامتحان.","link":"https://binbaz.org.sa/fatwas/21608/هل-يدخل-الفقر-في-انواع-الابتلاء-من-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعدد ابتلاء الله للعباد.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1512,"question":"رجل ترك الصلاة عشر سنين، وترك الصوم والزكاة، وسرق، وتَسَلَّف ولم يرجع الأموال، وتاب؟","title":"حكم مَنْ ترك الفرائض وسرق ثم تاب","answer":"الجواب:\nإذا تاب يمحو الله ما سلف، إذا أسلم محا الله عنه ما مضى، يقول الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، ويقول النبيُّ ﷺ للمسلم: أسلمتَ على ما أسلفتَ من خيرٍ. والمال الذي سرقه يرده إلى أصحابه، والحمد لله، وإذا عجز فالله يرده عنه يوم القيامة، لكن إذا استطاع يرد المال على أهله.  ولا يقضي الصوم ولا الصلاة ما دام تاب وأسلم، الحمد لله.","link":"https://binbaz.org.sa/fatwas/21611/حكم-من-ترك-الفراىض-وسرق-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ترك الصلاة والصوم والزكاة وسرق ثم تاب فما الحكم.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1539,"question":"رجل عند بوله يخرج قبل بوله بقليلٍ مَنِيّ؛ لشدة قوة مَنِيِّه وكثرته، كما قال الأطباء، فهل يغتسل لكل...؟","title":"حكم خروج المَنِيّ بغير شهوة","answer":"الجواب:\nلا، هذا إذا كان عنده شهوة، وأما العادي هذا الذي مع البول أو بعد البول ما يضر، هذا مرض.\nس: لونه لون المَنِيّ؟\nج: لا بدّ عن شهوة: إذا فَضَخْتَ مَنِيَّكَ فاغتسل، لا بدّ أن يكون عن شهوةٍ: إما مجامعة، وإلا ملامسة، وإلا تقبيل، وإلا تفكير.\nس: يترك الاغتسال الآن؟\nج: لا، ما عليه اغتسال، ما عليه إلا الاستنجاء.","link":"https://binbaz.org.sa/fatwas/21639/حكم-خروج-المني-بغير-شهوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم خروج المني عند الوضوء.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":1687,"question":"إذا كان الرجلُ عنده معاصٍ ولا يصلي، وقبل وفاته بقليلٍ أعلن الشَّهادة: \"لا إله إلا الله، وأنَّ محمدًا رسول الله\"، هل يُحكم عليه بمثل الحكم هنا؟","title":"هل تكفِّر شهادةُ التوحيد الشرك والمعاصي؟","answer":"الجواب:\nالمعاصي لا يُكفِّرها قول: \"لا إله إلا الله\"، لا بدّ من التوبة، \"لا إله إلا الله\" تُكَفِّر الشركَ إذا صدق فيها، أما إذا أتى بالمعاصي فلا بدّ من توبته من المعاصي خاصَّةً، وإذا أتى ما يُوجب الحدَّ يُقام عليه الحدُّ، ولو قال:\"لا إله إلا الله\"، فالنبي ﷺ أقام الحدودَ على المسلمين وهم يقولون: \"لا إله إلا الله\".","link":"https://binbaz.org.sa/fatwas/21793/هل-تكفر-شهادة-التوحيد-الشرك-والمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المعاصي والشرك هل تكفرها قول لا إله إلا الله أم لا بد من التوبة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1696,"question":"بالنسبة لمَن يُلْجِمه العرقُ يوم القيامة: يكون ذلك لعامَّة الناس أم لمَن كانت له معصية؟","title":"مَن الذين يُلْجِمُهم العَرَقُ يوم القيامة؟","answer":"الجواب:\nظاهر الحديث العموم، لكن المراد الكفرة وأهل المعاصي، أما المؤمنون فلهم النَّجاة والسعادة في موقف القيامة، وفي القبر، وفي الجنة، لكن الإنسان يحذر أن يُصيبه ما أصاب الناس بسبب موته على بعض المعاصي –نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21802/من-الذين-يلجمهم-العرق-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يلجمه العرق يوم القيامة الناس عامة أم لمن كان له معاصي.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1796,"question":"هل هذه الدَّرجات متساوية من ناحية الثواب، التي هي: القرآن والقراءة والقتال والصَّدقات؟","title":"هل تتفاوت درجات الثواب للأعمال الصالحة؟","answer":"الجواب:\nلا، الثواب يختلف على حسب نية العبد وإخلاصه وصدقه واستكماله العمل، يختلف، هذا يُصلي وهذا يُصلي، وبين صلاتيهما أعظم مما بين المشرق والمغرب، هذا صلاته قد أقبل عليها، واعتنى بها، وخشع فيها لله، وكمَّلها، وهذا عنده نقصٌ فيها، فبينهما فرقٌ، وهكذا صيامهم، وهكذا حجهم، يختلفون.","link":"https://binbaz.org.sa/fatwas/21903/هل-تتفاوت-درجات-الثواب-للاعمال-الصالحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تتساوى درجات الأعمال من ناحية الثواب.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2052,"question":"الزهد أخصُّ من الورع؟","title":"هل الزهد أخَصُّ من الوَرَع؟","answer":"الجواب:\nالورع غيره، فالزهد معناه: عدم الاستكثار، فكونه يزهد فيها يعني: لا تشغله عن الآخرة، والورع: ترك المشتبهات.","link":"https://binbaz.org.sa/fatwas/22170/هل-الزهد-اخص-من-الورع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الزهد أخص من الورع.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2055,"question":"ما الفرق بين زهده ﷺ وورعه في الدنيا؟","title":"الفرق بين زهده عليه الصلاة والسلام وورعه في الدنيا","answer":"الزهد في الشيء الذي لا حاجةَ إليه، ولا أهميةَ له. والورع: ترك المشتبهات.","link":"https://binbaz.org.sa/fatwas/22173/الفرق-بين-زهده-عليه-الصلاة-والسلام-وورعه-في-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين زهده عليه الصلاة والسلام وورعه في الدنيا.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2062,"question":"أيّهما أفضل: طلب التَّقلُّل من الدنيا أم التَّزود من الأموال؟","title":"هل طلب التزود من المال أفضل أم التقلّل؟","answer":"الجواب:\nإذا كان يريد العملَ بطاعة الله ونفع المسلمين فعليه أن يعمل بالأسباب، إذا لم تشغله عن الآخرة، فيعمل وينفع الناس، مثلما فعل الصَّحابةُ: أبو بكر الصديق، وعمر، وعبدالرحمن بن عوف، وغيرهم، فقد أنفقوا في سبيل الله، وأحسنوا، ولم تشغلهم الدنيا عن الآخرة.","link":"https://binbaz.org.sa/fatwas/22180/هل-طلب-التزود-من-المال-افضل-ام-التقلل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التقلل من الدنيا أفضل أم التزود من الأموال.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2065,"question":"الأصل في الزهد في اللغة؟","title":"ما معنى الزهد وحقيقته؟","answer":"الجواب:\nالزهد في الشيء: عدم التَّعلق به، وعدم المبالاة به.\nعرفتم معنى الزهد، وأنَّ معناه: عدم التَّعلق بالدنيا، وعدم إيثارها على الآخرة، وليس معناه: تركها وعدم التَّسبُّب، لاـ يتسبب ويعمل ويستغني عن الناس، كما قال ﷺ: احرص على ما ينفعك، واستعن بالله رواه مسلم في \"الصحيح\"، ولما سُئل: أيُّ الكسب أطيب؟ قال: عمل الرجل بيده، وكل بيعٍ مبرور، وقال في حديث الزبير: لأن يأخذ أحدُكم حَبْلَه فيأتي بحزمةٍ من حطبٍ على ظهره، فيبيعها، فيكفّ بها وجهه؛ خيرٌ له من سؤال الناس، أعطوه أو منعوه.\nفعليه أن يطلب الرزق ويعمل لأولاده وأبويه، فيتعاون معهم بالحكمة والكلام الطيب، ويتعاون بالأسباب الشَّرعية: من البيع والشِّراء، والزراعة، والنِّجارة، والحدادة، وما يقدر عليه، فيعمل حتى يساعدهم، ولكن تكون الآخرةُ أكبر همِّه، فيُؤدِّي فرائضَ الله، ويترك محارمَ الله، ويحرص على عمل الآخرة، لا تشغله الدنيا عن الآخرة، فقد شغلت أكثرَ الخلق عن الآخرة.","link":"https://binbaz.org.sa/fatwas/22183/ما-معنى-الزهد-وحقيقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الزهد وحقيقته.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2072,"question":"لو كان العبدُ يستطيع أن يشتري من المتاع لبيته شيئًا ما وتقلَّل من ذلك كما روي عن بعض الصحابة أنه فعل ذلك، يعني: يكون المتاع الصالح ينتظره في الآخرة؟","title":"حكم الزيادة والتقلُّل من متاع الدنيا","answer":"الجواب:\nالمهم أن يبتعد الإنسان عمَّا يشغله عن الآخرة، أمَّا إذا كان لا يشغله، بل ينفع به الناس؛ من بيع، أو شراء، أو عقار، أو غير ذلك؛ فهو ينفع الناس، ولما سُئل ﷺ: أي الكسب أطيب؟ قال: عمل الرجل بيده، وكل بيع مبرور، وقال ﷺ: احرص على ما ينفعك، واستعن بالله، فإذا كان عمله ينفع -سواء بيع، أو شراء، أو مُزارعة، أو بيع دوابّ، أو بيع متاع آخر، أو غير ذلك- فيفعله ما دامت فيه مصلحةٌ ومنفعةٌ للمسلمين، يرجو به ثوابَ الله، فهو على خيرٍ عظيمٍ، والمؤمن على خيرٍ في أعماله كلها إذا نوى بها وجهَ الله والدار الآخرة.","link":"https://binbaz.org.sa/fatwas/22190/حكم-الزيادة-والتقلل-من-متاع-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التقلل من المتاع في الدنيا ليكون المتاع الصالح ينتظر العبد الصالح في الآخرة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2080,"question":"لو ماتت امرأةٌ وليس لها زوجٌ، وكانت من أهل الجنة، هل ستتزوج من المؤمنين؟","title":"هل مَن ماتت دون زوج تُزَوَّج في الجنة؟","answer":"الجواب:\nهذا إلى الله، فكلٌّ يقع مطلوبه في الجنة، لهم فيها ما يدَّعون، النساء والرجال، أي: لهم ما يطلبون، فالرجل يُعْطَى ما يطلب، والمرأة تُعْطَى ما تطلب، كلهم في نعيم.","link":"https://binbaz.org.sa/fatwas/22198/هل-من-ماتت-دون-زوج-تزوج-في-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماتت وليس لها زوج هل ستتزوج من المؤمنين في الجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2084,"question":"هل يُؤخذ في وقتنا هذا أنَّ النوم على الحصير من السُّنة؟","title":"هل النوم على الحصير من السُّنة؟","answer":"الجواب:\nلا، ما هو من السنة، إنما يكون حسب الحاجة.\nس: ومَن كان مُقتدرًا لكنَّه يجعل له أيامًا ينام فيها على الحصير؟\nج: إذا أراد أن يتَّعِظَ ويُحاسِب نفسه ويُجاهدها لا بأس، من باب محاسبة النفس وتذكيرها بحال الفقراء، وإلا فلو رزقه الله الطيبات فالحمد لله، فالله قال: كُلُوا مِنَ الطَّيِّبَاتِ [المؤمنون:51].","link":"https://binbaz.org.sa/fatwas/22202/هل-النوم-على-الحصير-من-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النوم على الحصير.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2093,"question":"ترجم المؤلفُ بـ\"فضل الجوع\" للباب، هل للجوع فضلٌ في ذاته؟","title":"هل للجوع فضل؟ وما صلته بالزهد؟","answer":"الجواب:\nنعم، الزهد في الزيادة التي تشغله عن الآخرة، والزهد في الحرام والمكروهات، والزهد فيما يصدّ عن الآخرة، مثلما قال ﷺ: ازهد في الدنيا يُحِبُّك الله، وازهد فيما عند الناس يُحبُّك الناس.\nس: والحديث الذي ورد فيه تعوّذ النبي ﷺ من الجوع، قال: اللهم إني أعوذ بك من الجوع؟\nج: هذا ما يُنافيه، فالزهد لا يستدعي الجوع.","link":"https://binbaz.org.sa/fatwas/22211/هل-للجوع-فضل-وما-صلته-بالزهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للجوع فضل في ذاته.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2146,"question":"إذا كان العبدُ قد اغتسل في هذا اليوم اغتسالًا لأجل التَّطهر لا لأجل الجمعة، ثم صلَّى الجمعة، فهل الصّواب أن الطهارة تعمّ الأمرين؟","title":"حكم مَن اغتسل للتطهر فقط يوم الجمعة","answer":"الجواب:\nلا، بسالغُسل، إذا كان ما توضأ ما يصح، فلا بد أن يتوضأ الوضوء الشرعي، أما الجنابة –عند جمعٍ من أهل العلم- إذا نواهما جميعًا انتقل إلى الصنف الأكبر، إذا كان جنابةً.\nس: يعني: يُعيد الصلاةَ التي صلَّاها بهذا الغُسل؟\nج: نعم، يُعيدها ظهرًا.","link":"https://binbaz.org.sa/fatwas/22265/حكم-من-اغتسل-للتطهر-فقط-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الاغتسال لرفع الحدث يعم اغتسال الجمعة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2180,"question":"التَّسَتُّر حال الاغتسال عريانًا يكون أفضل أو ..؟","title":"هل يُشرع التَّسَتُّر حال الاغتسال؟","answer":"الجواب:\nالاغتسال عُريانًا لا بأس به، فالنبي ﷺ كان يغتسل عريانًا، واغتسل موسى عريانًا، واغتسل أيوب عريانًا.\nس: ومَن قال أن الاغتسال عريانًا جائز، ولكن التَّستر أفضل؟\nج: لا، لا بأس بالاغتسال عريانًا، أما التَّسَتُّر فقد يشقّ عليه؛ لأنَّ التَّسَتُّر  قد يطبع ثيابه أو يملؤها بالماء.\nس: لكن لا بأس؟\nج: الأمر واسع إذا كان في حجرةٍ ولا يراه أحدٌ.","link":"https://binbaz.org.sa/fatwas/22301/هل-يشرع-التستر-حال-الاغتسال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الاغتسال عريانا.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2230,"question":"ما أكبر سببٍ في الحثِّ على الإخلاص لله؟","title":"ما أكبر سبب في الحث على الإخلاص؟","answer":"الجواب:\nالعمل لا يُقبل إلا إذا كان خالصًا لله، أما إذا كان لغيره فلا يُقبل.\nس: قال: ما السّبب؟\nج: لأنَّ العبد يتقرب به إلى الله، فالعبادات قربة إلى الله، ما تنفع ولا تُقبل ولا تصحّ إلا إذا كانت لله، فلا يُقبل منه إذا صلَّى لغير الله، أو صام لغير الله، أو ما صام ولا صلَّى ولا أدَّى العبادة: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ [البينة:5]، وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، فلا بد أن ينوي بقلبه أنَّ هذه الصلاة لله، أو هذا الصوم لله، أو هذه الصدقة لله، أو التَّسبيح، أو ما أشبه ذلك، يرجو ثواب الله.\nس: والتقوى؟\nج: طاعة الله، وترك معصيته، فالمتَّقي هو الذي أطاع الله وترك المعاصي.","link":"https://binbaz.org.sa/fatwas/22353/ما-اكبر-سبب-في-الحث-على-الاخلاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أكبر سبب في الحث على الإخلاص.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2604,"question":"الجنة فيها تكليف..... التسبيح والتكبير من باب التكليف؟","title":"هل في الجنة تكليف مثل التسبيح والتكبير؟","answer":"الجواب: نعيم، يسبّحون الله، نعيم يتنعّمون به، لكل واحد زوجتان من الحور العين غير زوجاته من الدنيا، كل واحد من أهل الجنة له زوجتان من الحور العين غير ما يُعطى من الزوجات والحور العين الأخرى، يعني لا ينقص واحد عن زوجتين مع زوجات الدنيا مع ما يعطيهم الله من الزوجات الأخرى.\nس: هل يقال أن في الجنة تكليف؟\nالشيخ: ما في تكليف، هي دار نعيم، التسبيح نعيم يتلذّذون به.","link":"https://binbaz.org.sa/fatwas/22738/هل-في-الجنة-تكليف-مثل-التسبيح-والتكبير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل في الجنة تكليف.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2605,"question":"إذا رأى بعض الناس رجلًا صالحًا وقال: إن شاء الله أنك من أهل الجنة، هل فيها شيء؟","title":"هل يجوز الحكم للرجل الصالح بالجنة؟","answer":"الجواب: أحسن أن يقول: أرجو أن تكون من أهل الجنة، وإلا ما فيها شيء إن شاء الله، لكن: أرجو أن تكون من أهل الجنة؛ كلام طيب.","link":"https://binbaz.org.sa/fatwas/22740/هل-يجوز-الحكم-للرجل-الصالح-بالجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم للرجل الصالح بالجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2609,"question":"بالنسبة لللرجل يكون له زوجتان من الحور العين.. وبالنسبة مثلًا إذا كانت الزوجة زوجها غير صالح...؟","title":"كيف تكون أحوال الأزواج في الجنة؟","answer":"الجواب: زوجاته في الجنة الله جلا وعلا أعلم، فيها ما تشتهي الأنفس وتلذ الأعين، وأزواجهم مختلفة، أحد عندهم مئات الزوجات، وأحد عنده آلاف الزوجات، وأحد عنده أقل من ذلك، لكن كل واحد لا يَنْقُص من زوجتن من الحور العين غير ما يُعطى من الزيادة.\nس:هل أهل الدرجة الأقل يرون الدرجة العليا؟\nالشيخ: الله أعلم، ما يُعطى مِثْل مَلِك من ملوك الدنيا وخمسة أمثاله، وفي اللفظ الآخر: وعشرة أمثاله، وله ما اشتهت نفسه ولذّت عينه.\nس: الزوجة في الدنيا إنْ كانت صالحة وزوجها صالح هل يُجمع بينهما في الجنة؟\nالشيخ: يُرجى ذلك، في بعض الأحاديث أنها تخيرّ، إذا كان لها أزواج تختار أحسنهم خلقًا، ولكن الأحاديث في هذا فيها بعض النظر، والله أعلم به ، والأقرب والله أعلم أنها لزوجها إن كان ما لها إلا زوج واحد ومات وهي راضية عنه وهو راض عنها؛ فالأقرب والله أعلم أنها تكون له، مثل ما أن أزواج النبي ﷺ في الجنة هم أزواجه في الآخرة، غير ما يعطيه الله من الزيادة، أما إن كان لها أزواج فالله أعلم، جاء في بعض الروايات أنها تخيّر، تختار أحسنهم خلقًا؛ فإن صح فهو واضح، ولكن في سنده بعض المقال.","link":"https://binbaz.org.sa/fatwas/22744/كيف-تكون-احوال-الازواج-في-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأزواج في الجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2613,"question":"هل الرؤيا تختص لبعض أهل الجنة أكثر من بعض؟","title":"هل يتفاوت المؤمنون في رؤية ربهم بالجنة؟","answer":"الجواب: كل أهل الجنة يرونه، لكن يتفاوتون فيها، بعضهم أعلى وأكثر.\nس: عدد المرات؟\nالشيخ: أقول بعضهم أكثر، على حسب تقواهم وإيمانهم ومنازلهم في الجنة، منهم من يراه بُكْرة وعَشِيًّا، بمنزلة البُكْرة والعَشِي.","link":"https://binbaz.org.sa/fatwas/22748/هل-يتفاوت-المومنون-في-روية-ربهم-بالجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفاوت المؤمنين في رؤية ربهم عز وجل في الجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2614,"question":"بالنسبة ليوم الجمعة؟","title":"ما يوم المزيد في الجنة؟","answer":"الجواب: يسمونه يوم المزيد، هذا يوم يزور ربهم فيه جل وعلا على منابر وعلى مجالس متفاوتة، ومع هذا كل أحد يرى أنه قد أعطي ما لم يعط الآخر، ما أحد يرى فضل ولا نقص ولا حزن، كلهم في نعيم، وكلهم في مجالسهم وفي زيارتهم، لا يرون أن هناك شيئًا من النقص عليهم أو الضيم لهم، كل راض بما هو فيه، مرتاح بالنعيم الذي هو فيه، يرى أنه قد أعطي ما لم يعط غيره. لأنها دار نعيم وليست دار حزن ولا دار مفاخرة ولا دار هضم، بل هي دار نعيم دائم.","link":"https://binbaz.org.sa/fatwas/22749/ما-يوم-المزيد-في-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يوم المزيد في الجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2619,"question":"هل لتارك الصلاة توبة؟ وكيف تكون؟","title":"هل لتارك الصلاة توبة؟ وكيف تكون؟","answer":"الجواب: كل عاصٍ له توبة، وكل كافر له توبة، ولا يوجد مَن لا توبةَ له، فعليه أن يتوب إلى الله، ويندم، ويحافظ على الصلوات، يندم على ما مضى، ويعزم ألا يعود، ويستغفر ربَّه، ويسأل ربَّه العفو، ويُصلي، والحمد لله.","link":"https://binbaz.org.sa/fatwas/22754/هل-لتارك-الصلاة-توبة-وكيف-تكون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لتارك الصلاة توبة، وكيف تكون.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2676,"question":"هل المُحْتَلِم لا تَقْرَبُه الملائكة؟","title":"ما صحة أن المُحْتَلِم لا تَقْرَبُه الملائكة؟","answer":"الجواب: النبي ﷺ لما جاءه أبو هريرة وحذيفة وانْخَنَسا منه قال ﷺ: إن المسلم لا يَنْجُس فالجنابة معنى من المعاني ما هي بنجاسة، معنى من المعاني تُوجِب الغُسل، وهكذا الحيض يوجب الغُسل، والمرأة طاهرة عرقها طاهر وريقها طاهر وما مسته طاهر وشعرها طاهر، وهكذا الجُنُب عرقه طاهر وبدنه طاهر، لكن عليه أن يغتسل كما أمره الله.","link":"https://binbaz.org.sa/fatwas/22814/ما-صحة-ان-المحتلم-لا-تقربه-الملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المحتلم لا تقربه الملائكة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2748,"question":"قول أن نية المؤمن أبْلَغُ من عمله؟","title":"ما صحة القول: نية المؤمن أبْلَغُ من عمله؟","answer":"الجواب: من كلام بعض السلف، مأخوذة من بعض الأحاديث، مستنبطة من حديث الأعمال بالنيات وأن العبد له ما نوى، وأنه إذا نوى العمل الطيب ثم حبسه عذر صار له أجر العاملين، كما في الحديث الصحيح: إذا مرض العبد أو سافر كتب الله له ما كان يعمل وهو صحيح مقيم، وفي الحديث: إن في المدينة أقوامًا ما سلكتم طريقًا ولا قطعتم شِعْبًا إلا وهو معكم حَبَسَهُمُ العُذْرُ يعني مع النية الصالحة.","link":"https://binbaz.org.sa/fatwas/22896/ما-صحة-القول-نية-المومن-ابلغ-من-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نية المؤمن أبلغ من عمله.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2762,"question":"يكون يأخذ أجر النية وإلا أجر العمل كاملًا؟","title":"هل أجر النية الصادقة مثل أجر العمل كاملًا؟","answer":"الجواب: أجرهم على نيتهم، نية الجهاد، يعطون مثل المجاهدين.\nس: هناك بعض العلماء فرق قال: إن كان يعمل هذا العمل قبل العذر أو قبل المرض ونوى؛ فيكتب له كامل الأجر، وإن كان لم يكن يعمله سابقًا ونوى يُكتب له أجر النية؟\nالشيخ: ظاهر الحديث الصحيح أنه يكتب له أجر المجاهدين، قال: شركوكم في الأجر، كانوا معكم حبسهم العذر.\nس: وذكروا مثال الصلاة إن كان يتنفل؟\nالشيخ: له أجرها، إذا تركها من أجل السفر والمرض له أجرها، إذا مرض العبد أو سافر كتب الله ما كان يعمل وهو صحيح مقيم، رواه البخاري في الصحيح؛ من فضل الله ورحمته.\nس: وإذا كان لا يعمل هذا الشيء ولكنه نوى أنه لو كان صحيحًا لذهب للصلاة أو تنفل أو كذا؟\nالشيخ: النبي ﷺ قال: ما كان يعمل، ما كان قد استقر له، أما الجديد فله مستقبله، لكن يُرجى له إذا كان عازمًا على عمل وحبسه العذر يُرجى له الأجر.","link":"https://binbaz.org.sa/fatwas/22910/هل-اجر-النية-الصادقة-مثل-اجر-العمل-كاملا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أجر النية في العمل الصالح.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2826,"question":"إذا كان إنسان على ضلالة ثم تاب: هل عليه وِزْرُ مَن تَبِعه حتى بعد التوبة؟","title":"هل يلحق المُفْسِد بعد توبته وِزْرُ مَن تَبِعه؟","answer":"الجواب: يُرجى له العافية إن شاء الله، إذا تاب يُرجى له إن شاء الله السلامة؛ لأن التوبة تجب ما قبلها، والحمد لله، وعليه يُبَيِّن رجوعَه.\nس: العلمية هل تدخل من ضمنها؟\nالشيخ: إن شاء الله تدخل.\nس: من قال إن عليه الوِزْر حتى بعد التوبة، وِزْرُ مَن تَبِعه؛ لحديث ابن آدم أنه تاب وعليه وزر مَن قتل بعده؟\nالشيخ: ما يظهر لي، الرسول ﷺ قال: التائب من الذنب كمن لا ذنب له، والتوبة تَجُبُّ ما قبلها، وابن آدم ما ندري تاب وإلا ما تاب، عندك خبر أنه تاب؟!","link":"https://binbaz.org.sa/fatwas/22975/هل-يلحق-المفسد-بعد-توبته-وزر-من-تبعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كان على ضلالة ثم تاب فهل عليه وزر من تبعه بعد التوبة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2864,"question":"في حديث عائشة في غسل الجنابة في آخر الحديث: ثم يغسل رجليه بعد أن يتوضأ يؤخر غَسل الرجلين؟","title":"حكم تأخير غَسل الرِّجلين في غُسل الجنابة","answer":"الجواب: هذا أفضل، وضوء كامل أولًا، ثم يغتسل، ثم يغسل رجليه من باب الكمال بعدما ينالها من أوساخ الجسد ونحوه، وإن توضأ وخلى الرجلين حتى يُكمّل الغسل ثم غسلها؛ كلها جاء، في حديث ميمونة وفي حديث عائشة، كله طيب. لكن الأكمل: يتوضأ وضوء كاملًا ثم يغسلهما غسلة أخرى، هذا الأفضل.\nس: بعض العلماء يقول أنه شاذ؛ لأنه لا معنى لغَسل الرجلين؟\nالشيخ: لا، ما هو شاذ، هو ثابت في الصحيحين.","link":"https://binbaz.org.sa/fatwas/23017/حكم-تاخير-غسل-الرجلين-في-غسل-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تأخير غسل الرجلين في غسل الجنابة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2892,"question":"متى يُؤجَر الرجل على نيته فيُعْطَى فضلَ ما لم يُدْرِك؟","title":"متى يُؤجَر المرءُ على نيته بما لم يعمل؟","answer":"الجواب: دائمًا يؤجر على نيته الصالحة، ما هو بس متى، دائمًا يُؤجَر على نيته الصالحة.\nس: في بعض الأحاديث أنه يدرك مثل ما يدرك مَنْ له أعمال؟\nالشيخ: الأعمال بالنيات، وإنما لكل امرئ ما نوى، فإذا كان مِن نيته أن يعمل لو قَدِر؛ كُتِب الله له أجر ذلك، يقول ﷺ: إذا مرض العبد أو سافر كتب الله له ما كان يعمل وهو صحيح مقيم، وقال: إن في المدينة أقوامًا ما سرتم مسيرًا ولا قطعتم واديًا إلا وهم معكم حبسهم العذر وهو المرض، إذا كان له نية صالحة لولا العذر.\nس: أليس في الحديث دليل على أن بعض الأعمال لا تدخل في هذا؟\nالشيخ: ظاهر الأحاديث العموم، لكن إذا فعله يكون أفضل، إذا استطاع وفعله يكون أفضل؛ لأن الفقراء يستطيعون أن يعملوا؛ فلا يُعطون الأجر وهم يستطيعون أن يعملوا، لكن العاجز الذي ما يستطيع، مثل أخرس ما يستطيع يتكلم؛ يُعطى أجره ولو ما فعل.","link":"https://binbaz.org.sa/fatwas/23047/متى-يوجر-المرء-على-نيته-بما-لم-يعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يؤجر الرجل على نيته.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2954,"question":"أرجو من سماحتكم أن تخبرونا عن كيفية الغسل من الجنابة؛ لأن بعض النساء تقوم بغسل مؤخرة الرأس أي الشعر وتقول إنه يجوز ويكفي لغسل الشعر كله، أو تقوم بغسل بعض الشعر بأن يتخلل الماء مؤخرة الشعر أي بعضه، فهل هذا يجوز؟ أما أنها تغسل الشعر كله سواء كان الشعر مربوطًا أم مفكوكًا، أرجو أن تخبرونا عن كيفية الغسل؟","title":"ما كيفية الغُسل من الجنابة للنساء؟","answer":"الجواب: السُّنَّة أن يستنجي الإنسان، يستنجي أولًا بعد الجماع، ثم يتوضأ وضوء الصلاة، ثم يفرغ على رأسه الماء ثلاث مرات، ثم يغسل بقية جسده، يبدأ بالشق الأيمن قبل الأيسر حتى يكمل الغسل.  والمرأة يكفيها إذا أمرّت الماء على رأسها ثلاث مرات يكفي، قالت أم سلمة: يا رسول الله إني امرأة أشد شعر رأسي أفأنقضه لغسل الجنابة؟ وفي رواية الحيضة؟ قال: يكفيك أن تحثي على رأسك ثلاث حثيات ثم تفيضي عليك الماء فإذا أفاضت عليه ثلاث حثيات مر على جميعه فلا يلزم النقض، وهكذا الرجل لو كان له رأس يُفيض عليه الماء ولا يحتاج للنقض.","link":"https://binbaz.org.sa/fatwas/23110/ما-كيفية-الغسل-من-الجنابة-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية الغسل من الجنابة للنساء.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3029,"question":"علامة قسوة القلوب؟","title":"ما علامات قسوة القلوب وأسباب لِينِها؟","answer":"الجواب: المعاصي من أعظم أسباب قسوة القلوب؛ كلما زادت المعاصي سبّبت القسوة للقلوب، وكلما جاءت الطاعات صارت من أسباب لين القلوب. ومن أسباب لِين القلوب: كثرة ذكر الله جل وعلا، الإكثار من ذكر الله من أسباب لِين القلوب، كذلك قراءة القرآن والإكثار من قراءة القرآن الكريم، والكَفّ: كَفُ اللسان عما لا ينبغي، كل هذا من أسباب صلاح القلوب.","link":"https://binbaz.org.sa/fatwas/23189/ما-علامات-قسوة-القلوب-واسباب-لينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/علامة قسوة القلوب.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3061,"question":"كلام السلف في ذم الدخول على السلاطين على ماذا يُحْمَل؟","title":"على ماذا يُحْمَل ذمُّ الدخول على السلاطين؟","answer":"الجواب: على الذي يمدحهم ويوافقهم على باطلهم، مثل ما قال ﷺ: سيكون بعدي عليكم أمراء ظلمة فمن صدّقهم بكذبهم وأعانهم على ظلمهم فليس مني ولست منه، ومن لم يصدّقهم بكذبهم ولم يُعنهم على ظلمهم فهو مني وأنا منه. فإذا دخل عليهم بالتوجيه والإرشاد وتخفيف الشر؛ هذا هو المطلوب، أما إذا دخل عليهم ليعينهم على الظلم ويصدقهم بالكذب فهذا هو المذموم، نسأل الله العافية.\nكذلك في حديث \"لا يُبلغني أحد عن أحد شيئًا\" فهذا الحديث ضعيف فيه جهالة، وهو لو صح محمول على الشيء الذي ما يضر المسلمين، أما شيء يضر المسلمين فالواجب تبليغ ولي الأمر حتى يحتاط المسلمين، والحديث وإن كان ضعيفًا لما فيه من الجهالة، لكن يلاحظ معناه، المعنى الصحيح؛ فالمسلمون يبلّغون ولي الأمر الشيء الذي فيه مصلحة ولا يبلغونه الشيء الذي يضر ولا ينفع. ولهذا لما سمع زيد بن أرقم عبدالله بن أُبي يتكلم في بعض الأسفار: ليخرجن الأعز منها الأذل؛ بَلّغ النبي ﷺ ولم يُنكر عليه النبي ﷺ، بل أنزل الله تصديقه في القرآن.","link":"https://binbaz.org.sa/fatwas/23221/على-ماذا-يحمل-ذم-الدخول-على-السلاطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/على ماذا يحمل كلام السلف في ذم الدخول على السلاطين.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3106,"question":"إذا شخص نائم سمع الأذان ولكن عقله ما كان معه، يعني كاملًا، ما هو الحكم في هذا؟","title":"حكم مَنْ سمع الأذان نائمًا ثم غلبه النوم","answer":"الجواب: ما قام يصلي؟\nس: لا، ولكن عقله ما كان كاملًا.\nالشيخ: عليه التوبة إلى الله والحذر، يحط ساعة وإلا غيرها، وإلا يعلّم أهله يقوّمونه، أو يحط ساعة تساعده حتى يستعين بها على أداء ما فرض الله.","link":"https://binbaz.org.sa/fatwas/23266/حكم-من-سمع-الاذان-ناىما-ثم-غلبه-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحذر من سماع الأذان وعدم القيام للصلاة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3172,"question":"الشخص إذا جمع بين الوضوء والغسل كما ذكرتم آنفا فإنه لا محالة أنه يمس بعد أن يتوضأ، ربما يمس فرجيه؟","title":"ما كيفية الجمع بين الوضوء والغسل؟","answer":"الجواب: لا يمسهما، يستنجي قبل، ويكفي، يستنجي يغسل فرجيه قبل، ثم الأفضل يتوضأ وضوء الصلاة، فإن كان ما توضأ ونوى الغسل والوضوء جميعًا؛ أجزأ عند جمع من أهل العلم، يدخل الأصغر في الأكبر.","link":"https://binbaz.org.sa/fatwas/23335/ما-كيفية-الجمع-بين-الوضوء-والغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الوضوء والغسل.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3190,"question":"يشترط عدم ارتكاب الكبائر (لتكفير السيئات)؟","title":"هل اجتناب الكبائر شرطٌ لتكفير السيئات؟","answer":"الجواب: نعم إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] لابدّ، وفي الحديث الصحيح عن النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان كفارات لما بينهن إذا اجتنبت الكبائر وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/23353/هل-اجتناب-الكباىر-شرط-لتكفير-السيىات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اجتناب الكبائر شرط لتكفير السيئات.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3255,"question":"حديث عائشة رضي الله عنها لما قالت: «كنت أغتسل أنا ورسول الله ﷺ من إناء واحد كلانا جُنُب»، فهل يدل هذا على جواز غسل الرجل مع زوجته ولو كان في ضوء النهار؛ لأن بعض الفقهاء قال: ما يدريك فعل النبي ﷺ كان يغتسل هو وعائشة رضي الله عنها في الليل، ولم يكن لديهم ضوء؟","title":"حكم غُسل الرجل مع زوجته جميعًا","answer":"الجواب: لا، هذا لا بأس به، الله أباح له الجماع، والجماع أعظم من النظر، له أن ينظر إليها وتنظر إليه ويغتسلان جميعًا مكشوفين؛ لأن الله أباح لها عورته وأباح له عورتها، فلا بأس في الليل والنهار، لكن إذا كان مستورين عن الناس.","link":"https://binbaz.org.sa/fatwas/23419/حكم-غسل-الرجل-مع-زوجته-جميعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم غسل الرجل مع زوجته جميعا.mp3","categories":["الغسل","قضايا المرأة"]},{"id":3372,"question":"ما ورد الوعيد في تأخير الغُسْل من الجنابة؟","title":"ما حكم تأخير الغُسْل من الجنابة؟","answer":"الجواب: ما أتذكر شيئًا، التأخير إذا كان ما فيه مانع، لو جامع في أول الليل جاز التأخير إلى آخر الليل، النبي ﷺ كان يؤخر عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23539/ما-حكم-تاخير-الغسل-من-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تأخير الغسل من الجنابة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3396,"question":"هل هذا الحديث (حتى أقبل على الجدار، فمسح...) يدل على جواز التيمم من أجزاء الأرض المتولدة كالطين، والرخام، وغيره؟","title":"هل يجوز التيمم بالطين والرخام ونحوهما؟","answer":"الجواب: جنس التراب، سواء في الجدار، أو في الأرض، وإذا دعت الحاجة إلى غيره كالذي في الأرض سبخة، أو في أرض رمل؛ تيمم منها، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]؛ لعموم الحديث، وعموم الآية: فَلَمْ تَجِدُوا [النساء:43].","link":"https://binbaz.org.sa/fatwas/23567/هل-يجوز-التيمم-بالطين-والرخام-ونحوهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث .. حتى أقبل على الجدار، فمسح بوجهه.. هل يدل على جواز التيمم من أجزاء.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3759,"question":"أمة محمد ﷺ فتنتها في المال؟","title":"هل فتنة أمة محمد ﷺ في المال؟","answer":"الجواب: في المال نعم، يقول النبي ﷺ: اتقوا الدنيا، واتقوا النساء؛ فإن أول فتنة بني إسرائيل كانت في النساء اللهم صل عليه وسلم، وهذه الأمة فتنتها في المال وفي النساء أيضًا، على خطر الذي يقع لهم في النساء شر كثير، نسأل الله العافية، ولهذا في الحديث الصحيح: ما تركت بعدي فتنة أضر على الرجال من النساء في الصحيحين.\nولهذا قال في حديث أبي سعيد: فاتقوا الدنيا واتقوا النساء.","link":"https://binbaz.org.sa/fatwas/23951/هل-فتنة-امة-محمد-ﷺ-في-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فتنة أمة محمد في المال.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3767,"question":"يكون موتهم (الأطفال) من الأسباب المكفّرة للذنوب؟","title":"هل موت الأطفال من أسباب دخول الجنة؟","answer":"الجواب: هذه كلها معلّقة، منها من أسباب دخولهم الجنة، تحريمهم على النار، من باب توفيقهم للأعمال الصالحة، ومن باب تكفير السيئات، ومن باب الجمع بينهما.\nس: تجري بهم أعمالهم على الصراط؟\nالشيخ: نعم هي مصيبة، والمصيبة يترتب عليها أشياء كثيرة، قد يترتب عليها توفيق الله العبد لعمل صالح عظيم بسبب صبره واحتسابه وإخلاصه وغير ذلك، وقد يترتب عليها مع ذلك أيضًا تكفير السيئات؛ لأنها من أسباب تكفير السيئات وحط الخطايا، وقد يترتب عليها الأمران جميعًا: توفيق الله له لعمل صالح، وما يحصل له من التكفير.","link":"https://binbaz.org.sa/fatwas/23960/هل-موت-الاطفال-من-اسباب-دخول-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا مات طفل على شخص، من أسباب دخول الجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3773,"question":"ما يدل على الوجوب قوله: أحوط (أي: الغُسل بعد الجِماع وإن لم يُنْزِل)؟","title":"هل يجب الغُسل بعد الجِماع وإن لم يُنْزِل؟","answer":"الجواب: محتمل، لكن السنة ثابتة، الواجب هو الغُسل، وإن لم ينزل، وإذا أنزل وجب عليه الغُسل. لكن إذا لم ينزل فالواجب الغُسل؛ لأن الرسول ﷺ أوضح لهم آخرًا، وأبو هريرة ممن أسلم آخرًا، وحديث عائشة صريح في أنه إذا مس الختان الختان فقد وجب الغسل، وقال: كنت أفعله مع هذه فأغتسل لما سئل عليه الصلاة والسلام، كلها رواها مسلم، وغيره، والرواية في الصحيحين.\nس: ابن حجر ذكر في الشرح قال: قول النبي الماء من الماء قال المراد بالماء الأول ماء الغسل، والثاني المني هذا صحيح؟\nالشيخ: نعم هذا المراد.","link":"https://binbaz.org.sa/fatwas/23969/هل-يجب-الغسل-بعد-الجماع-وان-لم-ينزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب الغسل بعد الجماع وإن لم ينزل.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3839,"question":"هل لا بدّ من النية؟","title":"هل تُشترط النية للكفارات عند المصائب؟","answer":"الجواب: الظاهر لا، الكفارات ليس من شرطها النية، المصائب ولو من غير نية، لكن إذا كان عن نية واحتساب وصبر يعني قارن ذلك؛ يحصل له مزيد ثواب.","link":"https://binbaz.org.sa/fatwas/24041/هل-تشترط-النية-للكفارات-عند-المصاىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشترط النية للكفارات عند المصائب.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3974,"question":"الغدرات التي غدر بها الإنسان ثم تاب منها ورجع؟","title":"ما حكم غدرات الإنسان قبل التوبة؟","answer":"الجواب: هذا في غير التائب، التائب يُعفى عنه، التائب انتهى أمره، هذه أشياء للذين أصروا ولم يتوبوا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24202/ما-حكم-غدرات-الانسان-قبل-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الغدرات التي غدر بها الإنسان ثم تاب منها ورجع.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4079,"question":"التكفير هنا للصغائر، إذا كان مصرًّا على الكبائر؟","title":"هل تكفَّر الصغائر للُمِصّر على الكبائر؟","answer":"الجواب: نعم، تُمنع؛ إصراره على الكبائر يمنع غفران الصَّغائر.\nس: ماذا يُغفر له؟\nج: لا يغفر له، يكون موقوفًا، ولهذا قال سبحانه: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31]، فعلَّق التَّكفير باجتناب الكبائر، وقال في حديث عثمان هذا، وفي الرواية الأخرى: ما لم تُصب في المقتلة يعني إن أصيب في المقتلة، هي الكبيرة؛ لم يُغفر له بوضوئه هذا وصلاته ركعتين... الصَّغائر والكبائر على الصحيح.  وقال بعضُ أهل العلم: تُمحى الصَّغائر، ولكن الشيء المعلّق بالشرط ما يقع؛ لأنَّ غفران الصغائر مشروط باجتناب الكبائر، فإذا وُجد الشرط انتفى المشروط، وهكذا قوله ﷺ: الصَّلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان؛ كفَّارات لما بينهن ما لم تُغش الكبائر، إذا اجتنب الكبائر معناه: أن الكبائر إذا غُشيت ولم تُجتنب؛ لم تكن هذه الصَّلوات كفَّارة، ولا الجمعة، ولا رمضان. س: ...... ماذا يبقى؟ ج: تكون حسنات، يُعطى حسنات، الأعمال الصَّالحات فيها حسنات، فيها خير، ومَن هو الذي يسلم منها؟! لأنَّ الكبائر كثيرة، ثم اختلفوا في حدِّها أيضًا، ويقول بعضُ الناس: أطلق الكبائر على كل ذنبٍ، لكنه ليس بصحيحٍ، الصواب أنَّ فيها كبائر وصغائر، لكن اختلفوا في حدِّ الكبيرة.","link":"https://binbaz.org.sa/fatwas/24318/هل-تكفر-الصغاىر-للمصر-على-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تكفير الصغائر لمن كان مصراً على الكبائر.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4080,"question":"الذي يأتي الكبائر ويُصلي النوافل ويُسبّح ويُهلل، هل له أجر في هذا؟","title":"هل يُؤجر على النوافل مَنْ يأتي الكبائر؟","answer":"الجواب: نعم، له الأجر الذي وعد الله به المؤمنين، لكن لا تُمحى عنه الصَّغائر إلا باجتناب الكبائر.","link":"https://binbaz.org.sa/fatwas/24319/هل-يوجر-على-النوافل-من-ياتي-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يؤجر الذي يأتي الكبائر ويُصلي النوافل ويُسبّح ويُهلل.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4081,"question":"التوبة من الصَّغائر لازمة؟","title":"هل التوبة من الصَّغائر واجبة؟","answer":"الجواب: نعم، التوبة من كل ذنبٍ: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8]، ويقول : وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ [النور:31]، خاطب المؤمنين وهو ما يكون مؤمنًا مع اقتراف الكبائر، يكون ناقص الإيمان.\nس: إذا اجتنب الكبائر، الصغائر يجب منها التوبة؟\nج: إذا اجتنب الكبائر ذهبت الصَّغائر، لكن إذا تاب منها كان ذلك من باب العناية والحذر؛ لأنه ما يدري هل سلم له إيمانه من الكبائر، أو عنده شيء، فالإنسان دائمًا على خطرٍ، فإن الغيبة والنميمة والربا وقطيعة الرحم والعقوق والسبّ والشتم وأشياء أخرى كلها داخلة في الكبائر، نسأل الله السلامة، ومَن يسلم من الغيبة؟!","link":"https://binbaz.org.sa/fatwas/24320/هل-التوبة-من-الصغاىر-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التوبة من الصَّغائر لازمة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4088,"question":"ما حصل من الدنيا ينقص الأجر يوم القيامة؟","title":"هل ينقص التمتع بملذات الدنيا من أجر الآخرة؟","answer":"الجواب: مثلما جاء في هذا الحديث: التمتع بملذَّاتها ونعيمها، والله المستعان، والله أعلم، هذه رواية ابن أبي الدنيا، يقول المنذري: بسندٍ حسنٍ والله أعلم، قد يحتجّ له بقوله جلَّ وعلا: وَيَوْمَ يُعْرَضُ الَّذِينَ كَفَرُوا عَلَى النَّارِ أَذْهَبْتُمْ طَيِّبَاتِكُمْ فِي حَيَاتِكُمُ الدُّنْيَا وَاسْتَمْتَعْتُمْ بِهَا [الأحقاف:20].\nويُروى عن عمر: أنه رأى جابرًا معه شيء من لحمٍ اشتراه للأهل، فقال: أوكلّما اشتهيتُم اشتريتُم؟! أما سمعتَ الله يقول لقومٍ: أَذْهَبْتُمْ طَيِّبَاتِكُمْ فِي حَيَاتِكُمُ الدُّنْيَا؟\nالمقصود أنه ينبغي للإنسان أن يفعل بعض الشيء من جهة التَّقلل، ومن جهة الزهد في بعض الشيء؛ حتى يُعوّد نفسه القناعة، لا يكون دائمًا دائمًا على شراء الملذات والطيبات، بل بعض الأحيان يتقشَّف بعض الشيء، ويتخفف بعض الشيء؛ حتى لا تعتاد النفسُ الرغبة في هذه الأشياء التي تُعتبر من ملذَّاتها العاجلة، ومن مشاغلها العاجلة، ومن التَّكلف حتى يحتاج إلى أموالٍ كثيرةٍ ربما سببت له الوقوع في أكسابٍ ما هي طيبة، أو اقتراض قد يشقّ عليه دفعه، وأما إذا يسَّر الله فالأمر واسعٌ بحمد الله، مثلما قال جلَّ وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ [البقرة:172]، الأمر واسع، وقال تعالى: يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا [المؤمنون:51]، فإذا كان عن يسرٍ، وعن عدم تكلُّفٍ؛ فالحمد لله.","link":"https://binbaz.org.sa/fatwas/24328/هل-ينقص-التمتع-بملذات-الدنيا-من-اجر-الاخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث لا يصيب عبد من الدنيا شيئا إلّا نقص من درجاته..mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4122,"question":"اليوم هذا يوم الجزاء: هل المؤمنين يكونوا مكسيين، أو عراة في الوقوف هذا؟","title":"متى يُكسى المؤمنون يوم القيامة؟","answer":"الجواب: يكونون عُراة، أولًا يُكسى إبراهيم عليه الصلاة والسلام.\nس: لا يأكلون ولا يشربون حتى المؤمنين في هذا اليوم العظيم؟\nج: الناس مشغولون بالهمِّ العظيم والله المستعان، أما وقت الكسوة الله أعلم، أولًا يُكسى إبراهيم، ثم يُكسى المؤمنون والأنبياء، لكن متى يكون هذا؟ الله أعلم: في أثناء اليوم، أو بعد دخولهم الجنة، الله أعلم.","link":"https://binbaz.org.sa/fatwas/24365/متى-يكسى المومنون-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بعض أهوال القيامة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4123,"question":"يُرفع القرآن.. أحسن الله إليك؟","title":"هل من علامات الساعة رفع القرآن والدين؟","answer":"الجواب: يُرفع القرآن، ويُرفع الدين كله، ما يبقى شيء، ما يبقى إلا الكفر -نسأل الله العافية- ولهذا قال: إذا طلعت الشمسُ من مغربها آمن الناسُ كلهم لكن لا ينفعهم ذلك؛ لأنَّ طلوعها من مغربها علامة ظاهرة، فلهذا إذا رآها الناسُ آمنوا كلهم، لكن لا ينفعهم، لا ينفع الذين كانوا كفَّارًا إيمانهم بعدما رأوا طلوع الشمس من مغربها، نسأل الله السلامة: يَوْمَ يَأْتِي بَعْضُ آيَاتِ رَبِّكَ لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا [الأنعام:158]، فالأمر محدد بطلوع الشمس من مغربها، متى طلعت من مغربها خُتم على الأعمال، فالمؤمن على إيمانه، والكافر على كفره -نسأل الله العافية- ثم يبعث الله ريحًا طيبةً مسّها مسّ الحرير، فتقبض أرواح المؤمنين والمؤمنات، فلا يبقَ إلا الأشرار، فعليهم تقوم الساعة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24368/هل-من-علامات-الساعة-رفع-القران-والدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من علامات الساعة رفع القرآن والدين كله.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4138,"question":"معرفة الرسول ﷺ لهم فيقول أصيحابي، يقصد معرفتهم بآثار الوضوء محجلين غرلًا؟","title":"كيف يعرف النبي ﷺ أصحابه في القيامة؟","answer":"الجواب: غُرْلًا مُحجَّلين، نعم، هذه علامة الأمة.","link":"https://binbaz.org.sa/fatwas/24385/كيف-يعرف-النبي-ﷺ-اصحابه-في-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يعرف النبي أصحابه في القيامة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4150,"question":"إقامة الحد مكفِّر أم لا بد من التوبة؟","title":"هل إقامة الحد مكفِّر أم لا بد من التوبة؟","answer":"الجواب: الحدود مُكفِّرات، التوبة مُكفِّرة، والحدود مُكفِّرات إذا لم يرجع إلى العمل، مُكفِّرة لما مضى، يعني: قبل الحدِّ.","link":"https://binbaz.org.sa/fatwas/24400/هل-اقامة-الحد-مكفر-ام-لا-بد-من-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحدود والتوبة مكفرات للذنوب.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4209,"question":"الذنوب التي مات ولم يتب منها؟","title":"حكم ذنوب المسلم التي مات ولم يتب منها","answer":"الجواب: كذلك مثل ما في الحديث، لما سترها عليه في الدنيا بينه وبين ربه  غفرها له  وقد تكون من الصغائر التي تغفر باجتناب الكبائر: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] فالعبد يجتنب الكبائر وتكفر عنه الصغائر، قد تكون سيئة بين العبد وبين ربه لم يطلع عليها سواه  ولم يقدر للعبد أن يتوب منها فغفرها الله له بجنب حسناته وأعماله الصالحة الكثيرة ورضا الله عنه لما فعل من الخير وصار قطرة في البحر، قطرة من نجاسة في بحر من الخيرات فعفا  عنه .","link":"https://binbaz.org.sa/fatwas/24472/حكم-ذنوب-المسلم-التي-مات-ولم-يتب-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الذنوب التي مات ولم يتب منها.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4215,"question":"في بعض الحالات يمر على العبد يطير شوقًا للموت ولقاء ربه جل وعلا، والحالة الثانية يكره الموت، ويكره كذلك...؟","title":"حكم كراهية المؤمن للموت","answer":"الجواب: هذا من طبيعة الناس كراهة الموت، من طبيعة الناس، مثلما قالت عائشة رضي الله عنها لما قال النبي ﷺ: من أحب لقاء الله أحب الله لقاءه ومن كره لقاء الله كره الله لقاءه فقالت عائشة: يا رسول الله أهو الموت فكلنا يكره الموت؟  فمن طبيعة الإنسان الغالبة عليه أنه يكره الموت ويحب الحياة، فالمؤمن يحب أن يزداد عملًا صالحًا، وغير المؤمن يحب أن يرتع في شهواته، قال: لا ولكنه المؤمن إذا حضره أجله وبشر بالجنة أحب لقاء الله فأحب الله لقاءه والكافر إذا حضر أجله وبشر بالنار كره لقاء الله وكره الله لقاءه أو كما قال عليه الصلاة والسلام.  فإذا وقع في قلب الإنسان بعض الأحيان اشتياق إلى الموت ليلقى ربه؛ لما وقع في قلبه من حسن الظن بالله والشوق إلى لقائه والرغبة فيما عنده ولما يشاهده في الدنيا من الشر والبلاء والفساد والخطر، هذا قد يقع للمؤمن، ولكن مع هذا كله لا يجوز له أن يطلب الموت ولا أن يتمناه كما في الأحاديث الصحيحة النهي عن ذلك، ولكن هذا من رحمة الله له، ومما يعجّله الله له من اللذة والسرور والنعيم.","link":"https://binbaz.org.sa/fatwas/24479/حكم-كراهية-المومن-للموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أهو الموت فكلنا يكره الموت.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4410,"question":"غسل الرجل مع امرأته يكون سُنةً؟","title":"حكم غسل الرجل مع امرأته","answer":"الجواب: جائز، جائز، حكمه الجواز.\nس: ما يكون سنةً؟\nج: محل نظرٍ، النبي فعله يدل على جوازه، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24687/حكم-غسل-الرجل-مع-امراته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم غسل الرجل مع امرأته.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4422,"question":"المني إذا خرج من غير شهوةٍ؟","title":"ما حكم المني إذا خرج من غير شهوةٍ؟","answer":"الجواب: إذا خرج لأجل المرض يكون الحكم حكم الأبوال، ..... الحكم حكم سائر الفضلات التي تخرج من الإنسان؛ توجب الوضوء.","link":"https://binbaz.org.sa/fatwas/24700/ما-حكم-المني-اذا-خرج-من-غير-شهوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المني إذا خرج من غير شهوةٍ.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4467,"question":"الاستدلال بحديث عائشة: افعلي ما يفعل الحاج إلا أن تطوفي بالبيت على جواز مسّ المصحف بغير طهارة؟","title":"(افعلي ما يفعل الحاج) هل يعمّ مسّ المصحف؟","answer":"الجواب: ما هو بكفء، هذا عام مخصوص، أقول: عام مخصوص، العمومات ما تنقض الخاص، ولا تُبطل الخاص.","link":"https://binbaz.org.sa/fatwas/24745/افعلي-ما-يفعل-الحاج-هل-يعم-مس-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستدلال بحديث افعلي ما يفعل الحاج، إلا أن تطوفي بالبيت على جواز مسّ المصحف.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":4474,"question":"هل يُباشر الوضوء قبل مُباشرة الغسل، وقد يمسّ فرجه للتنظيف؟","title":"حكم مس الفرج بعد الوضوء وقبل الغسل","answer":"الجواب: ما يمس، إذا استنجى لا يمس فرجه، انتهى، إذا استنجى وغسله بنية الطهارة انتهى، لكن لو غسل ما حوله، ومسح يده على ما حوله... ما يضره.\nس: يعني: يُباشر الوضوء، يعني: قبل مُباشرة الغسل يبدأ بالوضوء؟\nج: ... نعم: ثم يتوضأ وضوء الصَّلاة.","link":"https://binbaz.org.sa/fatwas/24753/حكم-مس-الفرج-بعد-الوضوء-وقبل-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الوضوء قبل مُباشرة الغسل، ومس الفرج.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4481,"question":"نقض الشعر لغسل الحيض يجب؟","title":"حكم نقض الشعر لغسل الحيض","answer":"الجواب: لا، مُستحبٌّ فقط، ولهذا في حديث أم سلمة عند مسلم: \"أفأنقضه من الحيض؟\" قال: لا، إنما يكفيك أن تحثي.","link":"https://binbaz.org.sa/fatwas/24761/حكم-نقض-الشعر-لغسل-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم نقض الشعر لغسل الحيض.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":4529,"question":"مَن جرَّ ثوبه دائر أمره بين كبيرةٍ صغرى وكبيرةٍ كبرى أكبر منها، يعني... إن جرَّ ثوبه خُيلاء: كبيرة؟","title":"هل تتفاوت كبائر الذنوب وصغائرها؟","answer":"الجواب: الكبائر تختلف، حتى الكبائر نفسها تختلف، تتفاوت، أقول: الكبائر تختلف.\nس: يعني على كلتا الحالتين تكون كبيرةً؟\nج: نعم، هذا ظاهر النصوص: \"النائحة\" النياحة كبيرة، والزنا أكبر منها، والعقوق كبيرة، وقطيعة الرحم الأخرى - العقوق لغير الوالدين- أسهل من الوالدين، وهكذا؛ فالكبائر متفاوتة، والصَّغائر متفاوتة.","link":"https://binbaz.org.sa/fatwas/24809/هل-تتفاوت-كباىر-الذنوب-وصغاىرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كبائر الذنوب وصغائرها تتفاوت.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4749,"question":"بالنسبة للشرط الأخير من شروط التوبة الذي هو: ردّ المظالم، يقول: أنا فقير لا أستطيع أن أردَّ المظالم مثلًا من سرقةٍ؟","title":"حكم من لا يستطيع رد المظالم","answer":"يستحلّه منها، فإذا عجز عن ذلك فالله يعلم تمام عزمه، إذا عزم على ذلك عفا الله عنه، إذا عجز عنها ولم يسمحوا عنك فالله يُسامحك، إذا صدق في التوبة؛ لأنَّ العاجز الصَّادق كالمؤدي.","link":"https://binbaz.org.sa/fatwas/25089/حكم-من-لا-يستطيع-رد-المظالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من شروط التوبة ردّ المظالم، فما حكم من أراد التوبة وهو فقير لا يستطع رد ما أخذه.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4806,"question":"إذا اغتسل ناويًا التَّبرد، ونوى الوضوء هل يُجزئ؟","title":"هل يُجزئ غسل التَّبرد عن الوضوء؟","answer":"ما يُجزئ، لا بدّ من الوضوء الشرعي.","link":"https://binbaz.org.sa/fatwas/25201/هل-يجزى-غسل-التبرد-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من اغتسل ناويًا التَّبرد ونوى الوضوء فهل يُجزئ.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4966,"question":"هل يكون فيه غفران بلا توبة؟","title":"هل يمكن حصول الغفران لأحد دون توبته؟","answer":"الجواب: قد يغفر الله بلا توبة، قال تعالى: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] قد يغفر الله له فضلًا منه أو لأعمال صالحة فعلها أو لمعروف بذله أو لتفريج كربة لمسلم أو لصدقة فعلها أو لأسباب أخرى.\nس: قول بعض السلف: ما أظن اللهَ أن يغفر للمأمون إدخاله كتب اليونان؟\nالشيخ: كل هذا ما يجوز.","link":"https://binbaz.org.sa/fatwas/27666/هل-يمكن-حصول-الغفران-لاحد-دون-توبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يمكن الغفران لأحد دون توبته.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4973,"question":"أعمال القلب \"الخَطَرات\" تسجلها الملائكة؟","title":"هل تسجّل الملائكة خطرات القلب؟","answer":"الجواب: الخَطَرات التي ما تستقر الظاهر ما تُسجل، ما يٌسجل إلا العمل الذي يستقر، إما فعل وإلا قول.","link":"https://binbaz.org.sa/fatwas/27969/هل-تسجل-الملاىكة-خطرات-القلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تسجّل الملائكة خطرات القلب؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4975,"question":"يقول: هل يصح الغسل من الجنابة إذا كانت الأصابع فيها طلاء؟","title":"حكم الطلاء والجبيرة عند الغُسل والوضوء","answer":"الجواب: إذا كان عليها شيء يُزال، مناكير أو غيره، الملصوقات التي تكون عبثًا ما هي بضرورة تُزال، أما الجبيرة يُمِر عليها الماء، لكن إذا كانت لُصوقات مناكير أو أشياء لصقت بالجلد طين أو عجين يُزال في الغسل والوضوء جميعًا. \nأما إذا كان لعِلة دواء جرح، لعلة أو جبيرة، لاـ يُمِر عليه الماء ويكفي، أو يمسح إذا كان ما يستطيع الماء، يمسح ويكفي مثل ما في الوضوء، أما إذا كانت لُصوقات ما لها لزوم مناكير أو عجين أو طين أو أشباه ذلك؛ فهذه تُزال في الغسل وتُزال في الوضوء جميعًا.","link":"https://binbaz.org.sa/fatwas/28044/حكم-الطلاء-والجبيرة-عند-الغسل-والوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الطلاء والجبيرة عند الغسل والوضوء.mp3","categories":["الغسل","الحيض والنفاس","قضايا المرأة"]},{"id":5048,"question":"العبد إذا كان مُعافًى من الذنب أفضل أم إذا كان يُذنب ويتوب وهو يُعاني من نفسه ويُجاهدها مجاهدةً عظيمةً في الله؟","title":"هل العافية من الذنب أفضل أم جهاد النفس؟","answer":"الجواب: المحتوى: مَن رزقه الله العافيةَ والسلامة؛ فهو أفضل بلا شكٍّ.","link":"https://binbaz.org.sa/fatwas/29287/هل-العافية-من-الذنب-افضل-ام-جهاد-النفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل العافية من الذنب أفضل أم جهاد النفس؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":5063,"question":"ضابط الصغائر ومثالها؟","title":"ما ضابط الصغائر والكبائر من الذنوب؟","answer":"الجواب: فيها اختلاف، في ضبط الصغائر، ينبغي للمؤمن أن يحذر السيئات كلها بالكلية؛ فالواجب على المؤمن أن يحذر السيئات كلها بالكلية صغيرها وكبيرها؛ حتى لا يقع في شيء من الكبائر، نسأل الله العافية.\nوالأكثر في تعريف الكبيرة أنها: ما فيه حد في الدنيا أو وعيد في الآخرة؛ كالسرقة والزنا والخمر، ما فيه حد في الدنيا أو وعيد في الآخرة؛ والغيبة والنميمة، كلها فيها وعيد.\nس: ما ترون التنفير من الصغائر حتى لا يتساهل الناس؟\nج: الواجب الحذر من جميع الذنوب، ويعتبرها كبائر حتى يحذرها؛ لأن كل سيئة قد يظنها صغيرة وهي كبيرة؛ فيجب الحذر.","link":"https://binbaz.org.sa/fatwas/29351/ما-ضابط-الصغاىر-والكباىر-من-الذنوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما ضابط الصغائر والكبائر من الذنوب؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":5082,"question":"هذا سائل يقول: وبعد إلى فضيلة الشيخ عبد العزيز أطال الله في عمره رب العالمين، وجعله سبحانه ذخرًا لهذه الأمة آمين لدي يا فضيلة الشيخ ثلاث مسائل أود الإجابة عليها.الأولى: أنني يا فضيلة الشيخ إنسان مؤمن بالرب، والحمد على ذلك، والصلاة أقوم بها، والصوم كذلك، والعمرة فقد اعتمرت حتى الآن ثلاثة عشر مرة، وعمري تسعة عشر سنة، ومنذ حوالي ست سنوات مضت أقوم بشيء لا يرضاه الرب، ولا رسوله، وهو - والعياذ بالله - اللواط، والعادة السرية، ففي عامنا الفائت، وفي إجازة الربيع (1404هـ) ذهبنا إلى مكة لأخذ عمرة فصممتُ التوبة لله عن هاتين العادتين السيئتين، فتبتُ، ولله الحمد على ذلك، فلما أتى رمضان في نفس العام، أخذتُ عمرةً أيضًا، والمشكلة حينما انتهى رمضان عدتُ للعادة السرية فقط، ولم أرجع للواط، وحينما دخل عامنا (1405هـ)، وبدأت اختبارات نصف السنة التي قد مضت منذ ما يقرب الشهرين عُدت - والعياذ بالله - إلى عادة اللواط، وتركتُها، وأود من فضيلتكم الإفتاء في ذلك، وإفادتي أفادكم الله، حتى أتوب إلى الله توبة نصوحًا، وكيف الطريق إلى ذلك؟","title":"حكم من تاب من الفواحش والمنكرات ثم رجع إليها","answer":"الجواب: الله جلَّ وعَلا حرَّم علينا الفواحش ما ظهر منها وما بطن، وأوجب علينا التوبة النصوح من جميع الذنوب، فقال : وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، وقال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8]، وقال سبحانه: أَفَلا يَتُوبُونَ إِلَى اللَّهِ ويَسْتَغْفِرُونَهُ واللَّهُ غَفُورٌ رَحِيمٌ [المائدة:74] هذه الآيات وما جاء في معناها كلها تدل على وجوب التوبة، وأنه  قد فتح أبوابها، ويسّرها لعباده. فعليك أيها السائل أن تتقي الله، وأن تجزم بالتوبة، وتصدق بالتوبة، وأن تبتعد عن نقضها، وأن تحذر مكائد الشيطان، فإن الشيطان عدو مبين، وله نواب من الإنس يدعون إلى الفواحش والمنكرات ويحبّبونها، ويحبّبون نقض التوبة، ويقولون: إن الله غفور رحيم، إن الله تواب حكيم، إن الله كذا، إن الله كذا؛ حتى يوقعوك فيما حرم الله، وقد ينزل بك الأجل، وأنت على معاصي الله ، فيحال بينك وبين التوبة، ولا حول ولا قوة إلا بالله. فالواجب عليك أن تجزم على التوبة، وتصدق في التوبة من اللواط، ومن العادة السرية، هذان محرمان، واللواط أعظم وأشنع؛ لأن اللواط من كبائر الذنوب، ومن أعظم الجرائم، جاء في الحديث: لعن الله من عمل عمل قوم لوط، لعن الله من عمل عمل قوم لوط، لعن الله من عمل عمل قوم لوط، وقال الله في كتابه العظيم عن اللوطية: إِنَّكُمْ لَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُمْ بِهَا مِنْ أَحَدٍ مِنَ الْعَالَمِينَ [العنكبوت:28] فأخبر أن اللوطية ما سبقهم أحد، قوم لوط، ما سبقهم أحد إلى هذه الفاحشة ممن قبلهم، نسأل الله العافية، وفي الحديث: من وجدتموه يعمل عمل قوم لوط، فاقتلوا الفاعل والمفعول به، وقد أجمع علماء الصحابة رضي الله عنهم على أن اللائط والملوط به يُقتلان إذا كانا مكلَّفَين؛ لأنها جريمة أشنع من جريمة الزنا، والعياذ بالله. فيجب الحذر، والتوبة الصادقة، والبُعد عن أسباب ذلك، وعن مخالطة من يدعو إلى ذلك، أو يجر إلى ذلك، أو تتوق النفس إلى فعل ذلك معه، يجب الحذر من أولئك؛ فإن صحبة الأشرار من أعظم أسباب الشر، ومن أعظم دواعي الشر، فيجب البُعد عن صحبة الأشرار، ويجب الحرص على صحبة الأخيار، مع سؤال الله الثبات، والتوفيق للاستقامة على التوبة، وعدم نقضها. وهكذا العادة السرية عادة قبيحة ومنكَرة، قال الله فيها وما في معناها: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ  ۝  إِلَّا عَلَى أَزْوَاجِهِمْ أو مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ  ۝  فَمَنِ ابْتَغَى ورَاءَ ذَلِكَ فَأُولَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7] أي: الظالمون، والعادة السرية غير الزوجة، وغير ملك اليمين، فتكون من العدوان والظلم، وفيها مضار كثيرة كما بيَّن أهل العلم، وبيَّن أهل الطب. فيجب عليك الحذر منها؛ لأنها عادة سيئة منكَرة، فإياك وإياها، واحذرها، واحذر من يشير بها، أو يدعو إليها. نسأل الله لنا ولك الهداية والثبات على الحق والصدق في التوبة.","link":"https://binbaz.org.sa/fatwas/29984/حكم-من-تاب-من-الفواحش-والمنكرات-ثم-رجع-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 01.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":5233,"question":"أخ يسأل ويقول: ما علاج قسوة القلب؟","title":"ما علاج قسوة القلب؟","answer":"الجواب: قسوة القلب له علاجٌ كثير، أعظم ذلك: الإقبال على الله بقراءة كتابه العظيم، وتدبر معانيه، والإكثار من ذكره ، والعناية بما أوجب الله من الصلاة وغيرها، والحذر مما حرَّم الله.......، وتأثر العبد بذكر الله وقراءة كتابه، واعتنى بما أوجب الله عليه من الصلاة وغيرها، وابتعد عن محارم الله...... كما قال : أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَنْ تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللَّهِ وَمَا نَزَلَ مِنَ الْحَقِّ وَلَا يَكُونُوا كَالَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلُ فَطَالَ عَلَيْهِمُ الْأَمَدُ فَقَسَتْ قُلُوبُهُمْ وَكَثِيرٌ مِنْهُمْ فَاسِقُونَ [الحديد:16]، فطول الأمد على مَن قبلنا حتى ضيَّعوا وتكاسلوا هو الذي قسَّى قلوبهم، ومَن قصَّر الأمل، واتَّبع شرع الله، وابتعد عن محارم الله؛ ليَّن اللهُ قلبَه، وشرح صدره، واستقام على الطريق. وفي الحديث: لا تُكثروا الكلام بغير ذكر الله، فإنَّ كثرة الكلام بغير ذكر الله قسوةٌ للقلوب، وإن أبعد القلوب من الله القلب القاسي، فالإكثار من الكلام، والقيل والقال والخوض بغير حقٍّ من أسباب قسوة القلوب، والإكثار من ذكر الله وقراءة كتابه والاستغفار والاستكثار من الأعمال الصَّالحات بعد أداء الفرائض وترك المحارم؛ كل هذا من أعظم الأسباب، بل هو السبب الوحيد في لين القلب والسلامة من قسوته. ومما يدل على هذا المعنى: قوله ﷺ: إذا أذنب العبدُ نكت في قلبه نكتة سوداء، فإن هو تاب مُحيت وصُقِلَ قلبُه، وإن عاد في الذنوب نكت نكتة أخرى سوداء، وهكذا حتى يسود القلبُ، وحتى يُظلم القلبُ، قال: وذلك الران وتلا قوله تعالى: كَلَّا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ [المطففين:14]، هذا معنى الحديث. المقصود أن الذنوب من أسباب سواد القلب وظلمته وقسوته، والتوبة إلى الله وتعاطي الأعمال الصَّالحة من أسباب صفائه ولينه وقوته وغيرته وسلامته.","link":"https://binbaz.org.sa/fatwas/30177/ما-علاج-قسوة-القلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 301.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":5308,"question":"بعض النساء يُشكل عليها الغسل من الجنابة والحيض، نرجو من سماحتكم تفصيل كيفية الغسل، وهل تطهر المرأة من الجنابة إذا حثت على رأسها ثلاث حثيات، وهل يلزمها غسل جميع الرأس بالماء؟","title":"ما صفة الغسل من الجنابة والحيض والنفاس؟","answer":"الجواب: الجنب والحائض والنفساء كلهم غسلهم متقارب، تعم بدنها بالماء وتفيض على رأسها الماء، لكن السُّنة أن يبدأ بالوضوء، يستنجي أولًا، الحائض تستنجي والنفساء والجنب، تستنجي أولًا، ثم يتوضأ وضوء الصلاة ثم يفيض الماء على رأسه ثلاث غرفات، ثم على جنبه الأيمن ثم جنبه الأيسر ثم يُكمل، هذا السُّنة ولا حاجة إلى نقض الرأس، لكن الحائض يستحب لها النقض؛ لأن مدتها تطول، والنفساء، فإذا نقضت كان أفضل في الغسل فتغسله بالماء، فإن أمرّت عليه الماء من غير نقض فكفى. فالحاصل أن المقصود هو إفاضة الماء على البدن، فإذا أفاض الماء على بدنه بنية غسل الحيض أو غسل الجنابة أو غسل النفاس؛ كفى، لكن الأفضل أنه بعد الاستنجاء يتوضأ وضوء الصلاة، ثم يفيض الماء على رأسه ثلاث غرفات يعمها على الرأس، ثم جنبه الأيمن ثم جنبه الأيسر، ثم بقية بدنه حتى يكمل، الجنب والحائض والنفساء، لكن النفساء والحائض يستحب لهما النقض، في بعض الأحاديث النقض (انقضي رأسك) فإذا نقضت كان أفضل مع الماء والسدر، والجُنب لا يحتاج إلى سدر، الماء يكفي.[1]","link":"https://binbaz.org.sa/fatwas/30962/ما-صفة-الغسل-من-الجنابة-والحيض-والنفاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 028.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":5390,"question":"الرجل يُسَرُّ من ثناء الناس؟","title":"هل يتنافى الإخلاص مع السرور بثناء الناس؟","answer":"الجواب: لا يضرُّه إذا كان لم يعمل من أجلهم، مثلما قال النبي: تلك عاجل بشرى المؤمن، إذا سُرَّ به ولم يعمل لأجلهم، ولكن سمعوا أنه يدعو إلى الله فدعوا له وأثنوا عليه، سمعوا أنه يتصدق فدعوا له وأثنوا عليه، ولكنه ما قصدهم؛ ما يضره، هذه عاجل بُشرى المؤمن. س: قول مَن قال: إن علامة الإخلاص أن يستوي عندك الذم والمدح؟ ج: لا، ما هو شرط، إذا استبشر بدعاء الناس ما يضرّ، تلك عاجل بُشرى المؤمن.[1]","link":"https://binbaz.org.sa/fatwas/31131/هل-يتنافى-الاخلاص-مع-السرور-بثناء-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 006.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":5562,"question":"الدلك في الغسل والوضوء؟","title":"ما حكم الدلك في الغسل والوضوء؟","answer":"الجواب: نعم الدَّلك مستحب، ليس بواجبٍ، جاء في بعض الأحاديث أنَّ النبي كان يدلك ذراعيه ﷺ، فلا بأس إذا دلك من باب الاستحباب، لكن الغالب -غالب فعل النبي ﷺ- ليس فيه دلك، يمر الماء فقط؛ لأنها أرفق بالمسلمين، فمرور الماء يكفي، وإذا دعت الحاجةُ إلى الدلك فلا بأس. س: في الغسل كذلك؟ ج: وفي الغسل كذلك إذا مرَّ الماء كفى على البدن كله، وإن وجد أشياء تحتاج إلى دلكٍ دَلَكَ: كمحلٍّ فيه طين، فيه عجين، فيه أشياء يُزيلها، يدلكها حتى تزول.[1]","link":"https://binbaz.org.sa/fatwas/31514/ما-حكم-الدلك-في-الغسل-والوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 002.mp3","categories":["الغسل","فروض الوضوء وصفته"]},{"id":5564,"question":"إذا اغتسل من الجنابة قبل أذان الفجر ونوى يوم الجمعة؟","title":"هل يجزئ الغسل قبل الفجر للجنابة والجمعة؟","answer":"الجواب: لا، إذا كان قبل الفجر لا، يغتسل يوم الجمعة، إذا اغتسل من الجنابة في الليل قبل الفجر ما يكفي، يُستحب له غسل الجمعة بعد الأذان عند ذهابه إلى الجمعة. س: ولو كان بعد الفجر؟ ج: بعد الفجر يكفي، وإذا اغتسل عند ذهابه إلى الجمعة طيب؛ لأن بينهما مسافة.[1]","link":"https://binbaz.org.sa/fatwas/31516/هل-يجزى-الغسل-قبل-الفجر-للجنابة-والجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 004.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":5566,"question":"إذا غسل يديه ورجليه خرّت خطاياه مع الماء أو مع آخر قطر الماء، يدل على أنَّ الأفضل عدم التنشيف لخرور الخطايا؟","title":"ما حكم التنشيف في الوضوء والغسل؟","answer":"الجواب: خرور الخطايا هذا عند الغسل، وهذا بعد ذلك، عند غسله تخرّ الخطايا مثلما في الحديث، لكن إن تنشف بعد ذلك هذه رطوبة باقية. س: التنشيف ما ثبت إلا في الغسل فقط؟ ج: المعروف في الغسل من حديث ميمونة. س: في الحديث الثاني، هذا يقول: لم يكن النبي ﷺ يعتاد تنشيف أعضائه بعد الوضوء ولا صح عنه في ذلك حديث البتة، بل الذي صح عنه خلافه؟ ج: ما أعلم في هذا شيئًا، لا التنشيف، ولا عدمه، إنما جاء في الغسل: أتته بمنديل فردَّه وجعل ينفض الماء بيديه، وأما في الوضوء ما أحفظ فيه شيئًا، الأمر فيه واسع. س: في الغسل الأفضل عدم التَّنشيف؟ ج: هذا هو، نعم، ينفض الماء بيديه مثلما في حديث ميمونة في الصحيح. س: وجعل ينفض الماء بيديه؟ ج: هذا السنة. س: نفض الماء، ما تخلص منه؟ ج: هذا السنة، نفض الماء بيديه وعدم التَّمسح.[1]","link":"https://binbaz.org.sa/fatwas/31518/ما-حكم-التنشيف-في-الوضوء-والغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 006.mp3","categories":["فروض الوضوء وصفته","الغسل"]},{"id":5574,"question":"المُكره على الجماع؟","title":"هل يجب الغسل على مَن أُكره على الجماع؟","answer":"الجواب: محل نظرٍ والله أعلم، إن خرج المني يغتسل، لكن إذا أُكره ولا خرج مني هذا محل نظرٍ، ولعلَّ الغسل أقرب؛ لأنه شمله: إذا مسَّ الختانُ الختانَ، لعله أقرب.\nوكذلك النائم إذا علم أنه أدخل فرجه، قد يقال أنه يغتسل احتياطًا وإن كان ما قصد، أما الوجوب فمحل نظرٍ؛ لأنه ما عنده قصد ولا فعل شيئًا.[1]","link":"https://binbaz.org.sa/fatwas/31526/هل-يجب-الغسل-على-من-اكره-على-الجماع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 014.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":6160,"question":"هل يكفي غسل الجنابة عن غسل الجمعة؟","title":"حكم الاكتفاء بغسل الجنابة عن غسل الجمعة","answer":"الجواب: نعم إذا كان في النهار يكفي، لكن إذا نواهما جميعًا فهو أفضل، ينويهما جميعًا، يغتسل عن الجنابة ناويًا معه غسل الجمعة.","link":"https://binbaz.org.sa/fatwas/1590/حكم-الاكتفاء-بغسل-الجنابة-عن-غسل-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_485.mp3","categories":["صلاة الجمعة","الغسل"]},{"id":6161,"question":"إذا مات إنسان وهو جنب، هل تجزئه غسلة واحدة، أم غسلتين؟","title":"حكم جمع أكثر من نية في غسل واحد","answer":"الجواب:  بسم الله الرحمن الرحيم ، اللهم صل وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد: فهذا يسأل عن الميت إذا كان جنبًا، هل يغسل مرتين، أم يكفي غسل واحد؟  والجواب: أنه يكفي غسل واحد ينويه الغاسل عن الجنابة، وعن الموت جميعًا، كما لو حاضت المرأة، وعليها جنابة، ثم اغتسلت بعد الحيض بنية الحيض، والجنابة. فالمقصود: أن هذا يكفي غسل واحد بنية واحدة، الغاسل ينوي هذا وهذا، ينوي الجنابة، وينوي الموت، ويكفي.","link":"https://binbaz.org.sa/fatwas/1608/حكم-جمع-اكثر-من-نية-في-غسل-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_502.mp3","categories":["فروض الوضوء وصفته","الغسل"]},{"id":6747,"question":"هل يجوز مسح الوضوء، أم تركه أفضل؟ وإذا أقيمت الصلاة والإنسان في نافلة، فماذا يصنع؟","title":"حكم التنشيف بعد الوضوء وبعد الغسل من الجنابة","answer":"الجواب: الأمر واسع، من نشف؛ فلا بأس، ومن ترك؛ فلا بأس، فلم يجيء في هذا شيء صحيح فيما نعلم، لا في التنشيف ولا في كراهة التنشيف، الأمر فيه واسع. أما غسل الجنابة فقد ورد عن النبي ﷺ أنه عرض عليه المنديل؛ فرده، وجعل ينفض الماء بيده، في غسل الجنابة -عليه الصلاة والسلام- هذا أفضل، ينفض الماء بيده، أما الوضوء فلم يثبت فيه شيء فيما نعلم، فمن نشف؛ فلا بأس، ومن ترك؛ فلا بأس، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/2616/حكم-التنشيف-بعد-الوضوء-وبعد-الغسل-من-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1112.mp3","categories":["الغسل","فروض الوضوء وصفته"]},{"id":7022,"question":"بعض المسلمين يخرجون أيام العطل خارج مدينة الرياض للنزهة، غير ناويين السفر، ويأخذون معهم قليلًا من الماء، وعند الصلاة يتيممون بدلًا من الماء؛ بحجة قلة الماء، علمًا أنه باستطاعتهم البحث عن الماء، أو حمله معهم أثناء الرحلة، فهل يجوز التيمم في هذه الحالة، وإذا كان لا يجوز، فما حكم هذه الصلاة بدون وضوء؟","title":"حكم التيمم للصلاة لبعد الماء أو قلته","answer":"الجواب:\n\nإذا خرجوا للنزهة، وحضرت الصلاة، وليست عندهم إلا ماء قليل بقدر حاجتهم -والماء بعيد عنهم- صلوا بالتيمم، ولو أنهم ما حملوه معهم، لكن إذا حملوه معهم يكون أفضل إذا تيسر، لكن ما كل أحد يتيسر له حمل الماء معه.\n\nفإذا تيسر الماء منهم قريب؛ وجب عليهم أن يتوضؤوا، وإذا كان بعيدًا معروفًا يشق عليهم الذهاب إليه، أو يضيعوا أوقاتهم لبعده عنهم؛ فلا حرج أن يتيمموا، وكان الصحابة يتيممون إذا كان الماء بعيدًا عنهم، يشق عليهم.","link":"https://binbaz.org.sa/fatwas/2958/حكم-التيمم-للصلاة-لبعد-الماء-او-قلته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1408.mp3","categories":["الغسل","التيمم"]},{"id":7448,"question":"ما حكم اللصفة، هل يمسح عليها عند الغسل من الجنابة؟ وهل يمسح عليها عند الوضوء إذا كانت على أحد أعضاء الوضوء؟","title":"حكم المسح على اللاصقة في الغسل وفي الوضوء","answer":"الجواب: نعم، ويقال لها: الجبيرة، واللزقة، كذلك التي توضع على الظهر، أو على البطن، أو على الجنب، إذا كان عليه غسل جنابة؛ يكفي جريان الماء عليها، إذا أجرى عليها الماء؛ كفى، وإذا كانت في محل الوضوء في القدم؛ كفى المسح عليها، والذراع؛ كفى المسح عليها، يمسح عليها عند غسل الذراع إذا كانت في الذراع، وإذا كانت في الوجه عند غسل الوجه، وإذا كانت في القدم؛ مر عليها الماء ومسحها بالماء عند غسل القدم، ويكفي ذلك ولا يحتاج معها إلى تيمم.","link":"https://binbaz.org.sa/fatwas/3540/حكم-المسح-على-اللاصقة-في-الغسل-وفي-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1845.mp3","categories":["فروض الوضوء وصفته","الغسل"]},{"id":7627,"question":"هذه الرسالة من الجمهورية العراقية ناحية التأميم، يقول مرسلها الطالب صالح عواد خلف: أقرأ القرآن الكريم وبعد عندي بيت أجلس فيه أقرأ القرآن الكريم وأصلي فيه، وبعض الأحيان يصير عندي جنابة هل يجوز أن أغتسل في هذا البيت وأن البيت متروك، فيه كتب دينية، وأنا عمري ستة عشر سنة أو أكثر، أرجو الإفادة وفقكم الله؟ المقدم: أعد.المقدم: يقول: إنه يجلس في بيت غير مسكون، ويوجد فيه كتب دينية، وأيضاً بعض الأحيان تكون عليه جنابة، ويغتسل في هذا البيت، الذي فيه الكتب الدينية هل يجوز ذلك أم لا؟","title":"حكم الاغتسال من الجنابة في بيت مهجور به كتب إسلامية","answer":"الجواب: لا حرج في ذلك، لا بأس في ذلك يغتسل، إذا كان فيه ماء، وتيسر له الغسل فيه فلا بأس؛ لأن جعله للمطالعين والمراجعين نوع من الإذن في استعمال الماء في الوضوء والغسل والشرب، لما ترك للمطالعين والمراجعين في هذه الكتب فالمعنى أنهم يتوضئوا من هذا الماء ويغتسلون منه، ولا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4681/حكم-الاغتسال-من-الجنابة-في-بيت-مهجور-به-كتب-اسلامية ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_025/02503.mp3","categories":["شروح الحديث","الغسل"]},{"id":7726,"question":"سماحة الشيخ! هذه الرسالة وردتنا من الرياض من المستمع (ع. ع. ح) يقول عن دخول المرأة وزوجها الحمام وكل منهم يرى من الآخر عورته، فما حكم ذلك؟","title":"حكم اغتسال الزوجين وكل منهما يرى عورة الآخر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه نبينا وإمامنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين. أما بعد:\nفقد ثبت عن رسول الله عليه الصلاة والسلام أنه كان يغتسل مع أزواجه رضي الله عنهن وأرضاهن، وهذا يدل على جواز نظر الزوج إلى عورة زوجته وهي كذلك، وقد أباح الله له جماعها ومباشرتها فلا غرابة في ذلك، ولا كراهة في ذلك، فإذا اغتسلا جميعاً في الحمام أو في حجرة معينة وهما مكشوفا العورة فلا بأس بذلك. نعم، ولا حرج فيه.\nلكن فيما تقدم يلاحظ أن يكون الحمام ليس فيه من ينظر إلى عورتيهما، لا بد أن يكون هذا في محل خاص مستور ليس فيه إلا الزوج والزوجة، أما إذا كان هناك محل.. إذا كان في محل ينظر إلى عورتهما حرم عليهما ذلك، حرم عليه وعليها جميعاً، وإنما يكون الجواز فيما إذا كانا في محل مستور عن غيرهما. نعم..","link":"https://binbaz.org.sa/fatwas/4925/حكم-اغتسال-الزوجين-وكل-منهما-يرى-عورة-الاخر ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_032/03201.mp3","categories":["شروح الحديث","الغسل"]},{"id":7886,"question":"أيضاً هذا سؤال ومهم جداً؛ لأنه يرد لنا كثير من الأسئلة والاستفسارات حتى أنه معي الآن أكثر من (12) رسالة حول التبول بعد الجماع، يقول: هل يجب على الرجل أن يتبول بعد الجماع وقبل الوضوء والغسل مع الدليل وفقكم الله وجزاكم عنا ألف خير؟","title":"حكم التبول بعد الجماع وقبل الاغتسال","answer":"الجواب: النبي ﷺ أمر الجنب أن يتوضأ قبل النوم إذا فرغ من الجماع في الليل فالسنة له أن يتوضأ قبل أن ينام، ومعلوم أنه في ترتيب وضوئه يستنجي يبول بعد الجماع ويستنجي ثم يتوضأ وضوء الصلاة، ولا أعلم شيئاً فيه النص على البول وإنما هذا تابع إذا قام، إذا فرغ من جماعه شرع له أن يتوضأ، ومعلوم أن الذي يريد الوضوء لابد أن يغسل فرجه عما أصابه ويحصل البول حين يتبول ويستنجي ثم يتوضأ وضوء الصلاة، أما شيء منصوص عن البول خاصة فلا أعلم له أصلاً ولكن المشروع له أنه يستنجي يبول بعدما يفرغ من حاجته إذا ذهب للوضوء يبول ويستنجي ويغسل آثار ما أصابه من الأذى ثم يتوضأ وضوء الصلاة كما أخبرت عائشة رضي الله عنها: كان النبي ﷺ إذا فرغ يغسل فرجه ثم يتوضأ وضوء الصلاة ثم ينام ويغتسل في آخر الليل في الغالب عليه الصلاة والسلام، وربما اغتسل في أول الليل، لكن الغالب أنه يغسل فرجه ويتوضأ وضوء الصلاة ثم ينام، وقد أمر بهذا عليه الصلاة والسلام، سأله عمر فأمر عليه الصلاة والسلام الجنب أن يتوضأ ثم ينام. نعم.","link":"https://binbaz.org.sa/fatwas/5356/حكم-التبول-بعد-الجماع-وقبل-الاغتسال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_059/05904.mp3","categories":["شروح الحديث","الغسل"]},{"id":8672,"question":"تقول في سؤال آخر: قال الرسول ﷺ ما معناه لامرأة: اغسلي الدم وصلي أي: دم الحيض، فهل يكون هذا في أي وقت من أوقات نزول الدورة أم قرب انتهائها، وإذا اغتسلت وتطهرت منها وصليت فهل يحل الجماع أم لا؟","title":"معنى حديث: (اغسلي عنك الدم وصلي)","answer":"الجواب: هذا عند انتهاء الحيض، إذا انتهى الحيض أمرها النبي صلى الله عليه وسلم أن تغسل الدم وتغتسل وتصلي، إذا انتهت الدورة وفي ثوبها شيء غسلت ما أصاب الثوب، تقرصه بالماء تحكه بظفرها أو بحجر أو بعظم أو بغيره ثم تغسله بالماء ويطهر الثوب وتصلي فيه بعد ذلك، وكذلك إذا اغتسلت بعد ذلك بعد زوال الدم والطهر ووجود الطهر فإنها تصلي بعد ذلك وتحل لزوجها.\nالمقصود: أن هذا كله عند انتهاء الدورة إذا رأت الطهارة إما بالقصة البيضاء أو حشت بقطن ونحوه في الفرج فخرج نقياً فإنها تغتسل غسل الحيض وتغسل إن كان في بدنها شيء إذا كان أصاب فخذها أو رجلها شيء من الدم تغسله ثم تغتسل غسل الحيض وإذا أصاب ثوبها شيء أو سراويلها غسلته أيضاً وبعد هذا تصلي وتحل لزوجها. نعم.\nالمقدم: جزاكم الله خير، الحقيقة لها كلام بعد هذا يفهم منه أنها فهمت حديث الرسول صلى الله عليه وسلم بأن تغسل المرأة دمها وهي في أثناء الحيض ثم تصلي؛ لأنها تقول: هل كلما عاد علي الدم مرة أخرى طوال اليوم أغتسل وأصلي أم لا؟\nالشيخ: مادام الدم موجود لا تغتسلي، إنما الغسل يكون عند النهاية، أما مادام الدم يتكرر في الليل والنهار فأنت في الحيض حتى تنتهي المدة وتحصل الطهارة، فإذا انتهت المدة خمساً أو ستاً أو سبعاً أو ثمان حسب العادة، إذا انتهت العادة ورأت المرأة الطهارة ... الماء الأبيض، أو جعلت في فرجها شيء من القطن ثم أخرجته أو نحوه من الأشياء الدالة على نظافتها فإنها تغتسل، وتصلي وتحل لزوجها وتصوم إذا شاءت وانتهى الأمر، أما أنها تغتسل كل ساعة، لا ؛ لأن الدم يجري تارة ويقف أخرى ما دام المدة موجودة ما بعد انتهت المدة ولا رأت الطهارة فإنها لا تغتسل حتى تنتهي المدة وينقطع الدم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6810/معنى-حديث-اغسلي-عنك-الدم-وصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21415.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":8674,"question":"تقول في سؤال آخر: قال الرسول ﷺ ما معناه لامرأة: اغسلي الدم وصلي أي: دم الحيض، فهل يكون هذا في أي وقت من أوقات نزول الدورة أم قرب انتهائها، وإذا اغتسلت وتطهرت منها وصليت فهل يحل الجماع أم لا؟","title":"معنى حديث: (اغسلي عنك الدم وصلي)","answer":"الجواب: هذا عند انتهاء الحيض، إذا انتهى الحيض أمرها النبي صلى الله عليه وسلم أن تغسل الدم وتغتسل وتصلي، إذا انتهت الدورة وفي ثوبها شيء غسلت ما أصاب الثوب، تقرصه بالماء تحكه بظفرها أو بحجر أو بعظم أو بغيره ثم تغسله بالماء ويطهر الثوب وتصلي فيه بعد ذلك، وكذلك إذا اغتسلت بعد ذلك بعد زوال الدم والطهر ووجود الطهر فإنها تصلي بعد ذلك وتحل لزوجها.\nالمقصود: أن هذا كله عند انتهاء الدورة إذا رأت الطهارة إما بالقصة البيضاء أو حشت بقطن ونحوه في الفرج فخرج نقياً فإنها تغتسل غسل الحيض وتغسل إن كان في بدنها شيء إذا كان أصاب فخذها أو رجلها شيء من الدم تغسله ثم تغتسل غسل الحيض وإذا أصاب ثوبها شيء أو سراويلها غسلته أيضاً وبعد هذا تصلي وتحل لزوجها. نعم.\nالمقدم: جزاكم الله خير، الحقيقة لها كلام بعد هذا يفهم منه أنها فهمت حديث الرسول صلى الله عليه وسلم بأن تغسل المرأة دمها وهي في أثناء الحيض ثم تصلي؛ لأنها تقول: هل كلما عاد علي الدم مرة أخرى طوال اليوم أغتسل وأصلي أم لا؟\nالشيخ: مادام الدم موجود لا تغتسلي، إنما الغسل يكون عند النهاية، أما مادام الدم يتكرر في الليل والنهار فأنت في الحيض حتى تنتهي المدة وتحصل الطهارة، فإذا انتهت المدة خمساً أو ستاً أو سبعاً أو ثمان حسب العادة، إذا انتهت العادة ورأت المرأة الطهارة ... الماء الأبيض، أو جعلت في فرجها شيء من القطن ثم أخرجته أو نحوه من الأشياء الدالة على نظافتها فإنها تغتسل، وتصلي وتحل لزوجها وتصوم إذا شاءت وانتهى الأمر، أما أنها تغتسل كل ساعة، لا ؛ لأن الدم يجري تارة ويقف أخرى ما دام المدة موجودة ما بعد انتهت المدة ولا رأت الطهارة فإنها لا تغتسل حتى تنتهي المدة وينقطع الدم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6810/معنى-حديث-اغسلي-عنك-الدم-وصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21415.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":8989,"question":"نعود في هذه الحلقة إلى رسالة المستمع محمود أحمد الدوسة من العراق بغداد الزعفرانية، أخونا له أسئلة كثيرة تجاوزت الثلاثين سؤالًا، عرضنا جزءًا من أسئلته في حلقات مضت، وفي هذه الحلقة نعرض هذا السؤال يقول: هل ورد عن الرسول ﷺ حديث يحدد الوقت الذي كان يتوضأ فيه رسول الله ﷺ؟ وهل ورد حديث يحدد وقت الاغتسال؟","title":"هدي النبي عليه الصلاة والسلام في الوضوء والغسل","answer":"الجواب: لا أعلم شيئًا في هذا، لا أعلم أنه ورد عن الرسول صلى الله عليه وسلم حديث يحدد زمان غسله وزمان وضوئه بالدقائق؛ لا أعلم ذلك لكنه ما كان يتكلف عليه الصلاة والسلام، السنة دالة على أنه كان غير متكلف وغير موسوس عليه الصلاة والسلام، بل كان يتوضأ في مدة يسيرة، ويغتسل في مدة يسيرة وليس من جنس أعمال الموسوسين الذين يتنطعون ويتكلفون ويعذبون أنفسهم، بل هو صلى الله عليه وسلم في غاية من الكمال في أخلاقه وأعماله، فما كان يتكلف ولا يتنطع لا في غسله ولا في وضوئه عليه الصلاة والسلام، وهذا هو الواجب على المؤمن أن يكون بعيدًا عن التنطع والتكلف في الوضوء أو الغسل، بل يتوضأ في حالة حسنة ليس فيها تنطع وليس فيها جفاء، بل يتوضأ كما توضأ النبي صلى الله عليه وسلم مرة مرة أو مرتين مرتين أو ثلاثًا ثلاثًا ولا يزد على ذلك، وهكذا في الغسل: يستنجي، ثم يتوضأ وضوء الصلاة في حال الجنابة، ثم يغتسل يفرغ الماء على رأسه ثلاث مرات ثم على بدنه يبدأ بالأيمن ثم الأيسر.\nهذا هو المعروف من فعله عليه الصلاة والسلام، ولم يكن عنده تكلف، ولم يعرف عنه أنه كان يطيل البقاء في الحمام لهذا الأمر، بل كان عليه الصلاة والسلام وسطًا في كل أعماله وأقواله عليه الصلاة والسلام، نعم.\nالمقدم: هل كان غالب أحواله صلى الله عليه وسلم البقاء على الوضوء سماحة الشيخ؟\nالشيخ: كان الغالب هكذا، كان الغالب على أحواله الوضوء عليه الصلاة والسلام، كان يتوضأ لكل صلاة ثم شرع .. السواك، فكان يصلي الصلاتين والأكثر بوضوء واحد، «وفي يوم الفتح صلى عدة صلوات بوضوء واحد فسأله عمر عن ذلك فقال: عمدًا فعلت» ليعلم الناس أنه لا حرج في أن يجمع الصلوات بوضوء واحد، «وكان يجمع بين الصلاتين بوضوء واحد» في أسفاره عليه الصلاة والسلام وفي غيرها.\nفالحاصل أنه كان لا يتكلف في الوضوء والغسل ولا يتنطع، وكان ربما صلى الصلوات بوضوء واحد عليه الصلاة والسلام، والغالب عليه يتوضأ لكل صلاة عليه الصلاة والسلام، وربما قضى حاجته ولم يتوضأ كما ثبت في صحيح مسلم «أنه خرج من محل قضاء الحاجة فقدم له طعام فقيل له: أفلا تتوضأ؟ فقال: إني ما أريد الصلاة ثم أكل» فدل ذلك على أنه لا حرج أن يأكل الإنسان وهو على غير طهارة، لكن يستحب إذا كان جنبًا أن يتوضأ قبل الأكل قبل النوم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7147/هدي-النبي-عليه-الصلاة-والسلام-في-الوضوء-والغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_175/17505.mp3","categories":["الغسل"]},{"id":9025,"question":"هل الاغتسال في يوم الجمعة واجب لأنني قرأت حديثاً يوجب الاغتسال يوم الجمعة؟","title":"حكم الاغتسال ليوم الجمعة","answer":"الجواب: ذهب بعض أهل العلم إلى وجوب الاغتسال يوم الجمعة، واحتجوا بالحديث الذي أشرت إليه وهو قوله ﷺ: غسل يوم الجمعة واجب على كل محتلم، وذهب أكثر أهل العلم إلى أنه سنة وليس بواجب؛ لأحاديث جاءت في ذلك؛ منها: قوله ﷺ: من توضأ يوم الجمعة فبها ونعمت، ومن اغتسل فالغسل أفضل.\nومنها: قوله ﷺ: من توضأ يوم الجمعة ثم أتى المسجد فصلى ما قدر له ثم أنصت حتى يفرغ الإمام من خطبته ثم يصلي معه غفر له ما بينه وبين الجمعة الأخرى وفضل ثلاثة أيام، ولم يذكر فيه الغسل إنما ذكر الوضوء فدل ذلك على أن الوضوء مجزئ وأن الغسل ليس بواجب ولكنه سنة مؤكدة، وتأولوا قوله ﷺ: (واجب) يعني: متأكد، كما تقول العرب: حقك علي واجب، فهذا من باب التأكيد.\nفالأحوط للمؤمن أن يعتني بهذا وأن يجتهد في الغسل يوم الجمعة خروجاً من خلاف العلماء وعملاً بظاهر الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/7183/حكم-الاغتسال-ليوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14718.mp3","categories":["الغسل"]},{"id":9549,"question":"الرسالة السادسة والأخيرة في هذه الحلقة من (ع. ع. س) من الدمام من منطقة ابن خلدون، يقول: إذا كان الشخص نائماً واستيقظ ورأى على ثيابه ماءً أو آثار ماء لكنه لا يدري ما نوعه، وهو لا يفرق بين المني وغيره، وقد صلى ولم يغتسل ثم تذكر بعد ذلك أنه قد حلم حلماً جعله يحتلم، فماذا يجب عليه، هل يعيد الصلوات التي صلاها أم ماذا يعمل؟","title":"حكم من وجد بللاً في ثيابه ولم يعرف ماهيته","answer":"الجواب: نعم إذا كان عرف أنه مني يغتسل غسل الجنابة ويعيد الصلاة التي صلى، أما إن كان لم يتذكر شيئاً من ذلك والماء اشتبه عليه لا يعرفه هل هو مني أو بول فإنه يغسل ثوبه من باب الحيطة ولا يلزمه غسل الجنابة، إلا إذا غلب على ظنه أنه مني، أما إذا لم يعلم فإنه يدع ذلك ولا يلزمه غسل الثوب ولا الغسل من الجنابة إلا إذا عرف أنه بول أو عرف أنه مذي فيغسل الثوب، المذي يرش الثوب والبول يغسله غسلاً ويعصره والمني طاهر لا يجب غسله، لكن إذا فركه أو غسله يكون أولى وأفضل، فإن غلب على ظنه أنه مني وجب عليه الغسل، وإن غلب على ظنه أنه بول وجب عليه غسل الثوب والتنظف من هذا البول الذي أصاب فخذه أو أصاب غير ذلك.\nفالحاصل أنه إن عرف أنه مني أو غلب ظنه أنه مني فإنه يغتسل ويصلي ما فعل من الصلوات بغير غسل، وقد يتبين ذلك إذا كان عن ملاعبة أو تفكير عند النوم فإنه في الغالب يكون منياً أو مذياً والمني والمذي يختلفان، المني ماء غليظ يتبين والمذي ماء ضعيف يكون له أثر ..... في الثوب ولا يكون منياً، فهو ينبغي له أن يتحرى هذا الشيء ويحرص فإن ظهرت أمارات المني اغتسل وإن ظهرت أمارات المذي رش ثوبه وغسل ذكره وأنثييه واستنجى ويكفي هذا، وإن كان بولاً والبول لا يخفى أيضاً غسل الثوب غسل ما أصاب الثوب وغسل ما أصاب فخذه إن أصابه شيء ويكفيه الاستنجاء والوضوء الشرعي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7713/حكم-من-وجد-بللا-في-ثيابه-ولم-يعرف-ماهيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24612.mp3","categories":["الغسل"]},{"id":9559,"question":"هذه فائزة الطاهر منهل من السودان بعثت إلينا بهذه الرسالة تقول فيها: بعض النساء لدينا يمشطن شعورهن أي: يظفرنها، وعندما يغتسلن من الجنابة لا تفك المرأة ضفائرها، فهل يصح غسلها مع أن الماء لم يصل إلى كل منابت الشعر؟ أفيدونا أفادكم الله.","title":"حكم نقض المرأة ضفائر رأسها في غسل الجنابة والحيض","answer":"الجواب: نعم، إذا أفاضت الماء على رأسها كفى؛ سألت أم سلمة رضي الله عنها النبي ﷺ عن ذلك، فقالت: يا رسول الله! إني امرأة أشد شعر رأسي أفأنقضه لغسل الجنابة والحيضة؟ فقال: إنما يكفيك أن تحثي على رأسك ثلاث حثيات، ثم تفيضي عليك الماء فتطهرين فإذا حثت يعني على رأسها ثلاث مرات، يعني إذا غرفت على رأسها ثلاث مرات بالماء وسال عليه الماء كفى ذلك، وإن لم تنقضه يكفي أن يمر عليه الماء وعلى الظفائر ويكفي ذلك ولا حاجة إلى النقض. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7724/حكم-نقض-المراة-ضفاىر-راسها-في-غسل-الجنابة-والحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_270/27008.mp3","categories":["الغسل"]},{"id":9794,"question":"لها استفسار ثان في رسالتها تقول: إذا اغتسلت من الجنابة وانتهيت يخرج مني شيء من المني هل يجب علي إعادة الغسل؟","title":"حكم المني النازل بعد الغسل","answer":"الجواب: لا يجب، ما دام حصل غسل فهذا المني لا قيمة له؛ لأنه خرج بدون شهوة فحكمه حكم البول لا قيمة له، وإنما الغسل الواجب قد أدي فلا يضرك خروج المني الذي نشأ عن الجماع السابق، وهكذا الرجل لو اغتسل ثم خرج منه بعد ذلك مع البول لا يضره ذلك ما دام ناشئًا عن الجماع السابق، أما إن خرج عن شهوة جديدة أو ملامسة جديدة أو عن تقبيل أو نحو ذلك من أسباب خروج المني من شهوة فهذا مني جديد يغتسل له، إذا كان عن شهوة جديدة من نظر أو ملامسة أو تقبيل، فهذا يكون له حكم الجنابة الجديدة على من خرج منه ذلك أن يغتسل من رجل أو امرأة، أما إذا كان بقية الغسل السابق بقية الجنابة السابقة فلا يضر ولا يترتب عليه غسل.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7961/حكم-المني-النازل-بعد-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19610.mp3","categories":["الغسل"]},{"id":9811,"question":"وله استفسار أخير يقول فيه: عند الانتهاء من الاستحمام هل تصح الصلاة بدون إعادة الوضوء باعتبار أنه قد تطهر في الاستحمام؟ وهل في ذلك شرط إذا أردت أن يكفيني الاستحمام عن الوضوء؟","title":"حكم الغسل بنية الطهارة من الحدث الأكبر والأصغر","answer":"الجواب: اختلف أهل العلم في ذلك، والأرجح أنه إذا اغتسل للجنابة ناويًا الحدثين، إذا اغتسل عن الجنابة ناويًا الحدثين- الحدث الأصغر والأكبر- أجزأه ذلك؛ لأن الأصغر يدخل في الأكبر، لكن السنة والأفضل والكمال أن يفعل ما فعله النبي ﷺ فيتوضأ أولًا، يستنجي يغسل ذكره وما حوله، ثم يتوضأ وضوء الصلاة، ثم يفيض الماء على جسده، يفيض الماء على رأسه ثم على شقه الأيمن ثم الأيسر ويكمل بقية الجسد، هذا هو المشروع وهذا هو الكمال، يبدأ صاحب الجنابة بالاستنجاء وغسل مذاكيره وما حولها ثم يتوضأ وضوء الصلاة اقتداءً برسول الله ﷺ، ثم بعد ذلك يفيض الماء على بشره، هذا هو الأفضل وهذا هو الكمال، فإن نواهما جميعًا واغتسل غسلًا كاملًا، ولم يبدأ بالوضوء أجزأه ذلك، ولكن السنة مثلما تقدم؛ أن يبدأ بالاستنجاء ثم الوضوء ثم يكمل الغسل. نعم.\nالمقدم: يعني مدار هذا على النية، إذا نوى كفاه؟\nالشيخ: نعم، ولكن السنة أن يبدأ بالوضوء بعد الاستنجاء ثم يكمل كفعل النبي ﷺ، نعم، ولا يعيد الوضوء بعد الغسل لا يعيد الوضوء. نعم.\nالمقدم: نعم، جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7978/حكم-الغسل-بنية-الطهارة-من-الحدث-الاكبر-والاصغر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_197/19710.mp3","categories":["الغسل"]},{"id":10064,"question":"المستمعة (س) من الرياض بعثت تسأل وتقول: هل تغتسل المرأة من الاستحاضة التي بعد الحيض وإذا كان يجب الغسل فما الحكم فيمن كانت جاهلة بهذا؟","title":"حكم الغسل على المستحاضة","answer":"الجواب: الاغتسال من الاستحاضة مستحب وليس بواجب، الغسل الواجب من الحيض إذا انتهت مدته ورأت الطهارة تغتسل وجوباً كالجنب، أما الاستحاضة الدماء التي تأتيها بعد الحيض المستمر النزيف المستمر فهذا يستحب منه الغسل، لصلاتي الظهر والعصر والمغرب والعشاء غسلاً واحداً والفجر غسلاً واحداً، وإن تركت فلا حرج عليها لأن النبي ﷺ أوصى بهذا حمنة بنت جحش .\nأما الواجب فلا يجب عليها إلا غسل الحيض وغسل الجنابة أما الاستحاضة فيها الوضوء، على المرأة أن تتوضأ لكل صلاة، كما قال النبي ﷺ لـفاطمة بنت أبي حبيش وكانت مستحاضة: توضئي لوقت كل صلاة، لكن من اغتسل إذا اغتسلت فهو أفضل فالأفضل أن يكون للظهر والعصر غسلاً واحداً، أن تغتسل لوقت الظهر و العصر غسلاً واحداً، وأن تغتسل للمغرب والعشاء غسلاً واحداً وللفجر غسلاً واحداً هذا أفضل لأن الرسول ﷺ أوصى به حمنة رضي الله عنها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8233/حكم-الغسل-على-المستحاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30315.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":10550,"question":"سماحة الشيخ! إنني أتوضأ وضوءاً كاملاً قبل أن أغتسل، ثم بعد ذلك أفيض الماء على جسمي جميعاً وأخرج من الحمام وأذهب للصلاة ولا أتوضأ مرة ثانية بعد الغسل، بل أكتفي بالوضوء السابق قبل الغسل، فهل عملي هذا صواب أم خطأ؛ لأنني سمعت أن الرسول ﷺ كان يتوضأ قبل الغسل ويكتفي بذلك أفيدونا جزاكم الله خيراً؟","title":"حكم الوضوء قبل الغسل والاكتفاء به","answer":"الجواب: الذي فعلت هو السنة وقد وفقت للسنة، هذه هي السنة الوضوء ثم الغسل، وهكذا كان النبي يفعل ﷺ، يتوضأ ثم يغتسل عليه الصلاة والسلام، فأنت بهذا وافقت السنة والحمد لله، إلا إذا حدث منك شيء ينقض الوضوء حال الغسل بأن لمست فرجك أو خرج منك ريح، فهذا يوجب عليك إعادة الوضوء، أما ما دمت لم تمس فرجك ولم يخرج منك شيء ينقض الوضوء فإن عملك طيب وهو الموافق للسنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8727/حكم-الوضوء-قبل-الغسل-والاكتفاء-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_321/32107.mp3","categories":["الغسل"]},{"id":10579,"question":"هل يفتقر من اغتسل للوضوء إذا أراد الدخول في الصلاة، أم يكفي الاغتسال عن الوضوء؟","title":"حكم الوضوء عند الغسل من الجنابة","answer":"الجواب: الوضوء مع الغسل أفضل، كونه يتوضأ إذا كان عليه غسل الجنابة، أو غسل الحيض على المرأة توضأ وضوء الصلاة، تستنجي ويستنجي الرجل ثم يتوضأ وضوء الصلاة، ثم يفرغ على رأسه ثلاث مرات ويخلل رأسه بأصابعه، ثم يفيض الماء على جسده على شقه الأيمن ثم الأيسر، هذه السنة في الجنابة وفي غسل الحيض وفي غسل الجمعة، يبدأ بالوضوء، يعني: بعدما يستنجي من بوله ونحوه، يتوضأ وضوء الصلاة ثم يكمل غسله بادئاً بالرأس يفرغ عليه ثلاث مرات، ثم يغسل شقه الأيمن ثم الأيسر ثم يكمل، هذا هو المشروع، وكان النبي يفعله ﷺ في غسل الجنابة.\nلكن لو نوى الغسل والوضوء، نواهما جميعاً، نوى الجنابة والحدث الأصغر جميعاً، وأفاض الماء على جسده مرة واحدة وعمم بالماء أجزأه ذلك، لكن كونه يفعل ما فعله النبي ﷺ، فيتوضأ ثم يغتسل يكون هذا هو الأكمل والأفضل. هو لابد من الاستنجاء إذا كان أراد أن يغتسل غسلاً واحداً للوضوء لابد من الاستنجاء يستنجي عما خرج من بول أو غائط أو مني يستنجي ثم يفيض الماء على بدنه، ويعم بدنه بالماء ويكفيه بنية الجنابة والوضوء جميعاً ينويهما جميعاً، أما إذا كان ما نوى إلا الجنابة فإنها ترتفع الجنابة، ويبقى عليه الوضوء يتوضأ وضوءاً خاص عن الحدث الأصغر، والكمال أن يتوضأ أولاً بعد الاستنجاء ثم يغتسل هذا هو الكمال. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8757/حكم-الوضوء-عند-الغسل-من-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_324/32405.mp3","categories":["الغسل"]},{"id":11459,"question":"رسالة بتوقيع أحد الإخوة المستمعين يقول الغزالي أخونا يقول: إنني أعمل في مزرعة، وإذا ما صادف أن اغتسلت في بركة المكينة، أو اغتسلت في الدش، هل يجزئ ذلكم عن الوضوء؟ وجهوني جزاكم الله خيرًا.","title":"إجزاء الغسل عن الوضوء","answer":"الجواب:  إذا رتبت، لما انغمست في الماء رتبت أخرجت وجهك ناويًا بذلك الوضوء، ثم أخرجت ذراعك الأيمن، ثم الأيسر ناوياً الوضوء، ثم أخرجت رأسك ناويًا الوضوء، ثم أخرجت رجليك ناويًا الوضوء؛ فأنت على نيتك بالترتيب، وإلا فإنه لا يجزئك، إلا إذا كان عن جنابة -غسل الجنابة- أو نويت الحدثين، نويت غسل الجنابة، ونويت الوضوء، فيكون بهذا الغسل أجزأ على الصحيح، دخل الأصغر في الأكبر، نعم. المقدم: طيب، لكن أما إذا كان للتبرد أو للنظافة؟ الشيخ: لابد يرتب. المقدم: لابد من الترتيب؟ الشيخ: رأسه أولًا بنية الوضوء، ثم يديه بنية الوضوء، ثم رأسه بنية الوضوء، ثم رجليه بنية الوضوء. المقدم: بارك الله فيكم، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9640/اجزاء-الغسل-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38114.mp3","categories":["الغسل"]},{"id":11615,"question":"هل الاستحمام يجزئ عن الوضوء للصلاة؟","title":"حكم الاكتفاء بالاستحمام عن الوضوء","answer":"الجواب:  إذا كان الاستحمام عن جنابة، وأراد الحدثين الأصغر والأكبر، المغتسل أراد بغسله الوضوء والغسل جميعًا وهو جنب؛ أجزأ، أما الاستحمام عن غير الجنابة لا، لابد من الوضوء قبله، أو بعده، لابد أن يتوضأ. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9802/حكم-الاكتفاء-بالاستحمام-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38813.mp3","categories":["الغسل","فروض الوضوء وصفته"]},{"id":11629,"question":"هل الاستحمام يجزئ عن الوضوء للصلاة؟","title":"حكم الاكتفاء بالاستحمام عن الوضوء","answer":"الجواب:  إذا كان الاستحمام عن جنابة، وأراد الحدثين الأصغر والأكبر، المغتسل أراد بغسله الوضوء والغسل جميعًا وهو جنب؛ أجزأ، أما الاستحمام عن غير الجنابة لا، لابد من الوضوء قبله، أو بعده، لابد أن يتوضأ. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9802/حكم-الاكتفاء-بالاستحمام-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38813.mp3","categories":["الغسل","فروض الوضوء وصفته"]},{"id":11853,"question":"مستمع رمز إلى اسمه بالحروف (ع) و (ح) و (هـ) يقول: هل يجزئ الاغتسال عن الوضوء؟ حيث أنه يقوم بإفراغ الماء على بدنه كله.","title":"مسألة إجزاء الغسل عن الوضوء","answer":"الجواب:  لا يجزئ الغسل، لابد من الوضوء، يبدأ يتمضمض، ويستنشق، ويغسل وجهه، ثم يديه، ثم يمسح رأسه وأذنيه، ثم رجليه، يغسل رجليه، أما كونه يصب الماء على بدنه ما يجزئ، إلا إذا كان عن جنابة ونواهما جميعًا، إذا كان الغسل جنابة، ونوى الحدثين؛ صار الأصغر تبع الأكبر، مع أن الأولى والأفضل حتى في الجنابة، يتوضأ، ثم يغتسل، كفعل النبي ﷺ كان يتوضأ، ثم يغتسل -عليه الصلاة والسلام- فهذا هو المشروع، ولو في الجنابة، لكن لو نواهما جميعًا في الجنابة؛ أجزأ عند جمع من أهل العلم، وصار الأصغر تبعًا للأكبر، لكن بكل حال الأولى له والأفضل له أن يتوضأ أولًا، ثم يعمم بدنه بالغسل في الجنابة. أما الغسل المستحب غسل الجمعة، أو غسل التبرد لا، الغسل مستقل، والوضوء مستقل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10037/مسالة-اجزاء-الغسل-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39617.mp3","categories":["الغسل"]},{"id":12819,"question":"يقول: أقوم لصلاة الفجر وأغتسل من الجنابة إذا كانت، فهل يجزئ الغسل عن الوضوء والذهاب للصلاة؟","title":"غسل وإجزاؤه الجنابة عن الوضوء","answer":"الجواب:  المشروع لك أن تتوضأ وضوء الصلاة، ثم تغتسل، تستنجي ثم تتوضأ وضوء الصلاة، ثم تغتسل، هكذا كان النبي يفعل -عليه الصلاة والسلام- لكن لو نويت بالغسل هذا وهذا الحدثين، نويت الحدث الأصغر والأكبر وأنه يقوم مقام الوضوء أجزأ على الراجح.  ولكن الأفضل لك أن تتوضأ أولًا وضوء الصلاة، تستنجي، ثم تتوضأ وضوء الصلاة، ثم تكمل الغسل، هذا هو الذي كان يفعله النبي -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/11033/غسل-واجزاوه-الجنابة-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46307.mp3","categories":["الغسل"]},{"id":12838,"question":"يسأل سؤالًا آخر يقول فيه: هل الغسل من الاحتلام يشابه الغسل من الجنابة؟","title":"استواء الغسل من الاحتلام والغسل من الجنابة","answer":"الجواب:  نعم، سواء، إذا رأى الماء، إذا رأى المحتلم الماء المني؛ وجب عليه الغسل، المرأة والرجل في هذا سواء، لما في الصحيحين عن أم سلمة -رضي الله عنها- وعن أنس أن أم سليم سألت النبي ﷺ فقالت: يا رسول الله! إن الله لا يستحي من الحق، هل على المرأة من غسل إذا هي احتلمت؟ فقال ﷺ: نعم إذا هي رأت الماء يعني: المني. وأجمع العلماء على أنها إذا لم تر الماء، أو الرجل لم ير الماء يعني: المني، فلا غسل عليه، إنما الغسل من الماء: الماء من الماء إلا في الجماع في اليقظة، إذا جامع ولو ما رأى الماء؛ يغتسل، إذا جامع زوجته يعني: أولج فرجه في فرجها؛ فإنه يغتسل، وهي تغتسل ولو ما حصل إنزال، ولو ما حصل مني؛ لقوله ﷺ: إذا مس الختان الختان؛ فقد وجب الغسل وقوله ﷺ: إذا جلس بين شعبها الأربع، ثم جهدها؛ فقد وجب الغسل، وإنْ لم ينزل نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11052/استواء-الغسل-من-الاحتلام-والغسل-من-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46404.mp3","categories":["الغسل"]},{"id":13753,"question":"يقول في غسل الجنابة إذا استحم الشخص بالماء أولًا، ثم بالصابون في نفس المكان، هل في ذلك شيء؟ وهل لابد من الوضوء؟الشيخ: أعد.المقدم: يقول: في غسل الجنابة إذا استحم الإنسان بالماء أولًا، ثم بالصابون في نفس المكان، هل في ذلك شيء؟ وهل لابد من الوضوء؟","title":"حكم الوضوء لمن استعمل الصابون في غسل الجنابة","answer":"الجواب: ليس في ذلك شيء إذا اغتسل من الجنابة بالصابون، أو بالسدر، أو بالإشنان، أو بغيره؛ فلا بأس، لكن كونه يتوضأ وضوء الصلاة أولًا، ثم يغتسل غسل الجنابة؛ يكون أكمل، كفعل النبي -عليه الصلاة والسلام- لكن لو غسل للجنابة فقط ولم... الوضوء، ولم يفعل الوضوء؛ فلا حرج، يطهر من.. الجنابة، وإذا أراد الصلاة يتوضأ وضوء الصلاة. أما إذا جمع بينهما فهذا هو الأكمل، يتوضأ وضوء الصلاة، ثم يغتسل في جميع بدنه بالصابون، أو بغيره، ولكن لا يمس العورة، فإن مسها؛ يعيد الوضوء، نعم، إن مس عورته -يعني: الفرج- الذكر، أو الدبر، إذا مسه؛ يعيد الوضوء الشرعي، يغسل وجهه ويديه، ويمسح رأسه، وأذنيه، ويغسل رجليه، هذا الوضوء الشرعي.  أما إذا كان لا، يعني: عمم الماء على بدنه، ولكن ما مس فرجه حين الغسل؛ فوضوؤه الأول صحيح. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12117/حكم-الوضوء-لمن-استعمل-الصابون-في-غسل-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54602.mp3","categories":["الغسل"]},{"id":13824,"question":"يقول هذا السائل في سؤاله سماحة الشيخ: إذا اجتمع على الإنسان مثلًا غسل الجمعة وغسل الجنابة، فهل يغتسل غسلًا واحدًا أو غسلين؟ وكيف ينوي النية في هذه الحالة؟","title":"هل يكفي غسل للجنابة والجمعة؟","answer":"الجواب: يكفيه غسل واحد بنية الجنابة ويكفي؛ لأن المقصود: النظافة والنشاط، وقد حصل في غسل الجنابة، فإن نواهما جميعًا فهو طيب لا بأس، إن نواهما غسل الجنابة وغسل الجمعة كله طيب، وإن نوى غسل الجنابة فقط كفى. نعم.","link":"https://binbaz.org.sa/fatwas/12191/هل-يكفي-غسل-للجنابة-والجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53706.mp3","categories":["الغسل"]},{"id":13847,"question":"السائل (ع. أ) يقول: رجل اغتسل للجمعة ثم راح إلى المسجد للصلاة ثم بعدما صلى وقبل أن يخرج من المسجد أو بعد خروجه من المسجد ذكر بأنه لم يتوضأ، فما هو الجواب في هذه المسألة؟ جزاكم الله خيرًا.","title":"ما يلزم من اغتسل وصلى الجمعة ولم يتوضأ؟","answer":"الجواب: الذي اغتسل للجمعة ولم يتوضأ ثم ذكر بعد الصلاة عليه أن يعيد صلاة الجمعة ظهرًا، يتوضأ ويصلي ظهرًا؛ لأنه صلاته غير صحيحة صلى بغير وضوء، والغسل لا يقوم مقام الوضوء غسل الجمعة ما يكفي حتى يتوضأ قبله أو بعده، فإذا صلى ولم يتوضأ فإنه يعيدها ظهرًا. نعم يتوضأ ويعيدها ظهرًا.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12217/ما-يلزم-من-اغتسل-وصلى-الجمعة-ولم-يتوضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53717.mp3","categories":["الغسل"]},{"id":13974,"question":"يسأل أخونا ويقول: هل للإنسان أن يتوضأ داخل الحمام أثناء الاستحمام قبل أن يرتدي ملابسه؟","title":"حكم الوضوء عريانًا بعد الاستحمام","answer":"الجواب: لا نعلم بأساً في ذلك، إذا اغتسل من الجنابة أو يوم الجمعة، لا نعلم.. لكن السنة والأفضل أن يبتدي بالوضوء في غسل الجنابة، يتوضأ، ثم يغتسل للجنابة ويكفيه الوضوء الأول، كان النبي يتوضأ أولاً عليه الصلاة والسلام، يعني: يستنجي ويغسل ما أصاب فرجه وما حوله، ثم يتوضأ وضوء الصلاة ثم يغتسل، حتى إذا انتهى من الغسل انتهى من كل شيء، ليس عليه وضوء بعد ذلك، إلا إن أحدث بأن مس فرجه، أو خرج منه ريح؛ فإنه يعيد الوضوء، أما إذا كان اغتسل ولم يمس فرجه ولم يحدث؛ فإن وضوءه الأول كافي.\nأما غسل الجمعة، فإنه إن شاء توضأ قبله وإن شاء توضأ بعده، لا يكفي وحده الغسل، لا بد من وضوء إما قبله وإما بعده، وإذا توضأ قبله وبعده وهو عريان، فلا حرج في ذلك؛ لأنه تجرد ليغتسل، فإذا توضأ قبل الغسل أو بعد الغسل وهو لم يلبس الثياب في غسل الجنابة أو في غسل الجمعة أو نحوه؛ فلا بأس إن شاء الله نعم، ولا حرج، ولا حرج إن شاء الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12408/حكم-الوضوء-عريانا-بعد-الاستحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60604.mp3","categories":["الغسل"]},{"id":14528,"question":"المستمع: سعد محمد عباس من العراق، الأنبار، الكرماء، بعث برسالة يقول فيها: من المعروف أنّ الوضوء يشترط على أمور معينة مثل غسل الوجه والمضمضة والاستنشاق وغير ذلك. وسؤالي: هل يجوز لي بعد الخروج من الحمام، وبعد الاغتسال مباشرة في الصلاة، دون أداء شروط الوضوء المذكورة؟أجيبوني، جزاكم الله خيرًا.","title":"حكم الاكتفاء بالغسل عن الوضوء","answer":"الجواب: الوضوء طهارة مستقلة، والغسل طهارة مستقلة عن الجنابة، وعن الحيض في حق المرأة والنفاس، فإذا اغتسل المؤمن عن الجنابة بنية الطهارتين الكبرى والصغرى أجزأه ذلك، ودخلت الصغرى في الكبرى، وإذا اغتسل بنية الجنابة فقط فالأرجح: أنه لا يدخل، فعليه أن يتوضأ، وإذا توضأ قبل غسله يكون أفضل؛ لأن الرسول -عليه الصلاة والسلام- كان يتوضأ قبل الغسل، كان إذا أتى أهله يستنجئ ويتوضأ وضوء الصلاة، ثم يغتسل، هذا هو السنة، يستنجي يغسل ذكره وما حوله ويتوضأ وضوء الصلاة، ثم يغتسل، فإذا اغتسل من غير ترتيب ونوى الطهارتين الصغرى والكبرى أجزأه ذلك على الصحيح، نعم. المقدم: جزاكم الله خيرًا، إذن الأمر مهم بالنسبة للنية في هذه الحالة؟\nالشيخ: نعم، نعم.\nأما إن كان الغسل مستحبًا، فإن هذا لا يدخل فيه الوضوء، لا بد من الوضوء، أو كان للتبرد،نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13024/حكم-الاكتفاء-بالغسل-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63406.mp3","categories":["الغسل"]},{"id":14651,"question":"تقول في سؤالها الثاني: ما هي فروض الغسل من الحيض والجنابة؟","title":"فروض الغسل من الحيض والجنابة","answer":"الجواب: الفرض تعميم الجسم من الجنابة والحيض والنفاس، يعمه بالماء، إذا عم الجسم بالماء بنية الطهارة كفى عن المرأة والرجل، عليه جنابة والمرأة من الحيض والنفاس إذا عمت جسمها بالماء، واغتسلت بنية الطهارة، كفى، لكن الأفضل أن يبدأ بالوضوء إذا كان جنبًا أو يبدأ بالضوء، الوضوء الشرعي، ثم يعم بدنه بالماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13137/فروض-الغسل-من-الحيض-والجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55917.mp3","categories":["صلاة الجمعة","الغسل","قضايا المرأة"]},{"id":14759,"question":"السؤال الثاني للأخ دخيل الله يقول: إذا اغتسل الإنسان من أي حدث أثناء دخول وقت الصلاة هل يجزئ ذلك عن الوضوء للصلاة، أم أنكم توجهونه بشيء آخر؟","title":"هل يجزء غسل الجنابة عن الوضوء؟","answer":"الجواب: السنة لمن أصابه حدث الجنابة أن يبدأ بالوضوء، يستنجي أولًا، ثم يتوضأ وضوء الصلاة، ثم يكمل غسله، يفيض على رأسه ثلاث مرات، ثم على جنبه الأيمن، ثم الأيسر، ويكمل غسله، هذا هو السنة، لكن لو أنه غسل بنية الحدثين الجنابة والحدث الأصغر كفاه ذلك؛ لقوله ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى ويدخل الأصغر في الأكبر، لكن السنة والأفضل أن يبدأ بالوضوء بعد الاستنجاء، ثم يكمل غسله، نعم.\nالمقدم: جزاكم الله خيرًا، إنما تشترطون النية سماحة الشيخ إذا نوى رفع الحدث الأصغر والأكبر؟\nالشيخ: نية الأمرين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13254/هل-يجزء-غسل-الجنابة-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63802.mp3","categories":["الغسل"]},{"id":14958,"question":"من بلاد بني الحارث من قرية الشباشبة، وصلتنا هذه الرسالة من المرسل (ن. ع. ح) يقول فيها: أفيد فضيلتكم بأنني قد أصبت بمرض، وأجري لي عملية بالمستشفى، وعند طلوعي من المستشفى، أفادني الدكتور المختص بأنه يجب علي عدم الغسل بالماء لمدة خمسة شهور، بما فيها شهر رمضان المبارك القادم. أرجو إفادتي؛ هل أبقى على ما قال الدكتور -خمسة شهور-، أم أغتسل وأصلي وأصوم رمضان، وما الحكم في الفروض التي تركتها؟","title":"حكم من قرر الطبيب أن يترك الغسل عدة شهور","answer":"الجواب: الظاهر أنه لك عذر في ذلك في عدم الغسل، تيمم عن الجنابة، لكن من باب الاحتياط ينبغي سؤال غيره من الأطباء الذين هم متخصصين بهذا المرض، من باب التأكد وسؤال طبيب ثان ، ولا سيما الأطباء المسلمون الذين يوثق بهم، إذا أخذت الحيطة بسؤال ثاني أو ثالث هذا طيب.  أما إذا كان هذا الذي أخبرك هو الطبيب المختص، وهو الذي تولى العلاج، وأنت مطمئن إلى خبره، لا يظهر لك منه ما يدل على تساهله بالإسلام، أو كراهته لحكم الإسلام، فالحمد لله، هذا من أمور الطب، ومما يخشى منه الخطر لو خالفته، فلا بأس أن تأخذ بقوله، ولا تغتسل حتى تمضي المدة احتياطًا لصحتك وسلامتك.  ولكن من باب الاحتياط، ومن باب التوثق ينبغي أن تسأل طبيبًا آخر أو طبيبين إذا تيسر ذلك من باب الحيطة.","link":"https://binbaz.org.sa/fatwas/13455/حكم-من-قرر-الطبيب-ان-يترك-الغسل-عدة-شهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_648/nour_64806.mp3","categories":["الغسل"]},{"id":15020,"question":"هذه أختكم في الله (أ. أ. ع) جدة، تقول: في الحديث عن أم سلمة -رضي الله عنها- قالت: «قلت: يا رسول الله، إني امرأة أشد شعر رأسي، أفأنقضه لغسل الجنابة -وفي رواية: والحيضة- فقال: لا، إنما يكفيك أن تحثي على رأسك ثلاث حثيات رواه مسلم.هل هذا يعني: أن غسل مقدمة الرأس ثلاث حثيات دون غسل باقي الشعر من الخلف يا سماحة الشيخ؟","title":"معنى حديث: \"إنما يكفيك أن تحثي...\"","answer":"الجواب: المعنى: أنها لا تنقض، ما يلزمها النقض، أن تحثي على رأسها ثلاث حثيات، وتسيل الماء على الجدائل، تعمها بالماء الجدائل، ولا يلزمها النقض، إذا عمته بثلاث حثيات، فإن الغالب أن هذا الماء يصل إلى الجوف -جوف الشعر- ثم تفيض الماء على بقية جسدها؛ فتطهر بإذن الله -والحمد لله-. ولكن النقض في الحيض، كما جاء في رواية أخرى: «أنه أمر بعض الحيض أن ينقضن شعرهن» نقضه أولى في الحيض وأكمل، وإن لم تنقض فلا بأس، كما في حديث أم سلمة.  أما في الجنابة فلا حاجة إلى النقض، تفيض الماء على رأسها وعلى بدنها، والحمد لله، الرجل والمرأة، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13518/معنى-حديث-انما-يكفيك-ان-تحثي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56305.mp3","categories":["الحيض والنفاس","الغسل"]},{"id":15052,"question":"عن الاحتلام وردتنا هذه الرسالة من جدة، من باعثها (ع. ع. ب) يقول فيها: إذا الرجل احتلم، فخرج منه شيء، فهل يغتسل، ويلبس لبسًا جديدًا، أم يعيد هذا اللباس عليه؟","title":"حكم الاغتسال على من احتلم","answer":"الجواب: إذا احتلم الرجل، أو المرأة؛ فإنهما يغتسلان، إذا رأيا الماء، وهو المني، أما احتلام بدون ماء ليس فيه غسل؛ لأن النبي ﷺ لما سألته أم سليم، قالت: يا رسول الله، إن الله لا يستحي من الحق، فهل على المرأة من غسل إذا هي احتلمت؟ أجابها -عليه الصلاة والسلام- بقوله: نعم؛ إذا هي رأت الماء يعني: المني، فإذا رأى الرجل أو المرأة المني بعد الاحتلام، أو رأى المني، وإن لم يكن احتلامًا؛ فإنه يغتسل، والمني معروف، ماء غليظ، ينتج عن الشهوة، فإذا رأى الرجل، أو المرأة ماء -وهو المني- بعد احتلامهما، أو استيقظا ورأياه وإن لم يذكرا احتلام؛ فإنهما يغتسلان، كما أمر بهذا النبي -عليه الصلاة والسلام-. أما احتلام ليس معه مني؛ فإنه لا يوجب الغسل، سواء كان في الليل أو في النهار، ولا يؤثر على الصائم، ولا على الحاج الاحتلام؛ لأنه ليس باختياره، فلو احتلم في نهار الصيام، أو احتلم في عرفة، أو في منى قبل أن يرمي الجمرة؛ فإنه لا يضره ذلك؛ لأنه ليس باختياره، والله سبحانه لا يكلف نفسًا إلا وسعها، ، نعم.","link":"https://binbaz.org.sa/fatwas/13576/حكم-الاغتسال-على-من-احتلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65409.mp3","categories":["الغسل"]},{"id":15091,"question":"المستمع (م. س. أ) من مصر، بعث برسالة ضمنها جمعًا من الأسئلة، في أحدها يقول: ما حكم من اغتسل من الجنابة دون أن يتوضأ في أول الغسل؟ وهل لمن يتوضأ في أول الغسل عليه أن يغسل رجليه أم لا؟","title":"حكم الاكتفاء بغسل الجنابة عن الوضوء","answer":"الجواب: إذا اغتسل من الجنابة ناويًا الحدثين الأكبر والأصغر أجزأ عنهما، أما إذا ما نوى إلا الأكبر فقط، فالذي ينبغي أن يتوضأ، وقد ذهب بعض أهل العلم إلى إجزائه عن الوضوء؛ لأن الأصغر يدخل في الأكبر، ولكن ظاهر الأحاديث خلاف ذلك؛ لقوله ﷺ: إنما الأعمال بالنيات وهو لم ينو إلا الأكبر. فالواجب عليه أن يتوضأ بعد ذلك الوضوء الشرعي. والسنة أن يبدأ بالوضوء، هذا هو السنة، يبدأ بالوضوء، ثم يغتسل، هذا هو السنة، وإذا توضأ قبل ذلك، فإن ترك رجليه، ثم كمل الغسل فلا بأس، وإن كمل رجليه فهو أفضل، وقد ثبت عنه ﷺ هذا وهذا، ثبت عنه في حديث عائشة أنه توضأ، وكمل الوضوء، وثبت عنه في حديث ميمونة أنه ترك الرجلين، حتى فرغ، ثم غسلهما مكانًا آخر. فكونه يتوضأ وضوءًا كاملًا، ثم يغتسل، ثم بعد هذا يغسل رجليه مرة أخرى، يكون هذا أفضل، وإن تركهما حتى كمل الغسل، ثم كملهما، فلا حرج في ذلك؛ لأن الغسل صار الآن مشتركًا بين الوضوء والغسل، فإذا توضأ الوضوء الشرعي إلا الرجلين، ثم كمل غسله، ثم كمل رجليه، فلا حرج، لكن مثلما تقدم كونه يكمل الوضوء حتى الرجلين، ثم يكمل الغسل يكون هذا هو الأفضل، ثم بعد ذلك يغسل قدميه، مكانًا آخر، إذا تيسر ذلك، فإن كان المكان واحدًا، وليس فيه شيء يتعلق بالرجلين، بأن كان مبلطًا، غسلهما في المكان، والحمد لله. وكونه غسلهما في المكان الآخر -عليه الصلاة والسلام- محمول على أن انتقاله من المحل الذي قد يكون علق بهما شيء من طينه وترابه، فيغسلهما في مكان آخر لهذه العلة، هذا هو الظاهر، والله أعلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13584/حكم-الاكتفاء-بغسل-الجنابة-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49402.mp3","categories":["الغسل","الطهارة لصحة الصلاة"]},{"id":15150,"question":"سؤاله الأخير يقول: هل الاستحمام يكفي أو يمنع من الوضوء؟أرشدونا في ذلك، جزاكم الله عنا خير الجزاء.","title":"حكم الاكتفاء بالغسل عن الوضوء","answer":"الجواب: السنة أن يتوضأ أولًا وضوء الصلاة كاملًا، أو إلا رجليه، ثم يغتسل للجنابة، ثم يغسل رجليه بعد ذلك إذا كان لم يغسلها، وإن كان قد غسلها، غسلها أيضًا مرة أخرى عملًا بالسنة، هذا إذا كان في الجنابة، وإن نوى الحدثين جميعًا، واغتسل غسلًا كاملًا، ولم يخص الوضوء بأعماله أجزأ عند جمع من أهل العلم، بنيته الحدثين، ولكن الأولى والأفضل والسنة أن يتوضأ وضوء الصلاة، كما فعله النبي ﷺ بعد الاستنجاء، يستنجي يغسل ذكره وما حوله، ويتوضأ وضوء الصلاة، ثم يكمل غسل الجنابة، هذا هو السنة، وهذا هو الأفضل. أما غسل التبرد أو غسل الجمعة؛ فهذا لا يكفي عن الوضوء، لا بد من الوضوء، ثم الغسل، أو الغسل أولًا، ثم الوضوء، نعم.","link":"https://binbaz.org.sa/fatwas/13656/حكم-الاكتفاء-بالغسل-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65808.mp3","categories":["الغسل","الطهارة لصحة الصلاة"]},{"id":15154,"question":"سؤاله الأخير يقول: هل الاستحمام يكفي أو يمنع من الوضوء؟أرشدونا في ذلك، جزاكم الله عنا خير الجزاء.","title":"حكم الاكتفاء بالغسل عن الوضوء","answer":"الجواب: السنة أن يتوضأ أولًا وضوء الصلاة كاملًا، أو إلا رجليه، ثم يغتسل للجنابة، ثم يغسل رجليه بعد ذلك إذا كان لم يغسلها، وإن كان قد غسلها، غسلها أيضًا مرة أخرى عملًا بالسنة، هذا إذا كان في الجنابة، وإن نوى الحدثين جميعًا، واغتسل غسلًا كاملًا، ولم يخص الوضوء بأعماله أجزأ عند جمع من أهل العلم، بنيته الحدثين، ولكن الأولى والأفضل والسنة أن يتوضأ وضوء الصلاة، كما فعله النبي ﷺ بعد الاستنجاء، يستنجي يغسل ذكره وما حوله، ويتوضأ وضوء الصلاة، ثم يكمل غسل الجنابة، هذا هو السنة، وهذا هو الأفضل. أما غسل التبرد أو غسل الجمعة؛ فهذا لا يكفي عن الوضوء، لا بد من الوضوء، ثم الغسل، أو الغسل أولًا، ثم الوضوء، نعم.","link":"https://binbaz.org.sa/fatwas/13656/حكم-الاكتفاء-بالغسل-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65808.mp3","categories":["الغسل","الطهارة لصحة الصلاة"]},{"id":15374,"question":"هذا سائل للبرنامج أرسل بمجموعة من الأسئلة، السائلة (ح. ع) تقول: ما حكم الماء الذي يدخل مع الأذن والعين أثناء الاستحمام والأنف أثناء الاستنشاق؟","title":"حكم الماء الداخل من الأذن والأنف أثناء الاغتسال","answer":"الجواب: ما يضر، لا حرج فيه، ولو كان صائمًا، لا يضر، إذا ما تعمد إدخال الماء مع الأنف، إنما هو وقت الاستنشاق، لا يضر، لكن الصائم لا يبالغ، النبي -عليه الصلاة السلام- قال: وبالغ في الاستنشاق إلا أن تكون صائمًا نعم.","link":"https://binbaz.org.sa/fatwas/13877/حكم-الماء-الداخل-من-الاذن-والانف-اثناء-الاغتسال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56705.mp3","categories":["الغسل"]},{"id":15392,"question":"إذا توفي الإنسان وعليه غسل هل غسل الجنازة يكفي عن ذلك الغسل؟","title":"ما حكم من توفي وعليه غسل واجب؟","answer":"الجواب: نعم، الغاسل إذا كان يعلم ينويهما جميعًا، وإذا كان لا يعلم سده غسل الميت، نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13892/ما-حكم-من-توفي-وعليه-غسل-واجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56717.mp3","categories":["الغسل"]},{"id":15524,"question":"يقول يا سماحة الشيخ: عندما أريد الغسل من جنابة، أو لصلاة جمعة، أو لصلاة عيدين، أبدأ دائمًا بالغسل من السرة إلى الركبة بالصابون، ثم بعد ذلك أنوي الغسل، وأشرع فيه بالماء فقط، فهل عملي هذا صحيح؟","title":"كيفية الغسل للجمعة والجنابة والعيدين","answer":"الجواب: يكفي، لا بأس به، لكن ما في حاجة للصابون، الماء يكفي، وإذا فعلت الصابون فلا بأس، لكن لا بد يغسل بالماء هذا الصابون، تصب عليه الماء حتى يزول، حتى يبلغ الماء البشرة، حتى يزول الصابون، وتعم الفخذين والسرة، وما تحت السرة، والعورة كلها تعمها بالماء عن الجنابة، وهكذا في غسل الجمعة حتى تحصل لك السنة، نعم.","link":"https://binbaz.org.sa/fatwas/14065/كيفية-الغسل-للجمعة-والجنابة-والعيدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69113.mp3","categories":["الغسل"]},{"id":15595,"question":"سؤاله الثاني يقول: إذا كان بالقرب مني نهر أو بحر، وكنت أستحم فيه، وبعد ذلك حان وقت الصلاة، وليس عندي ماء غيره أتوضأ منه، فهل يكفي استحمامي ذلك عن الوضوء وأصلي به أم لا؟","title":"متى يجزئ الغسل عن الوضوء؟","answer":"الجواب: عليك أن توضأ مما حولك من النهر والبحر، سئل النبي ﷺ عن الوضوء من البحر؟ فقال: هو الطهور ماؤه، الحل ميتته الحمد لله، إذا تحممت للتبرد، أو لإزالة الوسخ، أو ما أشبه ذلك، فلا يكفي، لا بد من الوضوء. أما إذا كان عن جنابة ونويت الحدثين: الأصغر والأكبر في الغسل كفى، لكن الأفضل أنك تتوضأ وضوء الصلاة، ثم تغتسل غسل الجنابة بعد ذلك، هكذا كان النبي يفعل، كان النبي -عليه الصلاة والسلام- يبدأ بالوضوء، يستنجي أولًا، ثم يتوضأ وضوء الصلاة، ثم يتحمم ثم يغتسل، هذا هو السنة، ويكفي ذلك لكن لو نواهما جميعًا، ولم يبدأ بالوضوء، من نوى الغسل والوضوء جميعًا بنية واحدة أجزأه عند جمع من أهل العلم، ولكن الأفضل أنه يفعل ما فعله النبي ﷺ يعني: يتوضأ أولًا، يستنجي ويتوضأ وضوء الصلاة، ثم يسبغ الماء على بدنه، يعني: يكمل تروشه هذا هو السنة عن الجنابة. وهكذا المرأة عن الحيض، إذا طهرت من حيضها تستنجي وتتوضأ وضوء الصلاة، ثم تغتسل، تعم البدن بالماء وهذا هو الأمر الشرعي فيجزئها هذا عن وضوئها، وعن غسلها جميعًا. والماء سواء كان من ماء البحر، أو من ماء النهر، أو من ماء الآبار، الحمد لله الأمر واسع، الله قال: فَلَمْ تَجِدُوا مَاءً[المائدة:6] والماء يعم البحر والنهر والعيون والآبار كله داخل في الماء.","link":"https://binbaz.org.sa/fatwas/14137/متى-يجزى-الغسل-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_694/nour_69402.mp3","categories":["الغسل"]},{"id":16242,"question":"يسأل ويقول: هل الاغتسال غير الغسل من الجنابة يجزئ عن الوضوء؟","title":"هل يجزئ الغسل المباح عن الوضوء؟","answer":"الجواب: لا يجزئ عن الوضوء، لا بد من الوضوء المرتب، أما في الجنابة إذا اغتسل للجنابة، ونواهما؛ فإنه يجزي عند جمع من أهل العلم، والأفضل أن يتوضأ حتى في الجنابة، يتوضأ، ثم يكمل غسله، هذا هو الأفضل. كان النبي ﷺ في غسله من الجنابة يتوضأ، أولًا يستنجي، ثم يتوضأ وضوء الصلاة، ثم يفرغ الماء على رأسه ثلاثًا، ثم على بدنه، هذا هو السنة، وهذا هو الأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14942/هل-يجزى-الغسل-المباح-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80711.mp3","categories":["فروض الوضوء وصفته","الغسل"]},{"id":16343,"question":"أيضًا من المدينة المنورة رسالة بتوقيع إحدى الأخوات تقول المرسلة: (م. أ) أختنا تسأل سماحتكم عن حكم غسل الجمعة للنساء اللائي لا يذهبن إلى المساجد، بل يصلين في بيوتهن، وإذا كان واجب عليهن فمتى يكون؟ هل هو قبل الظهر؟ جزاكم الله خيرًا.","title":"ما حكم غُسل الجمعة على النساء؟","answer":"الجواب: ليس على النساء غسل الجمعة، الغسل على من راح إلى الجمعة، كما قال النبي ﷺ: من راح إلى الجمعة؛ فليغتسل أما هن فالسنة لهن الصلاة في البيوت، وليس عليهن غسل، وإنما هو على الرجال، نعم.","link":"https://binbaz.org.sa/fatwas/15037/ما-حكم-غسل-الجمعة-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71406.mp3","categories":["صلاة الجمعة","الغسل"]},{"id":16691,"question":"يقول في سؤال آخر: يقول بعض الناس: إنه يجب عند الاغتسال أن يكون المرء مستقبلًا القبلة، فهل ما قيل صحيح؟","title":"حكم استقبال القبلة عند الغسل","answer":"الجواب: ليس بصحيح، يغتسل، سواء كان مستقبلًا القبلة، أو غير مستقبل القبلة، الأمر في هذا واسع -والحمد لله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15471/حكم-استقبال-القبلة-عند-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_820/nour_82014.mp3","categories":["الغسل"]},{"id":16837,"question":"ما حكم من يجلس، أو يظل على الجنابة فترة من الزمن بعذر، أو بدون عذر؟","title":"ما حكم تأخير غسل الجنابة؟","answer":"الجواب: لا حرج ما دام لم يحضر وقت الصلاة، فإذا حضر وقت الصلاة؛ لزمه الغسل، وأداء الصلاة، كالظهر، أو العصر، أما في الضحى مثلًا تأخر حتى لم يغتسل إلا عند الظهر، قد ثبت في الصحيحين من حديث حذيفة، ومن حديث أبي هريرة أنهما لقيا النبي ﷺ ثم انخنسا منه، فقال لهما النبي ﷺ: ما شأنكم؟ قالا: كنا على جنابة، فكرهنا أن نجالسك، ونحن على غير طهارة، فقال النبي ﷺ: إن المسلم لا ينجس ولم ينكر عليهم بقاؤهم على غير طهارة، اللهم صل عليه. المقدم: لكن الذي تنصحون به الناس سماحة الشيخ؟ الشيخ: إذا بادر بالغسل طيب، إذا بادر حسن، ولكن لا يلزمه، قد يعوق عائق، يخرج السوق لحاجة يشتريها، أو كذا، لا حرج عليه، إنما يلزمه إذا حضر ما يوجب ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15618/ما-حكم-تاخير-غسل-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82414.mp3","categories":["الغسل"]},{"id":16853,"question":"ما حكم من يجلس، أو يظل على الجنابة فترة من الزمن بعذر، أو بدون عذر؟","title":"ما حكم تأخير غسل الجنابة؟","answer":"الجواب: لا حرج ما دام لم يحضر وقت الصلاة، فإذا حضر وقت الصلاة؛ لزمه الغسل، وأداء الصلاة، كالظهر، أو العصر، أما في الضحى مثلًا تأخر حتى لم يغتسل إلا عند الظهر، قد ثبت في الصحيحين من حديث حذيفة، ومن حديث أبي هريرة أنهما لقيا النبي ﷺ ثم انخنسا منه، فقال لهما النبي ﷺ: ما شأنكم؟ قالا: كنا على جنابة، فكرهنا أن نجالسك، ونحن على غير طهارة، فقال النبي ﷺ: إن المسلم لا ينجس ولم ينكر عليهم بقاؤهم على غير طهارة، اللهم صل عليه. المقدم: لكن الذي تنصحون به الناس سماحة الشيخ؟ الشيخ: إذا بادر بالغسل طيب، إذا بادر حسن، ولكن لا يلزمه، قد يعوق عائق، يخرج السوق لحاجة يشتريها، أو كذا، لا حرج عليه، إنما يلزمه إذا حضر ما يوجب ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15618/ما-حكم-تاخير-غسل-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82414.mp3","categories":["الغسل"]},{"id":17387,"question":"تقول: عندما تريد المرأة أن تغتسل للطهارة هل يلزمها الوضوء أولًا؟","title":"ما حكم الوضوء قبل الغسل؟","answer":"الجواب: السنة الوضوء، إذا كان عن حيض، أو جنابة الوضوء أولًا، تستنتجي إن كان في غسل الحيض، والجنابة، تستنجي، ثم تتوضأ وضوء الصلاة، تمضمض، وتستنشق، وتغسل وجهها، وذراعيها مع المرفقين، ثم تمسح وجهها، وأذنيها، ثم تغسل رجليها، هذا هو الأفضل، كان النبي يفعله في غسل الجنابة -عليه الصلاة والسلام- وربما ترك القدمين إلى آخر الغسل، ربما غسل وجهه، ويديه، ومسح رأسه، وأخر رجليه، هذا جائز وهذا جائز. والمرأة الحائض كذلك، فإن بدأت بالغسل، أو بدأ الجنب بالغسل، ثم تتوضأ بعد ذلك فلا بأس، لكن الأفضل أن يكون الوضوء هو الأول، يستنجي، وهكذا المرأة الحائض، والجنب تستنجي، ثم وضوء الصلاة، ثم الغسل يحثي على رأسه ثلاثًا، وهي كذلك، ثم يفيض على جنبه الأيمن، ثم الأيسر، والمرأة كذلك، هذا هو السنة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16266/ما-حكم-الوضوء-قبل-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83504.mp3","categories":["الغسل"]},{"id":17397,"question":"تقول: عندما تريد المرأة أن تغتسل للطهارة هل يلزمها الوضوء أولًا؟","title":"ما حكم الوضوء قبل الغسل؟","answer":"الجواب: السنة الوضوء، إذا كان عن حيض، أو جنابة الوضوء أولًا، تستنتجي إن كان في غسل الحيض، والجنابة، تستنجي، ثم تتوضأ وضوء الصلاة، تمضمض، وتستنشق، وتغسل وجهها، وذراعيها مع المرفقين، ثم تمسح وجهها، وأذنيها، ثم تغسل رجليها، هذا هو الأفضل، كان النبي يفعله في غسل الجنابة -عليه الصلاة والسلام- وربما ترك القدمين إلى آخر الغسل، ربما غسل وجهه، ويديه، ومسح رأسه، وأخر رجليه، هذا جائز وهذا جائز. والمرأة الحائض كذلك، فإن بدأت بالغسل، أو بدأ الجنب بالغسل، ثم تتوضأ بعد ذلك فلا بأس، لكن الأفضل أن يكون الوضوء هو الأول، يستنجي، وهكذا المرأة الحائض، والجنب تستنجي، ثم وضوء الصلاة، ثم الغسل يحثي على رأسه ثلاثًا، وهي كذلك، ثم يفيض على جنبه الأيمن، ثم الأيسر، والمرأة كذلك، هذا هو السنة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16266/ما-حكم-الوضوء-قبل-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83504.mp3","categories":["الغسل"]},{"id":17678,"question":"يقول السائل: هل المضمضة والاستنشاق واجبة أثناء الغسل من الجنابة؟","title":"حكم المضمضة والاستنشاق أثناء الغسل","answer":"الجواب: نعم المضمضة والاستنشاق واجبتان في الغسل من الجنابة والغسل من الحيض وفي الوضوء الشرعي لابد من المضمضة في الوضوء والغسل من الجنابة والغسل من الحيض والنفاس، لابد من ذلك. نعم؛ لأنهما في حكم الوجه. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16611/حكم-المضمضة-والاستنشاق-اثناء-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59507.mp3","categories":["الغسل"]},{"id":17733,"question":"هذا المستمع (ع. م) يقول سماحة الشيخ: شخص وضع على يده جبيرة وأصابته جنابة، واغتسل منها، ثم بعد ذلك نزع الجبيرة، فهل يجب عليه أن يغسل يده التي كانت عليها الجبيرة؟ أم يجب إعادة الغسل للجنابة؟","title":"حكم من اغتسل من جنابة وفي يده جبيرة","answer":"الجواب: ......... الجبيرة تقوم مقام الغسل ما تحتها، ............... طاهر ... به؛ لأن المسح عليها ضروري، أما الخف لا، لا يمسح على الخف وهو عليه جنابة، ......... يخلع، أما الجبيرة يمسح عليها ولو في الجنابة ولو في الحيض، فإذا برئ ما تحتها لم يجب الغسل، بل يتوضأ كالعادة ويغسل كالعادة في بقية أوقاته، زال حكمها. نعم.","link":"https://binbaz.org.sa/fatwas/16690/حكم-من-اغتسل-من-جنابة-وفي-يده-جبيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59601.mp3","categories":["الغسل"]},{"id":17736,"question":"يقول السائل رجل وامرأة اغتسل واغتسلت المرأة غسلًا واجبًا، ولكنهما وجدا بعد ذلك لمعة في جسده لم يصلها الماء، فهل يجب عليهما إعادة الغسل؟","title":"حكم من وجد بعد الغسل لمعة لم يصلها الماء","answer":"الجواب: إذا تأكد وجود لمعة تغسل اللمعة فقط اللمعة. نعم.","link":"https://binbaz.org.sa/fatwas/16691/حكم-من-وجد-بعد-الغسل-لمعة-لم-يصلها-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59602.mp3","categories":["الغسل"]},{"id":17752,"question":"يقول أيضًا من أسئلته: عند الغسل من الجنابة، هل يجب على المرأة أن تغسل وتخلل جميع شعر رأسها؟","title":"حكم نقض المرأة شعر رأسها لغسل الجنابة","answer":"الجواب: عليها أن تعمه بالماء، ولا يلزمها النقض، تعمه بالماء ويكفي والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/16723/حكم-نقض-المراة-شعر-راسها-لغسل-الجنابة","audio":"","categories":["الغسل","قضايا المرأة"]},{"id":18492,"question":"أرجو الاطلاع على مسألتي هذه والإجابة عليها؛ حيث أنني أسأل عن الحكم في لو كان شخص في مكان لا يوجد به ماء كاف للغسل من الجنابة، ووجد شيئًا قليلًا ما الحكم؟ أرجو إرشادي جزاكم الله خيرًا.","title":"حكم من لم يجد ماء يكفيه لغسل الجنابة","answer":"الجواب: يقول الله سبحانه فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، ويقول النبي ﷺ: إذا أمرتكم بأمر فأتوا منه ما استطعتم، فإذا كان الإنسان في مكان ليس فيه إلا ماء قليل لا يكفي للغسل فإنه يغسل به ما أمكن من جسده ثم يتيمم للباقي؛ لأنه معذور، كالذي في البرية، أو في سجن لا يعطى ماء إلا لشربه، وليس عنده ماء يكفيه للغسل ولا يعطى ماء للغسل؛ فإنه يغتسل بالذي عنده فيغسل بعض بدنه كرأسه وصدره ونحو ذلك ويستنجي منه ويتيمم للباقي، يعني: يضرب التراب بيديه بنية الطهارة، ويمسح بهما وجهه وكفيه عن بقية بدنه، ناويًا بذلك الطهارة من الجنابة، وإن نوى الطهارة من الجنابة وجميع الأحداث صح ذلك وصارت طهارته كاملة عن الحدث الأكبر والأصغر جميعًا عملًا بقوله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. وإذا كان الماء الذي عنده يحتاجه للشرب ويخشى من العطش؛ فإنه لا يغتسل به، بل يتيمم عن الجميع، ويبقى الماء عنده لحاجته عملًا بقوله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وعملًا بقوله : وَلا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ [البقرة:195]. نعم.","link":"https://binbaz.org.sa/fatwas/17586/حكم-من-لم-يجد-ماء-يكفيه-لغسل-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_867/nour_86703.mp3","categories":["الغسل"]},{"id":18566,"question":"تقول: إذا وجب الغسل على المرأة في الليل في ليالي رمضان؛ لكنها لم تغتسل إلا في النهار، فماذا عليها؟ جزاكم الله خيرًا.","title":"حكم تأخير غسل الجنابة بعد طلوع الشمس في رمضان","answer":"الجواب: هذا فيه تفصيل: إن كانت أخرت الغسل حتى طلع الفجر فلا يضر الصوم صحيح تصوم تغتسل، والحمد لله، المحرم الجماع إذا كان الجماع في الليل قبل الفجر، ولكن تأخر غسلها، أو غسل الزوج حتى طلع الفجر فلا مانع، كان النبي ﷺ يأتي أهله في الليل، ويصبح صائمًا ويغتسل بعد الصبح، كما أخبرت عائشة وأم سلمة عن ذلك كان يصبح جنبًا من جماع ثم يغتسل ويصوم عليه الصلاة والسلام. فتأخير الغسل إلى بعد طلوع الفجر أمر لا حرج فيه، لا من الرجل ولا من المرأة إذا كان الجماع في الليل، أما لو أخر الغسل أو أخرت الغسل إلى طلوع الشمس هذا لا يجوز؛ لأن معناه تأخير الصلاة. فالواجب أن يبادر بالغسل في الوقت حتى تؤدى الصلاة في الوقت، وحتى يؤدي الرجل الصلاة في الوقت، وفي الجماعة مع إخوانه والصوم صحيح بكلها الصوم صحيح؛ ما دام الجماع حصل في الليل إنما تأخر الغسل فالصوم صحيح. ولكن على المرأة وعلى الرجل الغسل في الوقت، والبدار بذلك حتى تؤدى الصلاة في الوقت قبل طلوع الشمس، والرجل يبادر بذلك حتى يؤدي الصلاة مع الجماعة في مساجد الله، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17680/حكم-تاخير-غسل-الجنابة-بعد-طلوع-الشمس-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_734/nour_73402.mp3","categories":["الغسل"]},{"id":18740,"question":"هل يجوز للمرأة تخليل شعرها بالماء سبع مرات أثناء الغسل من الجنابة دون أن تصب الماء على شعرها؟","title":"حكم اكتفاء المرأة بتخليل شعرها أثناء الغسل دون صب الماء","answer":"الجواب: لا يكفي ذلك، لا بد من صب الماء على شعرها ثلاثًا، النبي ﷺ أمر بأن تحثي عليه ثلاث حثيات، أما إذا كانت واحدة، لكن عمت الرأس؛ أجزأت، تعمه، أما مجرد التخليل بدون صب الماء فلا يكفي، لا بد من صب الماء، لا بد من جريان الماء على الرأس، أما مجرد تخليله بأصابع فيها رطوبة تخلل، ولكن من غير صب الماء، لا، لا بد من صب الماء ولو مرة، لكن السنة ثلاث؛ لأن في حديث أم سلمة قالت: يا رسول الله، إني أشد شعر رأسي، أفأنقضه لغسل الجنابة؟ -وفي رواية: والحيضة؟ عند مسلم رحمه الله- قال: يكفيك أن تحثي على رأسك ثلاث حثيات، ثم تفيضي عليك الماء؛ فتطهرين. فبين لها ﷺ أنه يكفيها أن تحثي عليه ثلاث حثيات، فلو أنها روته بالماء من دون ثلاث حثيات، صبت عليه الماء؛ كفى، لكن ثلاث هو الأفضل كما قاله النبي -عليه الصلاة والسلام- وأكمل في الإبلاغ. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17877/حكم-اكتفاء-المراة-بتخليل-شعرها-اثناء-الغسل-دون-صب-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87506.mp3","categories":["الغسل"]},{"id":18877,"question":"أرجو الاطلاع على مسألتي هذه، والإجابة عليها؛ حيث أنني أسأل عن الحكم في لو كان شخص في مكان لا يوجد به ماء كافٍ للغسل من الجنابة، ووجد شيئًا قليلًا، ما الحكم؟أرجو إرشادي، جزاكم الله خيرًا.","title":"حكم الجنب الذي لا يجد ماءً كافيًا للغسل","answer":"الجواب: يقول الله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول النبي ﷺ: إذا أمرتكم بأمر؛ فأتوا منه ما استطعتم فإذا كان الإنسان في مكان ليس فيه إلا ماء قليل لا يكفي للغسل؛ فإنه يغسل به ما أمكن من جسده، ثم يتيمم للباقي؛ لأنه معذور، كالذي في البرية، أو في سجن لا يعطى ماءً إلا لشربه، وليس عنده ماء يكفيه للغسل، ولا يعطى ماء للغسل؛ فإنه يغتسل بالذي عنده، فيغسل بعض بدنه -كرأسه وصدره ونحو ذلك- ويستنجي منه، ويتيمم للباقي، يعني: يضرب التراب بيديه بنية الطهارة، ويسمح بهما وجهه وكفيه عن بقية بدنه، ناويًا بذلك الطهارة من الجنابة، وإن نوى الطهارة من الجنابة وجميع الأحداث صح ذلك، وصارت طهارته كاملة عن الحدث الأكبر والأصغر جميعًا، عملًا بقوله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. وإذا كان الماء الذي عنده يحتاجه للشرب، ويخشى من العطش؛ فإنه لا يغتسل به، بل يتيمم عن الجميع، ويبقى الماء عنده لحاجته؛ عملًا بقوله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وعملًا بقوله : وَلا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ [البقرة:195] نعم.","link":"https://binbaz.org.sa/fatwas/18021/حكم-الجنب-الذي-لا-يجد-ماء-كافيا-للغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_880/nour_88003.mp3","categories":["الغسل","الطهارة لصحة الصلاة"]},{"id":19501,"question":"من الجزائر يقول هذا السائل: وضحوا لنا الاغتسال من الجنابة والحيض؟","title":"حكم الغسل من الجنابة والحيض","answer":"الجواب: الاغتسال من الجنابة فرض لا بد منه، وهكذا من الحيض، فيجب على المسلم إذا أتى أهله أن يغتسل من الجنابة؛ لأن الله جل وعلا يقول: وَإِنْ كُنْتُمْ جُنُبًا فَاطَّهَّرُوا[المائدة:6] وهكذا المرأة، وهكذا من الحيض والنفاس إذا انتهى الدم، وانقطع الدم؛ ولو لأقل من أربعين؛ وجب على النفساء الاغتسال، وإذا انتهت أيام الحيض، ورأت الطهارة؛ تغتسل وجوبًا لقوله جل وعلا: فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ[البقرة:222]. والنبي ﷺ أمر الحائض والنفساء بالغسل، فإذا انتهت مدة حيضها وجب عليها الغسل، وإذا رأت الطهارة لأقل من ذلك وجب الغسل أيضًا، والنفساء كذلك إذا كملت الأربعين وجب الغسل، وإن رأت الطهارة قبل ذلك وجب عليها الغسل. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18751/حكم-الغسل-من-الجنابة-والحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94602.mp3","categories":["الغسل"]},{"id":19638,"question":"سماحة الشيخ تقول الأخت السائلة التي رمزت لاسمها بـ (أ. س. م) طالبة بالمدرسة الثانوية، تقول: سماحة الشيخ ما هو الغسل؟ وما هي أحكامه؟ وكيفيته؟ وهل إهماله أو بطلانه له تأثير بالنسبة لأداء الصلاة أو الصيام؟","title":"صفة الغسل وبيان أنواعه","answer":"الجواب: الغسل إفاضة على البدن كله هذا يسمى غسل، إذا أفاض الإنسان الماء على بدنه كله من رأسه إلى قدميه يسمى غسل، وهو واجب من الجنابة، وهكذا من الحيض إذا انتهت من الحيض ورأت الطهارة وجب عليها الغسل، وهكذا من النفاس إذا انقطع الدم ورأت الطهارة وجب الغسل من النفاس، هذه أغسال واجبة. أما غسل الجمعة مستحب، الرجل يغتسل عند ذهابه للجمعة هذا مستحب، الغسل من الحجامة، الغسل من غسل الميت، هذه أغسال مستحبة، أما الغسل الواجب غسل الجنابة للرجل وفي حق المرأة غسل الحيض والنفاس هذه أغسال واجبة. نعم. المقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18910/صفة-الغسل-وبيان-انواعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94925.mp3","categories":["الغسل"]}]
